INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('9f931c0d-a626-5000-a516-daf25adc64c3', 'team', 'Islamic Studio', 'bn', 'নামাজে মনোযোগ: খুশু ফিরিয়ে আনার উপায়', 'নামাজে দাঁড়ালেই মন অন্যদিকে চলে যায়? খুশু কী, কুরআন-হাদিসে এর গুরুত্ব, মনোযোগ হারানোর কারণ এবং ধাপে ধাপে মনোযোগী নামাজ গড়ে তোলার বাস্তব পরামর্শ।', '<p>আমরা অনেকেই একটা অভিজ্ঞতার সাথে পরিচিত: আল্লাহু আকবার বলে নামাজে দাঁড়ালাম, আর সালাম ফেরানোর পর টের পেলাম পুরো সময়টা মন ছিল অফিসের কাজে, বাজারের হিসাবে বা ফোনের কোনো নোটিফিকেশনে। কোন রাকআতে কোন সূরা পড়েছি, তাও মনে নেই। এই অভিজ্ঞতা যতটা সাধারণ, ততটাই বেদনাদায়ক। কারণ নামাজ আল্লাহর সাথে বান্দার সরাসরি সাক্ষাৎ, আর সেই সাক্ষাতে আমরা উপস্থিত থাকি শুধু শরীরে।</p><p>ভালো খবর হলো, খুশু বা নামাজে মনোযোগ এমন কোনো গুণ নয় যা কারও আছে আর কারও নেই। এটি চর্চার মাধ্যমে বাড়ে। আজকের লেখায় আমরা দেখব খুশু কী, এর গুরুত্ব কতখানি, কেন মনোযোগ হারিয়ে যায় এবং কীভাবে ধীরে ধীরে তা ফিরিয়ে আনা যায়।</p><h2>খুশু কী?</h2><p>খুশু মানে অন্তরের বিনয়, স্থিরতা ও উপস্থিতি। আলেমরা বলেন, খুশুর মূল জায়গা অন্তর, আর তার প্রভাব পড়ে শরীরে। যার অন্তর আল্লাহর ভয় ও ভালোবাসায় নত, তার দৃষ্টি স্থির থাকে, অঙ্গপ্রত্যঙ্গ শান্ত থাকে, অপ্রয়োজনীয় নড়াচড়া কমে যায়। খুশু মানে শুধু চোখ বন্ধ করে দাঁড়িয়ে থাকা নয়; বরং যা পড়ছি তা বুঝে, যাঁর সামনে দাঁড়িয়েছি তাঁকে মনে রেখে নামাজ আদায় করা।</p><h2>কুরআনে খুশুর মর্যাদা</h2><p>সূরা আল-মুমিনুনের শুরুতেই আল্লাহ তাআলা ঘোষণা করেছেন, মুমিনরা সফল হয়েছে, যারা নিজেদের নামাজে বিনয়ী ও মনোযোগী (সূরা আল-মুমিনুন ২৩:১-২)। লক্ষ করুন, সফল মুমিনদের গুণাবলির তালিকা শুরু হয়েছে নামাজের খুশু দিয়ে। আরেক জায়গায় আল্লাহ বলেছেন, তোমরা ধৈর্য ও নামাজের মাধ্যমে সাহায্য চাও; আর নিশ্চয়ই তা কঠিন, তবে বিনয়ীদের জন্য নয় (সূরা আল-বাকারা ২:৪৫)। অর্থাৎ যার অন্তরে খুশু আছে, তার কাছে নামাজ বোঝা নয়, বরং আশ্রয়।</p><p>অন্যদিকে আল্লাহ সতর্ক করেছেন সেই নামাজিদের ব্যাপারে, যারা নিজেদের নামাজ সম্পর্কে উদাসীন (সূরা আল-মাউন ১০৭:৪-৫)। আলেমরা ব্যাখ্যা করেছেন, এই উদাসীনতার মধ্যে নামাজকে গুরুত্বহীন মনে করা, সময় নষ্ট করা এবং অবহেলা করে আদায় করাও অন্তর্ভুক্ত। তাই খুশুর প্রশ্নটি নিছক সৌন্দর্যের বিষয় নয়, ঈমানের গভীরতার বিষয়।</p><h2>হাদিসে খুশুর শিক্ষা</h2><p>জিবরাইল (আ.)-এর প্রসিদ্ধ হাদিসে রাসূল ﷺ ইহসানের সংজ্ঞা দিয়েছেন: তুমি আল্লাহর ইবাদত এমনভাবে করবে যেন তুমি তাঁকে দেখছ; আর যদি তুমি তাঁকে না দেখো, তবে তিনি তো তোমাকে দেখছেন (সহীহ বুখারী ৫০, সহীহ মুসলিম ৮)। খুশুর মূল চাবি এই হাদিসেই লুকিয়ে আছে। নামাজে দাঁড়িয়ে যদি মনে রাখি, আল্লাহ আমাকে দেখছেন, শুনছেন, তাহলে অন্তর আপনাআপনি নত হয়ে আসে।</p><p>একবার এক ব্যক্তি তাড়াহুড়া করে নামাজ পড়লে রাসূল ﷺ তাকে বললেন, ফিরে যাও, আবার নামাজ পড়ো, কারণ তুমি নামাজ পড়োনি। এভাবে তিনবার হওয়ার পর রাসূল ﷺ তাকে শিখিয়ে দিলেন, প্রতিটি রুকনে স্থির হতে হবে: রুকুতে স্থির হও, তারপর সোজা হয়ে দাঁড়াও, তারপর সিজদায় স্থির হও (সহীহ বুখারী ৭৫৭, সহীহ মুসলিম ৩৯৭)। এই স্থিরতা বা তুমানিনা খুশুর শারীরিক ভিত্তি। যে নামাজে শরীর তাড়াহুড়ায় থাকে, সেখানে মন স্থির হওয়া কঠিন।</p><p>নামাজে এদিক-ওদিক তাকানো সম্পর্কে আয়েশা (রা.) প্রশ্ন করলে রাসূল ﷺ বলেছিলেন, এটি এক ধরনের ছিনতাই, যা শয়তান বান্দার নামাজ থেকে ছিনিয়ে নেয় (সহীহ বুখারী ৭৫১)। আর উসমান (রা.) বর্ণিত হাদিসে আছে, যে ব্যক্তি সুন্দরভাবে অজু করে দুই রাকআত নামাজ পড়ে, যাতে সে মনে মনে অন্য কথা বলে না, তার পূর্বের গুনাহ মাফ করে দেওয়া হয় (সহীহ বুখারী ১৫৯, সহীহ মুসলিম ২২৬)। মনোযোগী দুই রাকআতের এত বড় পুরস্কার!</p><h2>কেন মনোযোগ হারিয়ে যায়?</h2><ul><li><strong>অর্থ না বোঝা:</strong> আমরা যা পড়ি তার অর্থ না জানলে মন সহজেই অন্য দিকে চলে যায়। মুখ চলে অভ্যাসে, মন চলে নিজের পথে।</li><li><strong>তাড়াহুড়া:</strong> জামাত ধরতে দৌড়ে আসা, বা নামাজ শেষ করে কাজে ফেরার তাড়া নামাজকে একটা "কাজ" বানিয়ে ফেলে।</li><li><strong>পরিবেশের বিঘ্ন:</strong> সামনে টিভি চলছে, পাশে ফোন বাজছে, জায়নামাজে চোখ টানা নকশা—এসব মনকে বারবার টেনে নেয়।</li><li><strong>শারীরিক চাহিদা:</strong> রাসূল ﷺ বলেছেন, খাবার উপস্থিত থাকলে এবং প্রস্রাব-পায়খানার বেগ চেপে রেখে নামাজ নেই (সহীহ মুসলিম ৫৬০)। অর্থাৎ যে জিনিস মনকে টানে, তা আগে সেরে নেওয়াই সুন্নাহর শিক্ষা।</li><li><strong>নামাজের বাইরের জীবন:</strong> সারা দিন যে অন্তর গুনাহ, অনর্থক কথা আর স্ক্রিনে ডুবে থাকে, নামাজে দাঁড়িয়ে সেই অন্তর হঠাৎ শান্ত হবে, এমন আশা করা কঠিন।</li></ul><h2>মনোযোগ ফিরিয়ে আনার বাস্তব উপায়</h2><h3>নামাজের আগে</h3><ul><li><strong>অজুকে প্রস্তুতি বানান:</strong> ধীরে, যত্ন নিয়ে অজু করুন। অজুর সময়েই মনকে বলুন, এখন আমি আল্লাহর সামনে দাঁড়াতে যাচ্ছি।</li><li><strong>আজান থেকে নামাজ পর্যন্ত সময় নিন:</strong> শেষ মুহূর্তে দৌড়ে না গিয়ে কয়েক মিনিট আগে প্রস্তুত হোন। সুন্নাত নামাজ মনকে ফরজের জন্য তৈরি করে।</li><li><strong>ফোন দূরে রাখুন:</strong> নামাজের সময় ফোন নিঃশব্দ করে অন্য ঘরে রাখলে মনের একটা বড় টান কমে যায়।</li><li><strong>সাদামাটা জায়গা বেছে নিন:</strong> যে জায়গায় চোখ টানার মতো কিছু নেই, সেখানে নামাজ পড়ুন।</li></ul><h3>নামাজের ভেতরে</h3><ul><li><strong>সিজদার জায়গায় দৃষ্টি:</strong> দাঁড়ানো অবস্থায় দৃষ্টি সিজদার জায়গায় রাখলে মন সহজে স্থির থাকে।</li><li><strong>অর্থ জেনে পড়ুন:</strong> সূরা ফাতিহা, রুকু-সিজদার তাসবিহ, তাশাহহুদ—এগুলোর অর্থ একবার ভালো করে শিখে নিন। তখন প্রতিটি শব্দ মনের কাছে একটি বার্তা হয়ে উঠবে।</li><li><strong>ফাতিহাকে সংলাপ হিসেবে পড়ুন:</strong> সহীহ মুসলিমের একটি হাদিসে (৩৯৫) এসেছে, বান্দা যখন ফাতিহার প্রতিটি আয়াত পড়ে, আল্লাহ তার জবাব দেন। আয়াতে আয়াতে একটু থেমে পড়ুন, যেন জবাব শোনার অপেক্ষা করছেন।</li><li><strong>সূরা বদলান:</strong> সবসময় একই দুটি ছোট সূরা পড়লে মুখ অভ্যাসে চলে। মাঝে মাঝে নতুন মুখস্থ করা সূরা পড়ুন।</li><li><strong>প্রতিটি রুকনে স্থির হোন:</strong> রুকু ও সিজদায় তাসবিহ ধীরে পড়ুন, রুকু থেকে উঠে পুরো সোজা হয়ে দাঁড়ান, দুই সিজদার মাঝে একটু বসুন।</li><li><strong>মন সরে গেলে আবার ফেরান:</strong> মন অন্য দিকে চলে যাওয়া স্বাভাবিক। হতাশ না হয়ে যতবার টের পাবেন, ততবার আলতো করে ফিরিয়ে আনুন। এই ফিরিয়ে আনাটাই চর্চা।</li></ul><h3>নামাজের পরে ও বাইরে</h3><ul><li>সালাম ফিরিয়েই উঠে না গিয়ে নামাজের পরের জিকিরগুলো পড়ুন; এতে নামাজের প্রশান্তি কিছুক্ষণ ধরে থাকে।</li><li>দিনের বাকি সময় গুনাহ ও অনর্থক কাজ কমানোর চেষ্টা করুন। নামাজের মান অনেকটাই নির্ভর করে নামাজের বাইরের জীবনের ওপর।</li><li>আল্লাহর কাছে খুশুর জন্য দোয়া করুন। মনোযোগও আল্লাহরই দান।</li></ul><h2>একটি সহজ সাপ্তাহিক পরিকল্পনা</h2><p>সব একসাথে করতে গেলে হাঁপিয়ে উঠবেন। তাই প্রতি সপ্তাহে একটি দিকেই মন দিন। প্রথম সপ্তাহে শুধু সূরা ফাতিহার অর্থ ভালো করে শিখুন এবং প্রতিটি নামাজে তা মনে রেখে পড়ুন। দ্বিতীয় সপ্তাহে রুকু-সিজদার তাসবিহের অর্থ। তৃতীয় সপ্তাহে তাশাহহুদ ও দরুদ। চতুর্থ সপ্তাহে একটি নতুন ছোট সূরা অর্থসহ। এক মাস পর দেখবেন, নামাজ আগের চেয়ে অনেক বেশি জীবন্ত লাগছে।</p><blockquote>নামাজ যদি আল্লাহর সাথে সাক্ষাৎ হয়, তবে সেই সাক্ষাতে শুধু শরীর নয়, অন্তরকেও নিয়ে যান।</blockquote><p>মনে রাখবেন, খুশু একদিনে আসে না, আর একবার এলেই চিরস্থায়ী হয়ে যায় না। কোনো দিন ভালো যাবে, কোনো দিন মন বারবার পালাবে। কিন্তু যে চেষ্টা চালিয়ে যায়, আল্লাহ তার চেষ্টার মূল্য দেন। ইসলামিক স্টুডিওর লার্ন অংশে নামাজের দোয়াগুলোর অর্থ দেখে নিন, আর আজকের পরের নামাজেই একটি নতুন অভ্যাস শুরু করুন।</p>', ARRAY['salah', 'khushu', 'tazkiyah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('5aa67dfa-de6f-55c4-a254-94aa576aea8e', 'team', 'Islamic Studio', 'bn', 'সন্তানকে নামাজে অভ্যস্ত করবেন যেভাবে', 'ভয় দেখিয়ে নয়, ভালোবাসা ও উদাহরণ দিয়ে কীভাবে সন্তানের মনে নামাজের প্রতি টান তৈরি করা যায়: বয়স অনুযায়ী ধাপ, সুন্নাহর শিক্ষা ও বাবা-মায়ের সাধারণ ভুল।', '<p>প্রত্যেক মুসলিম বাবা-মায়ের স্বপ্ন, সন্তান বড় হয়ে নামাজি হবে। কিন্তু বাস্তবে দেখা যায়, অনেক পরিবারে নামাজ নিয়ে প্রতিদিন একটা টানাপোড়েন চলে: "নামাজ পড়েছ?", "এখনো ওঠোনি?", "আর কতবার বলব?" কখনো বকাঝকা, কখনো অভিমান। এভাবে চলতে চলতে অনেক সন্তানের কাছে নামাজ হয়ে যায় বাবা-মাকে খুশি রাখার একটা দায়িত্ব, আল্লাহর সাথে সম্পর্ক নয়। আর বাবা-মায়ের চোখের আড়াল হলেই সেই দায়িত্বও হারিয়ে যায়।</p><p>সন্তানকে নামাজে অভ্যস্ত করা একটা দীর্ঘ যাত্রা। এই যাত্রা শুরু হয় সন্তানের জন্মের অনেক আগেই, বাবা-মায়ের নিজের নামাজ থেকে।</p><h2>কুরআন ও সুন্নাহর নির্দেশনা</h2><p>আল্লাহ তাআলা তাঁর নবীকে বলেছেন, তোমার পরিবারকে নামাজের আদেশ দাও এবং নিজেও তাতে অবিচল থাকো (সূরা ত্বা-হা ২০:১৩২)। লক্ষ করুন, আদেশের সাথেই এসেছে ধৈর্যের কথা। অর্থাৎ এটা একবার বলে দেওয়ার কাজ নয়, বারবার, ধৈর্যের সাথে করার কাজ। আরেক আয়াতে আল্লাহ মুমিনদের বলেছেন নিজেদের ও পরিবারকে আগুন থেকে বাঁচাতে (সূরা আত-তাহরিম ৬৬:৬)।</p><p>লুকমান (আ.) তাঁর ছেলেকে যে উপদেশ দিয়েছিলেন, তার মধ্যে ছিল নামাজ কায়েম করা, সৎকাজের আদেশ দেওয়া এবং বিপদে ধৈর্য ধরা (সূরা লুকমান ৩১:১৭)। এই উপদেশের পুরো অংশটি পড়লে দেখা যায়, লুকমান (আ.) আদেশের ভাষায় নয়, স্নেহের ভাষায় কথা বলছেন: "হে আমার প্রিয় বৎস"।</p><p>রাসূল ﷺ বলেছেন, তোমাদের সন্তানদের সাত বছর বয়সে নামাজের আদেশ দাও, দশ বছর বয়সে নামাজের জন্য শাসন করো এবং তাদের বিছানা আলাদা করে দাও (সুনান আবি দাউদ ৪৯৫)। আলেমরা এই হাদিস থেকে একটি গুরুত্বপূর্ণ বিষয় বের করেছেন: সাত থেকে দশ বছর, অর্থাৎ প্রায় তিন বছর সময় দেওয়া হয়েছে শুধু শেখানো ও উৎসাহ দেওয়ার জন্য। আর শাসনের কথা এসেছে শেষ ধাপে; আলেমদের ব্যাখ্যায় তা হালকা, আঘাতহীন এবং কেবল দায়িত্ববোধ জাগানোর জন্য, রাগ মেটানোর জন্য নয়। আজকের বাস্তবতায় অনেক অভিজ্ঞ আলেম ও শিক্ষক পরামর্শ দেন, শাসন বলতে প্রথমে পছন্দের কিছু সাময়িক বন্ধ রাখা, আলোচনা ও দায়িত্ব বুঝিয়ে দেওয়াকেই বেছে নিতে।</p><h2>সবচেয়ে বড় শিক্ষক: আপনার নিজের নামাজ</h2><p>শিশুরা যা শোনে তার চেয়ে অনেক বেশি শেখে যা দেখে। বাবা যদি আজান শুনে টিভি বন্ধ করে মসজিদে যান, মা যদি রান্না থামিয়ে জায়নামাজ বিছান, তাহলে শিশু কোনো ভাষণ ছাড়াই বুঝে নেয় যে নামাজ এই বাড়ির সবচেয়ে গুরুত্বপূর্ণ কাজ। আর যদি বাবা-মা নিজেরা নামাজ কাজা করেন অথচ সন্তানকে বকেন, শিশু শেখে যে নামাজ শুধু ছোটদের জন্য একটা নিয়ম।</p><p>রাসূল ﷺ নিজে শিশুদের নামাজের পরিবেশে রাখতেন। তিনি তাঁর নাতনি উমামাকে কাঁধে নিয়ে নামাজ পড়েছেন; সিজদায় গেলে নামিয়ে রাখতেন, দাঁড়ালে আবার তুলে নিতেন (সহীহ বুখারী ৫১৬, সহীহ মুসলিম ৫৪৩)। তিনি বলেছেন, আমি নামাজ দীর্ঘ করার ইচ্ছা নিয়ে দাঁড়াই, তারপর শিশুর কান্না শুনে নামাজ সংক্ষিপ্ত করি, কারণ তার মায়ের কষ্ট হবে তা আমি অপছন্দ করি (সহীহ বুখারী ৭০৭)। অর্থাৎ নবীজির মসজিদে শিশুরা ছিল, এবং তাদের উপস্থিতি নিয়ে বিরক্তি নয়, সহমর্মিতা ছিল।</p><h2>বয়স অনুযায়ী ধাপ</h2><h3>০-৬ বছর: ভালোবাসা ও পরিবেশ</h3><ul><li>শিশুকে পাশে রেখে নামাজ পড়ুন। সে নকল করে রুকু-সিজদা দিলে হাসিমুখে উৎসাহ দিন।</li><li>তার জন্য ছোট একটা নিজস্ব জায়নামাজ ও টুপি বা ওড়না কিনে দিন। নিজের জিনিস শিশুকে আগ্রহী করে।</li><li>আল্লাহর নিয়ামতের গল্প বলুন: কে আমাদের খাবার দেন, কে বৃষ্টি দেন। নামাজকে বলুন আল্লাহকে "ধন্যবাদ" বলার উপায়।</li><li>সূরা ফাতিহা ও ছোট সূরাগুলো খেলার ছলে মুখস্থ করান।</li></ul><h3>৭-৯ বছর: শেখানো ও উৎসাহ</h3><ul><li>অজু ও নামাজের নিয়ম হাতে-কলমে শেখান। ভুল হলে হাসাহাসি নয়, ধীরে ঠিক করে দিন।</li><li>প্রথমে দিনে এক-দুই ওয়াক্ত দিয়ে শুরু করুন, তারপর ধীরে ধীরে পাঁচ ওয়াক্তে নিন।</li><li>একটা চার্ট বানান; প্রতিটি নামাজে একটা স্টিকার। সপ্তাহ শেষে ছোট একটা পুরস্কার বা পরিবারের সাথে প্রিয় কোনো কাজ।</li><li>ছেলে সন্তানকে বাবার সাথে মসজিদে নিয়ে যান, বিশেষ করে জুমায়। মসজিদের আদব আগে শিখিয়ে নিন।</li></ul><h3>১০ বছর ও তার পরে: দায়িত্ব ও বোঝাপড়া</h3><ul><li>এখন নামাজ "তোমার নিজের দায়িত্ব"—এটা পরিষ্কার করে বলুন, সম্মানের সাথে।</li><li>নামাজের অর্থ ও উদ্দেশ্য নিয়ে কথা বলুন। কিশোর মন "কেন" জানতে চায়; প্রশ্নকে স্বাগত জানান।</li><li>নামাজ মিস করলে প্রকাশ্যে লজ্জা দেবেন না। আলাদা করে, শান্তভাবে কথা বলুন।</li><li>তাকে কখনো কখনো ঘরের জামাতে ইমাম বানান। দায়িত্ব পেলে কিশোররা গর্ব বোধ করে।</li></ul><h2>বাবা-মায়ের সাধারণ ভুল</h2><ul><li><strong>নামাজকে শাস্তির সাথে জুড়ে দেওয়া:</strong> "দুষ্টুমি করলে দুই রাকআত বেশি পড়বে"—এতে নামাজ শাস্তি হয়ে যায়।</li><li><strong>শুধু জাহান্নামের ভয় দেখানো:</strong> ভয় দরকার, কিন্তু শুধু ভয় দিয়ে ভালোবাসা জন্মায় না। আল্লাহর দয়া, জান্নাত ও নবীজির ভালোবাসার কথাও বলুন।</li><li><strong>অন্যের সন্তানের সাথে তুলনা:</strong> "দেখো ওর ছেলে কত নামাজি!" তুলনা বিরক্তি আর হীনম্মন্যতা তৈরি করে।</li><li><strong>অসংগতি:</strong> আজ কঠোর, কাল কিছুই না। শিশুরা ধারাবাহিক নিয়ম থেকেই অভ্যাস গড়ে।</li><li><strong>দোয়া ভুলে যাওয়া:</strong> ইবরাহিম (আ.) নিজের ও বংশধরদের জন্য নামাজ কায়েমকারী হওয়ার দোয়া করেছেন (সূরা ইবরাহিম ১৪:৪০)। আমাদেরও প্রতিদিন এই দোয়া করা উচিত।</li></ul><h2>যে সন্তান বড় হয়ে নামাজ ছেড়ে দিয়েছে</h2><p>অনেক বাবা-মা লেখেন, সন্তান কৈশোরে বা তরুণ বয়সে নামাজ ছেড়ে দিয়েছে। এ অবস্থায় রাগ, অপমান বা সম্পর্ক ছিন্ন করা কাজে আসে না; বরং দূরত্ব বাড়ায়। সম্পর্কটা উষ্ণ রাখুন, তার কথা শুনুন, তার জীবনের চাপগুলো বুঝুন। সময় সুযোগমতো আন্তরিকভাবে মনে করিয়ে দিন, আর সবচেয়ে বেশি দোয়া করুন। হৃদয়ের মালিক আল্লাহ; আমাদের কাজ চেষ্টা আর দোয়া।</p><blockquote>সন্তানকে নামাজ শেখানোর সবচেয়ে কার্যকর বাক্য হলো: "চলো, একসাথে পড়ি।"</blockquote><p>রাসূল ﷺ বলেছেন, তোমরা প্রত্যেকেই দায়িত্বশীল এবং প্রত্যেককে তার দায়িত্ব সম্পর্কে জিজ্ঞাসা করা হবে (সহীহ বুখারী ৮৯৩, সহীহ মুসলিম ১৮২৯)। সন্তানের নামাজ সেই দায়িত্বের সবচেয়ে মূল্যবান অংশ। ইসলামিক স্টুডিওর শিশুদের অংশ ও কুইজ ব্যবহার করে খেলার ছলে নামাজের নিয়ম শেখাতে পারেন, আর ইবাদত ট্র্যাকারে পরিবারের সবাই মিলে নামাজের হিসাব রাখতে পারেন।</p>', ARRAY['salah', 'parenting', 'family', 'kids']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('ce4218d3-2db7-5ead-89cc-a404462dbbcb', 'team', 'Islamic Studio', 'bn', 'হালাল উপার্জন: দোয়া কবুলের পূর্বশর্ত', 'হালাল রুজি কেন ইবাদতের ভিত্তি, হারাম উপার্জন কীভাবে দোয়া ও আমলকে বাধাগ্রস্ত করে, আর চাকরি-ব্যবসায় হালাল নিশ্চিত করার বাস্তব কিছু প্রশ্ন ও পরামর্শ।', '<p>আমরা অনেক সময় দ্বীনদারিকে নামাজ, রোজা, দাড়ি-টুপি বা পর্দার মধ্যে সীমাবদ্ধ করে ফেলি। কিন্তু ইসলামে একজন মানুষের দ্বীনদারির বড় পরীক্ষা হয় তার পকেটে, তার লেনদেনে, তার মাসের শেষে হাতে আসা টাকায়। সেই টাকা কোথা থেকে এল, কীভাবে এল—এই প্রশ্ন আল্লাহর কাছে অত্যন্ত গুরুত্বপূর্ণ। কারণ হালাল উপার্জন শুধু অর্থনৈতিক বিষয় নয়; এটি ইবাদত কবুল হওয়ার, দোয়া কবুল হওয়ার এবং পরিবারে বরকত আসার ভিত্তি।</p><h2>কুরআনের নির্দেশ: হালাল ও পবিত্র</h2><p>আল্লাহ তাআলা সমগ্র মানবজাতিকে উদ্দেশ করে বলেছেন, পৃথিবীতে যা কিছু হালাল ও পবিত্র, তা থেকে খাও এবং শয়তানের পদাঙ্ক অনুসরণ করো না (সূরা আল-বাকারা ২:১৬৮)। আবার বিশেষভাবে মুমিনদের বলেছেন, আমি তোমাদের যে পবিত্র রিজিক দিয়েছি তা থেকে খাও এবং আল্লাহর শুকরিয়া আদায় করো (সূরা আল-বাকারা ২:১৭২)। লক্ষ করুন, দুই আয়াতেই "পবিত্র" শব্দটি এসেছে। শুধু বৈধ হলেই হবে না, উপার্জন হতে হবে পরিচ্ছন্ন, প্রতারণা ও জুলুমমুক্ত।</p><p>ব্যবসা-বাণিজ্যে প্রতারণার ব্যাপারে আল্লাহ কঠোর সতর্কবাণী দিয়েছেন: ধ্বংস তাদের জন্য যারা মাপে কম দেয়; যারা মানুষের কাছ থেকে নেওয়ার সময় পুরো নেয়, আর দেওয়ার সময় কম দেয় (সূরা আল-মুতাফফিফিন ৮৩:১-৩)। আর সুদের ব্যাপারে স্পষ্ট ঘোষণা: আল্লাহ ব্যবসাকে হালাল করেছেন এবং সুদকে হারাম করেছেন (সূরা আল-বাকারা ২:২৭৫)।</p><h2>যে হাদিস আমাদের কাঁপিয়ে দেয়</h2><p>রাসূল ﷺ বলেছেন, আল্লাহ পবিত্র, তিনি পবিত্র ছাড়া কিছু গ্রহণ করেন না। তারপর তিনি এক ব্যক্তির কথা বললেন, যে দীর্ঘ সফরে আছে, চুল এলোমেলো, শরীর ধুলোমলিন; সে আকাশের দিকে দুই হাত তুলে বলছে, হে রব, হে রব! অথচ তার খাবার হারাম, পানীয় হারাম, পোশাক হারাম এবং হারাম দিয়েই সে পুষ্ট হয়েছে। তাহলে তার দোয়া কীভাবে কবুল হবে (সহীহ মুসলিম ১০১৫)?</p><p>এই হাদিসে দোয়া কবুলের প্রায় সব বাহ্যিক কারণ উপস্থিত: সফর, অসহায় অবস্থা, হাত তোলা, আল্লাহকে বারবার ডাকা। তবু একটি কারণ সব নষ্ট করে দিয়েছে: হারাম রিজিক। আমরা যখন অভিযোগ করি, এত দোয়া করি তবু কবুল হয় না, তখন নিজের উপার্জনের দিকে একবার তাকানো দরকার।</p><h2>নিজের হাতের উপার্জনের মর্যাদা</h2><p>ইসলামে পরিশ্রম লজ্জার নয়, সম্মানের। রাসূল ﷺ বলেছেন, নিজের হাতের উপার্জনের চেয়ে উত্তম খাবার কেউ কখনো খায়নি; আর আল্লাহর নবী দাউদ (আ.) নিজের হাতের উপার্জন থেকে খেতেন (সহীহ বুখারী ২০৭২)। একজন রিকশাচালক, দিনমজুর বা ছোট দোকানদার যদি সততার সাথে উপার্জন করেন, তিনি সমাজের চোখে যেমনই হোন, আল্লাহর কাছে তাঁর রুজি সম্মানিত।</p><p>সৎ ব্যবসায়ীর মর্যাদা সম্পর্কে রাসূল ﷺ বলেছেন, সত্যবাদী ও আমানতদার ব্যবসায়ী নবী, সিদ্দিক ও শহিদদের সাথে থাকবেন (জামে তিরমিযী ১২০৯)। ভাবুন তো, দোকানে বসে সততার সাথে বেচাকেনা করাও জান্নাতে নবীদের সঙ্গ পাওয়ার পথ হতে পারে!</p><p>আর প্রতারণার ব্যাপারে রাসূল ﷺ-এর কঠোর অবস্থান: একবার তিনি বাজারে খাদ্যশস্যের একটি স্তূপে হাত ঢুকিয়ে দেখলেন ভেতরের অংশ ভেজা। বিক্রেতা বলল, বৃষ্টিতে ভিজেছে। তিনি বললেন, তাহলে ভেজা অংশ ওপরে রাখলে না কেন, যাতে মানুষ দেখতে পায়? যে প্রতারণা করে সে আমার দলভুক্ত নয় (সহীহ মুসলিম ১০২)।</p><h2>সন্দেহজনক বিষয় থেকে দূরে থাকা</h2><p>রাসূল ﷺ বলেছেন, হালাল স্পষ্ট এবং হারাম স্পষ্ট; আর এ দুয়ের মাঝে কিছু সন্দেহজনক বিষয় আছে, যা অনেক মানুষ জানে না। যে সন্দেহজনক বিষয় থেকে বেঁচে থাকল, সে তার দ্বীন ও সম্মান রক্ষা করল (সহীহ বুখারী ৫২, সহীহ মুসলিম ১৫৯৯)। আধুনিক অর্থনীতিতে অনেক লেনদেন জটিল—বিনিয়োগ, কিস্তি, বিমা, অনলাইন আয়ের নানা মাধ্যম। এসব ক্ষেত্রে নিজের ধারণার ওপর নির্ভর না করে নির্ভরযোগ্য আলেমের কাছ থেকে জেনে নেওয়াই নিরাপদ। যেখানে আলেমদের মধ্যে মতভেদ আছে, সেখানে বিশ্বস্ত আলেমের মত অনুসরণ করুন এবং সম্ভব হলে সতর্কতার দিকটি বেছে নিন।</p><h2>নিজেকে জিজ্ঞেস করার কিছু প্রশ্ন</h2><h3>চাকরিজীবীদের জন্য</h3><ul><li>অফিসের নির্ধারিত সময় কি আমি সত্যিই কাজে দিই, নাকি ব্যক্তিগত কাজে, আড্ডায় বা ফোনে কাটাই?</li><li>অফিসের জিনিসপত্র, গাড়ি, ইন্টারনেট কি ব্যক্তিগত কাজে অনুমতি ছাড়া ব্যবহার করি?</li><li>ভুয়া বিল, বাড়তি ভাতা বা "সবাই তো নেয়" বলে কোনো অনৈতিক সুবিধা নিচ্ছি কি?</li><li>ঘুষ বা উপহারের নামে কোনো সুবিধা গ্রহণ করছি কি, যা আমার পদের কারণে পাচ্ছি?</li></ul><h3>ব্যবসায়ীদের জন্য</h3><ul><li>মাপে ও ওজনে কি পুরো দিচ্ছি? পণ্যের দোষ কি ক্রেতাকে জানাচ্ছি?</li><li>মিথ্যা কসম খেয়ে কি পণ্য বিক্রি করছি?</li><li>ভেজাল, মজুতদারি বা কৃত্রিম সংকট তৈরি করে দাম বাড়াচ্ছি কি?</li><li>কর্মচারীদের বেতন কি সময়মতো ও ন্যায্যভাবে দিচ্ছি?</li></ul><h3>সবার জন্য</h3><ul><li>আমার কোনো আয় কি সুদের সাথে জড়িত?</li><li>কারও পাওনা, ঋণ বা উত্তরাধিকারের অংশ কি আটকে রেখেছি?</li><li>অনলাইনে "সহজ আয়"-এর নামে জুয়া বা প্রতারণামূলক স্কিমে জড়িয়ে পড়েছি কি?</li></ul><h2>যদি অতীতে হারাম উপার্জন হয়ে থাকে</h2><p>কেউ যদি বুঝতে পারেন অতীতে হারাম উপার্জন হয়েছে, তাহলে হতাশ না হয়ে তওবা করুন। আলেমরা সাধারণভাবে বলেন, তওবার অংশ হলো সেই উপার্জন থেকে বের হয়ে আসা: কারও হক নষ্ট করে থাকলে যতটা সম্ভব তাকে ফিরিয়ে দেওয়া বা ক্ষমা চেয়ে নেওয়া, আর যা ফেরত দেওয়ার মালিক পাওয়া যায় না, তা থেকে নিজেকে মুক্ত করা। বিস্তারিত পদ্ধতি পরিস্থিতিভেদে আলাদা হয়, তাই একজন বিজ্ঞ আলেমের সাথে পরামর্শ করুন। আল্লাহর দরজা তওবাকারীর জন্য সবসময় খোলা।</p><h2>অল্প হালাল, অনেক বরকত</h2><p>হালাল পথে চলতে গিয়ে অনেক সময় আয় কম মনে হয়। পাশের সহকর্মী "উপরি" দিয়ে গাড়ি-বাড়ি করছে, আর আমি মাসের শেষে টানাটানিতে। এই সময় মনে রাখা দরকার, কিয়ামতের দিন প্রত্যেককে জিজ্ঞাসা করা হবে তার সম্পদ সম্পর্কে, কোথা থেকে উপার্জন করেছে আর কোথায় ব্যয় করেছে (জামে তিরমিযী ২৪১৭)। হারামের প্রাচুর্য সেদিন বোঝা হবে, আর হালালের অল্পও হবে প্রশান্তি।</p><blockquote>রিজিকের পরিমাণ আল্লাহ নির্ধারণ করেছেন; পথটা বেছে নেওয়ার দায়িত্ব আমাদের।</blockquote><p>হালাল উপার্জনের চেষ্টা নিজেই একটি ইবাদত। যিনি পরিবারের মুখে হালাল খাবার তুলে দিতে সারা দিন পরিশ্রম করেন, তাঁর প্রতিটি ঘামের ফোঁটা আল্লাহর কাছে হিসাব করা থাকে। আজই নিজের উপার্জনের খাতাটা একবার খুলে দেখুন, আর যেখানে সন্দেহ আছে, সেখানে পরিষ্কার হওয়ার নিয়ত করুন।</p>', ARRAY['halal', 'rizq', 'business', 'akhlaq']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('5dd88c9c-5a8c-523d-87dc-3925be748496', 'team', 'Islamic Studio', 'bn', 'রমজানের প্রস্তুতি: শাবান থেকেই শুরু', 'রমজান আসার আগেই কীভাবে মন, শরীর, পরিবার ও কাজকর্ম প্রস্তুত করবেন: রোজার উদ্দেশ্য, শাবানের আমল, ঘরোয়া পরিকল্পনা এবং শেষ দশকের প্রস্তুতি।', '<p>প্রতি বছর রমজান আসে, আর ঈদের পর আমাদের অনেকেরই আফসোস হয়: এবারও ঠিকমতো কাজে লাগাতে পারলাম না। প্রথম কয়েক দিন ইফতারের বাজার আর রান্নায় কেটে যায়, মাঝের দিনগুলো ক্লান্তিতে, আর শেষ দশক আসে ঈদের কেনাকাটার ভিড়ে। এর একটা বড় কারণ হলো, আমরা রমজানকে এমন কিছু মনে করি যা প্রথম রোজার দিন শুরু হয়। অথচ সফল রমজানের প্রস্তুতি শুরু হয় অনেক আগে।</p><h2>রোজা কেন?</h2><p>প্রস্তুতির আগে উদ্দেশ্যটা পরিষ্কার হওয়া দরকার। আল্লাহ তাআলা বলেছেন, তোমাদের ওপর রোজা ফরজ করা হয়েছে, যেমন তোমাদের পূর্ববর্তীদের ওপর করা হয়েছিল, যাতে তোমরা তাকওয়া অর্জন করতে পারো (সূরা আল-বাকারা ২:১৮৩)। ক্ষুধা-তৃষ্ণা মাধ্যম; লক্ষ্য হলো আল্লাহ-সচেতন একটি অন্তর। আর রমজান সেই মাস, যে মাসে কুরআন নাজিল হয়েছে মানুষের জন্য হিদায়াত হিসেবে (সূরা আল-বাকারা ২:১৮৫)। তাই রমজান মূলত কুরআনের মাস।</p><p>রাসূল ﷺ বলেছেন, যে ব্যক্তি ঈমানের সাথে ও সওয়াবের আশায় রমজানের রোজা রাখে, তার পূর্বের গুনাহ মাফ করে দেওয়া হয় (সহীহ বুখারী ৩৮, সহীহ মুসলিম ৭৬০)। আবার তিনি সতর্ক করেছেন, যে ব্যক্তি মিথ্যা কথা ও তদনুযায়ী কাজ ছাড়ে না, তার খাবার ও পানীয় ত্যাগ করায় আল্লাহর কোনো প্রয়োজন নেই (সহীহ বুখারী ১৯০৩)। অর্থাৎ রোজা শুধু পেটের নয়; জিহ্বা, চোখ, কান ও মেজাজেরও রোজা।</p><h2>শাবান: প্রস্তুতির মাস</h2><p>আয়েশা (রা.) বর্ণনা করেছেন, রমজান ছাড়া অন্য কোনো মাসে রাসূল ﷺ-কে শাবানের চেয়ে বেশি নফল রোজা রাখতে দেখিনি (সহীহ বুখারী ১৯৬৯, সহীহ মুসলিম ১১৫৬)। শাবানের এই রোজাগুলো যেন রমজানের অনুশীলন। আমরাও শাবানে সপ্তাহে এক-দুটি নফল রোজা রাখতে পারি, যাতে প্রথম রমজানে শরীর হঠাৎ ধাক্কা না খায়। যাদের আগের রমজানের কাজা রোজা বাকি আছে, তাদের জন্য শাবান শেষ হওয়ার আগে তা আদায় করে নেওয়ার উপযুক্ত সময়।</p><h2>মনের প্রস্তুতি</h2><ul><li><strong>লক্ষ্য লিখে ফেলুন:</strong> এই রমজানে কতটুকু কুরআন পড়বেন? অর্থসহ কতটুকু? কোন একটি ভালো অভ্যাস গড়বেন আর কোন একটি খারাপ অভ্যাস ছাড়বেন? লিখে রাখলে লক্ষ্য বাস্তব হয়।</li><li><strong>এখনই শুরু করুন:</strong> প্রতিদিন অল্প কুরআন তিলাওয়াত এখন থেকেই শুরু করুন। যে শাবানে দিনে দুই পৃষ্ঠা পড়ে, তার জন্য রমজানে দিনে এক পারা সহজ হয়।</li><li><strong>সম্পর্ক পরিষ্কার করুন:</strong> কারও সাথে মনোমালিন্য থাকলে মিটিয়ে নিন, কারও হক নষ্ট করে থাকলে ক্ষমা চেয়ে নিন। অন্তর পরিষ্কার না থাকলে ইবাদতের স্বাদ আসে না।</li><li><strong>তওবা:</strong> নতুন মৌসুমের আগে পুরোনো খাতা পরিষ্কার করুন। আন্তরিক তওবা দিয়ে রমজানে প্রবেশ করুন।</li></ul><h2>পরিবার ও ঘরের প্রস্তুতি</h2><ul><li><strong>রান্নাঘরের পরিকল্পনা:</strong> রমজানে অনেক বোন দিনের বড় অংশ রান্নাঘরে কাটান, ফলে নিজের ইবাদতের সময় পান না। আগে থেকে সাপ্তাহিক মেন্যু ঠিক করুন, ইফতার সাদামাটা রাখুন, আর পরিবারের সবাই কাজ ভাগ করে নিন। রাসূল ﷺ নিজেও ঘরের কাজে সাহায্য করতেন।</li><li><strong>বাজার আগেই:</strong> প্রয়োজনীয় জিনিস রমজানের আগে কিনে রাখলে রোজার দিনে বাজারের ভিড়ে সময় ও মেজাজ নষ্ট হয় না।</li><li><strong>শিশুদের যুক্ত করুন:</strong> শিশুদের জন্য রমজান ক্যালেন্ডার বানান, ছোট লক্ষ্য দিন—কয়েকটা ছোট সূরা, দিনে একটা ভালো কাজ। যারা বড় হচ্ছে, তাদের অর্ধেক দিন রোজার অনুশীলন করান।</li><li><strong>ঈদের কেনাকাটা আগেভাগে:</strong> শেষ দশকের রাতগুলো যেন মার্কেটে না কাটে, তাই কেনাকাটা রমজানের আগে বা প্রথম দিকে সেরে ফেলুন।</li></ul><h2>শরীর ও দৈনন্দিন রুটিন</h2><ul><li>রাতে দেরিতে ঘুমানোর অভ্যাস থাকলে এখন থেকেই একটু আগে ঘুমানোর চেষ্টা করুন, যাতে সাহরি ও ফজরে ওঠা সহজ হয়।</li><li>চা-কফির অভ্যাস বেশি হলে ধীরে ধীরে কমান; তাহলে রোজার প্রথম দিনগুলোতে মাথাব্যথা কম হবে।</li><li>যাদের ডায়াবেটিস, উচ্চ রক্তচাপ বা অন্য দীর্ঘমেয়াদি রোগ আছে, রমজানের আগে চিকিৎসকের সাথে ওষুধের সময় নিয়ে পরামর্শ করুন। অসুস্থদের জন্য শরিয়তে ছাড় আছে; নিজের ক্ষেত্রে কী প্রযোজ্য তা আলেমের কাছ থেকে জেনে নিন।</li><li>স্ক্রিন টাইমের সীমা আগেই ঠিক করুন: কোন অ্যাপ রমজানে বন্ধ থাকবে, কতক্ষণ ফোন দেখবেন।</li></ul><h2>রমজানের দিনগুলোর জন্য কিছু সুন্নাহ</h2><ul><li><strong>সাহরি খান:</strong> রাসূল ﷺ বলেছেন, তোমরা সাহরি খাও, কারণ সাহরিতে বরকত রয়েছে (সহীহ বুখারী ১৯২৩, সহীহ মুসলিম ১০৯৫)।</li><li><strong>ইফতারে দেরি নয়:</strong> মানুষ ততদিন কল্যাণে থাকবে, যতদিন তারা দ্রুত ইফতার করবে (সহীহ বুখারী ১৯৫৭, সহীহ মুসলিম ১০৯৮)।</li><li><strong>রোজা ঢাল:</strong> রাসূল ﷺ বলেছেন, রোজা ঢালস্বরূপ; কেউ ঝগড়া করতে এলে রোজাদার যেন বলে, আমি রোজাদার (সহীহ বুখারী ১৮৯৪, সহীহ মুসলিম ১১৫১)।</li><li><strong>ইফতার করানো:</strong> যে কোনো রোজাদারকে ইফতার করায়, সে রোজাদারের সমান সওয়াব পায়, অথচ রোজাদারের সওয়াব একটুও কমে না (জামে তিরমিযী ৮০৭)।</li><li><strong>রাতের নামাজ:</strong> যে ঈমানের সাথে ও সওয়াবের আশায় রমজানের রাতে নামাজে দাঁড়ায়, তার পূর্বের গুনাহ মাফ করা হয় (সহীহ বুখারী ৩৭, সহীহ মুসলিম ৭৫৯)।</li><li><strong>দানশীলতা:</strong> রাসূল ﷺ মানুষের মধ্যে সবচেয়ে দানশীল ছিলেন, আর রমজানে তাঁর দানশীলতা আরও বেড়ে যেত (সহীহ বুখারী ৬, সহীহ মুসলিম ২৩০৮)। দানের একটা বাজেট আগেই ঠিক করুন।</li></ul><h2>শেষ দশকের পরিকল্পনা এখনই</h2><p>লাইলাতুল কদর হাজার মাসের চেয়ে উত্তম (সূরা আল-কদর ৯৭:১-৫)। রাসূল ﷺ বলেছেন, শেষ দশকের বেজোড় রাতগুলোতে তা খোঁজ করো (সহীহ বুখারী ২০১৭)। আয়েশা (রা.) জিজ্ঞেস করেছিলেন, কদরের রাত পেলে কী দোয়া করব? রাসূল ﷺ শিখিয়েছিলেন: আল্লাহুম্মা ইন্নাকা আফুউউন তুহিব্বুল আফওয়া ফাফু আন্নি—হে আল্লাহ, আপনি ক্ষমাশীল, ক্ষমা করতে ভালোবাসেন, তাই আমাকে ক্ষমা করুন (জামে তিরমিযী ৩৫১৩)।</p><p>শেষ দশকের জন্য অফিস থেকে কিছু ছুটি নেওয়া যায় কিনা, এখনই ভেবে দেখুন। যারা ইতিকাফ করতে চান, তারা আগে থেকে পরিবার ও কাজের ব্যবস্থা করে রাখুন।</p><h2>রমজানের পরে কী থাকবে?</h2><p>আলেমরা বলেন, কোনো আমল কবুল হওয়ার একটি লক্ষণ হলো, তার পরেও ভালো কাজ চলতে থাকা। তাই প্রস্তুতির সময়েই ঠিক করে নিন, রমজানে গড়া কোন অভ্যাসটি সারা বছর ধরে রাখবেন: প্রতিদিন কয়েক পৃষ্ঠা কুরআন, সপ্তাহে একবার রাতের নামাজ, নিয়মিত সামান্য দান, কিংবা অনর্থক কথা কম বলা। রমজান যেন একটি প্রশিক্ষণ শিবির হয়, যার ফল দেখা যায় বাকি এগারো মাসে।</p><blockquote>রমজান জেতা হয় রমজানের আগেই।</blockquote><p>ইসলামিক স্টুডিওর রমজান সঙ্গী অংশে আপনার শহরের সাহরি-ইফতারের সময় দেখুন, প্রতিদিনের রোজা ও লক্ষ্য চিহ্নিত করুন। আজই একটি কাগজে লিখে ফেলুন: এই রমজানে আমি কী অর্জন করতে চাই।</p>', ARRAY['ramadan', 'fasting', 'shaban']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('78f9b15e-5f1f-5660-8c08-ef91a4b4ff49', 'team', 'Islamic Studio', 'bn', 'যাকাত হিসাবের সাধারণ ভুলগুলো', 'অনুমান করে যাকাত দেওয়া, কিছু সম্পদ হিসাব থেকে বাদ পড়া, ভুল খাতে দেওয়া—যাকাত আদায়ে আমাদের সমাজে প্রচলিত ভুলগুলো এবং সেগুলো এড়ানোর উপায়।', '<p>যাকাত ইসলামের পাঁচটি স্তম্ভের একটি। রাসূল ﷺ বলেছেন, ইসলাম পাঁচটি ভিত্তির ওপর প্রতিষ্ঠিত: আল্লাহ ছাড়া কোনো ইলাহ নেই ও মুহাম্মাদ ﷺ আল্লাহর রাসূল—এই সাক্ষ্য দেওয়া, নামাজ কায়েম করা, যাকাত দেওয়া, হজ করা এবং রমজানের রোজা রাখা (সহীহ বুখারী ৮, সহীহ মুসলিম ১৬)। কুরআনে বহু জায়গায় নামাজ ও যাকাতের কথা একসাথে এসেছে (যেমন সূরা আল-বাকারা ২:৪৩)। অথচ নামাজের নিয়ম নিয়ে আমরা যতটা সচেতন, যাকাতের হিসাব নিয়ে ততটা নই। ফলে অনেক আন্তরিক মানুষও অজান্তে ভুল করে ফেলেন।</p><p>এই লেখায় আমরা যাকাত হিসাবের কিছু সাধারণ ভুল তুলে ধরছি। মনে রাখবেন, যাকাতের অনেক খুঁটিনাটি বিষয়ে মাযহাবগুলোর মধ্যে মতভেদ আছে। তাই নিজের নির্দিষ্ট পরিস্থিতির জন্য একজন নির্ভরযোগ্য আলেমের পরামর্শ নিন। এখানে উদ্দেশ্য সচেতনতা তৈরি করা, ফতোয়া দেওয়া নয়।</p><h2>যাকাতের উদ্দেশ্য</h2><p>আল্লাহ তাআলা তাঁর রাসূলকে বলেছেন, তাদের সম্পদ থেকে সদকা গ্রহণ করো, যার মাধ্যমে তুমি তাদের পবিত্র ও পরিশুদ্ধ করবে (সূরা আত-তাওবা ৯:১০৩)। যাকাত তাই দয়া নয়, বরং সম্পদে গরিবের নির্ধারিত হক এবং সম্পদের মালিকের অন্তরের পরিশুদ্ধি। আর যারা সোনা-রুপা জমা করে রাখে কিন্তু আল্লাহর পথে ব্যয় করে না, তাদের জন্য কঠিন শাস্তির সতর্কবাণী এসেছে (সূরা আত-তাওবা ৯:৩৪-৩৫)।</p><h2>ভুল ১: অনুমান করে যাকাত দেওয়া</h2><p>অনেকে বছরের শেষে মোটামুটি একটা অঙ্ক ধরে নিয়ে "এবার পঞ্চাশ হাজার দিলাম" বলে যাকাত দেন। এতে কম হয়ে গেলে বাকিটা ঋণ হিসেবে থেকে যায়। সঠিক পদ্ধতি হলো, যাকাতের তারিখে নিজের সব যাকাতযোগ্য সম্পদের একটি তালিকা করে হিসাব করা। হিসাব করতে কষ্ট হলে একটি স্প্রেডশিট বা যাকাত ক্যালকুলেটর ব্যবহার করুন এবং প্রতি বছর একই তারিখে হিসাব করুন।</p><h2>ভুল ২: শুধু ব্যাংকের টাকা হিসাব করা</h2><p>যাকাতযোগ্য সম্পদের মধ্যে সাধারণত অন্তর্ভুক্ত:</p><ul><li>হাতে থাকা নগদ টাকা ও সব ব্যাংক অ্যাকাউন্টের জমা, মোবাইল ব্যাংকিংয়ের ব্যালেন্সসহ।</li><li>সোনা ও রুপা (গয়নার বিষয়ে মতভেদ নিচে দেখুন)।</li><li>ব্যবসার পণ্য, অর্থাৎ বিক্রির উদ্দেশ্যে রাখা মালামাল, বাজারমূল্যে।</li><li>অন্যের কাছে পাওনা যে টাকা ফেরত পাওয়ার আশা আছে।</li><li>শেয়ার, সঞ্চয়পত্র বা অন্যান্য বিনিয়োগ (এগুলোর হিসাবপদ্ধতি নিয়ে আলেমদের বিস্তারিত আলোচনা আছে)।</li></ul><p>অন্যদিকে নিজের বসবাসের বাড়ি, ব্যবহারের গাড়ি, আসবাবপত্র, পরিধানের কাপড়—এগুলো যাকাতযোগ্য নয়। ভাড়া দেওয়া বাড়ির ক্ষেত্রে বাড়ির মূল্যে নয়, বরং ভাড়ার জমানো টাকায় যাকাত আসে—এটিই অধিকাংশ আলেমের মত।</p><h2>ভুল ৩: গয়নার বিষয় এড়িয়ে যাওয়া</h2><p>ব্যবহারের সোনার গয়নায় যাকাত আছে কি না, এ বিষয়ে আলেমদের মধ্যে প্রসিদ্ধ মতভেদ আছে। হানাফি মাযহাবে ব্যবহারের গয়নাতেও যাকাত দিতে হয়, আর অন্য কিছু মাযহাবে ব্যবহারের গয়নায় যাকাত নেই। বাংলাদেশে অধিকাংশ মানুষ হানাফি মত অনুসরণ করেন। সমস্যা হয় যখন কেউ কোনো মতই না জেনে বিষয়টি পুরোপুরি এড়িয়ে যান। নিজের অনুসৃত মত জেনে নিন এবং সেই অনুযায়ী আমল করুন। আর গয়না যদি স্ত্রীর মালিকানায় থাকে, তবে যাকাতের দায়িত্বও মূলত তাঁর; স্বামী চাইলে তাঁর পক্ষ থেকে, তাঁর সম্মতিতে, আদায় করে দিতে পারেন।</p><h2>ভুল ৪: নিসাব ও বছর পূর্ণ হওয়ার হিসাবে গোলমাল</h2><p>যাকাত ফরজ হয় যখন সম্পদ নির্দিষ্ট পরিমাণ, অর্থাৎ নিসাবে পৌঁছায় এবং তার ওপর এক চান্দ্র বছর অতিবাহিত হয়। রাসূল ﷺ রুপার নিসাব হিসেবে পাঁচ উকিয়া উল্লেখ করেছেন (সহীহ মুসলিম ৯৭৯)। আধুনিক হিসাবে সাধারণত সোনার নিসাব প্রায় সাড়ে সাত ভরি (৮৫ গ্রামের মতো) এবং রুপার নিসাব প্রায় সাড়ে বায়ান্ন ভরি (৫৯৫ গ্রামের মতো) ধরা হয়। নগদ টাকার ক্ষেত্রে কোনটির মূল্য ধরতে হবে, সে বিষয়ে আলেমদের মধ্যে আলোচনা আছে; অনেকে গরিবের সুবিধার কথা ভেবে রুপার মূল্য ধরার পরামর্শ দেন।</p><p>আরেকটি সাধারণ ভুল হলো সৌর বছর, অর্থাৎ জানুয়ারি-ডিসেম্বর ধরে হিসাব করা। যাকাতের বছর চান্দ্র বছর, যা সৌর বছরের চেয়ে প্রায় এগারো দিন ছোট। সহজ উপায় হলো একটি নির্দিষ্ট হিজরি তারিখ, যেমন রমজানের কোনো দিন, যাকাতের তারিখ হিসেবে ঠিক করে নেওয়া।</p><h2>ভুল ৫: সব ঋণ বাদ দিয়ে দেওয়া</h2><p>যাকাতের হিসাব থেকে ঋণ বাদ দেওয়া যায়, তবে কোন ঋণ এবং কতটুকু, তা নিয়ে আলেমদের বিস্তারিত ব্যাখ্যা আছে। অনেকে বিশ-ত্রিশ বছর মেয়াদি বাড়ির পুরো ঋণ বাদ দিয়ে দেন, ফলে বছরের পর বছর যাকাতই আসে না। আলেমদের অনেকে বলেন, দীর্ঘমেয়াদি ঋণের ক্ষেত্রে শুধু চলতি বছরে যে কিস্তি পরিশোধযোগ্য, সেটুকু বাদ দেওয়া যায়। নিজের ক্ষেত্রে কী প্রযোজ্য, জেনে নিন।</p><h2>ভুল ৬: যাকাতের খাত না জেনে দেওয়া</h2><p>আল্লাহ তাআলা নিজে যাকাতের আটটি খাত নির্ধারণ করে দিয়েছেন: ফকির, মিসকিন, যাকাত আদায়ের কাজে নিযুক্ত কর্মী, যাদের অন্তর আকৃষ্ট করা প্রয়োজন, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে এবং মুসাফির (সূরা আত-তাওবা ৯:৬০)। কিছু সাধারণ ভুল:</p><ul><li><strong>নিজের মা-বাবা, দাদা-দাদি, সন্তান বা স্ত্রীকে যাকাত দেওয়া:</strong> এদের ভরণপোষণ এমনিতেই আপনার দায়িত্বে, তাই আলেমদের ঐকমত্যে তাদের যাকাত দেওয়া যায় না। তবে ভাই-বোন, চাচা-মামা বা অন্যান্য আত্মীয় যদি যাকাতের হকদার হন, তাদের দেওয়া উত্তম, কারণ এতে আত্মীয়তার হকও আদায় হয়।</li><li><strong>যাচাই না করে দেওয়া:</strong> রাস্তায় যে-ই হাত পাতে তাকে যাকাত দিয়ে দেওয়া। যতটা সম্ভব খোঁজ নিয়ে প্রকৃত অভাবীকে দিন।</li><li><strong>মসজিদ নির্মাণে দেওয়া:</strong> অধিকাংশ আলেমের মতে মসজিদ নির্মাণ বা রক্ষণাবেক্ষণ যাকাতের খাতের অন্তর্ভুক্ত নয়। এসব কাজে সাধারণ দান করুন।</li><li><strong>কর্মচারীর বেতনের অংশ হিসেবে দেওয়া:</strong> বেতন বা বোনাস তার প্রাপ্য পারিশ্রমিক; তা যাকাত হিসেবে গণ্য করা যায় না।</li></ul><h2>ভুল ৭: লোক দেখানো ও অসম্মানজনক বিতরণ</h2><p>যাকাতের কাপড় বিতরণের নামে শত শত মানুষকে রোদে লাইনে দাঁড় করানো, ছবি তুলে প্রচার করা—এসবে গ্রহীতার সম্মান ক্ষুণ্ণ হয়, আর কখনো কখনো দুর্ঘটনাও ঘটে। আল্লাহ সতর্ক করেছেন, খোঁটা দিয়ে ও কষ্ট দিয়ে তোমাদের দানকে নষ্ট করো না (সূরা আল-বাকারা ২:২৬৪)। সম্ভব হলে গোপনে, সম্মানের সাথে, গ্রহীতার প্রকৃত প্রয়োজন বুঝে দিন। অনেক সময় নিম্নমানের কাপড়ের চেয়ে নগদ টাকা বা প্রয়োজনীয় জিনিস বেশি উপকারী।</p><h2>ভুল ৮: দেরি করা</h2><p>যাকাত ফরজ হওয়ার পর বিনা কারণে দেরি করা উচিত নয়। "রমজানে দেব" ভেবে মাসের পর মাস ফেলে রাখলে গরিবের হক আটকে থাকে, আর মাঝে মৃত্যু এলে তা ঋণ হয়ে থাকে। প্রয়োজনে যাকাতের তারিখ রমজানে ঠিক করুন, কিন্তু যে তারিখ ঠিক করলেন, তাতে অবিচল থাকুন।</p><h2>একটি সহজ চেকলিস্ট</h2><ul><li>যাকাতের একটি নির্দিষ্ট হিজরি তারিখ ঠিক করুন।</li><li>সেই দিন সব যাকাতযোগ্য সম্পদের তালিকা করুন: নগদ, ব্যাংক, সোনা-রুপা, ব্যবসার পণ্য, পাওনা, বিনিয়োগ।</li><li>চলতি পরিশোধযোগ্য ঋণ বাদ দিন।</li><li>নিসাব পূর্ণ হলে মোট মূল্যের আড়াই শতাংশ (৪০ ভাগের ১ ভাগ) হিসাব করুন।</li><li>হকদারদের তালিকা করুন, আত্মীয়দের অগ্রাধিকার দিন।</li><li>হিসাবটি লিখে রাখুন, পরের বছর কাজে লাগবে।</li></ul><blockquote>যাকাত সম্পদ কমায় না; সম্পদকে পবিত্র করে।</blockquote><p>রাসূল ﷺ বলেছেন, সদকা সম্পদ কমায় না (সহীহ মুসলিম ২৫৮৮)। যাকাত সঠিকভাবে আদায় করা তাই বোঝা নয়, বরং সম্পদে বরকতের দরজা। এই বছর অনুমান নয়, হিসাব করে যাকাত দিন। আর যেখানে সন্দেহ, সেখানে আলেমের কাছে জিজ্ঞেস করতে লজ্জা করবেন না।</p>', ARRAY['zakat', 'wealth', 'fiqh']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('4cd3aac7-f4f9-57e7-adf1-79592a0fb49b', 'team', 'Islamic Studio', 'bn', 'কুরবানির শিক্ষা: গোশত নয়, তাকওয়া', 'কুরবানি কেবল পশু জবাই ও গোশত বণ্টনের উৎসব নয়। ইবরাহিম (আ.)-এর আত্মত্যাগ থেকে শুরু করে পশুর প্রতি দয়া, প্রতিবেশীর হক আর লোক দেখানো থেকে বাঁচা—কুরবানির গভীর শিক্ষাগুলো।', '<p>ঈদুল আজহা এলে আমাদের দেশে পশুর হাট, দরদাম, জবাই, গোশত কাটা আর ফ্রিজ ভরার ব্যস্ততায় দিনগুলো কেটে যায়। কে কত বড় গরু কিনল, কত দামে কিনল—এসব আলোচনাই যেন উৎসবের মূল বিষয় হয়ে ওঠে। অথচ কুরবানির পেছনে রয়েছে মানব ইতিহাসের অন্যতম শ্রেষ্ঠ আত্মত্যাগের গল্প এবং এমন কিছু শিক্ষা, যা একজন মুমিনের পুরো জীবনকে বদলে দিতে পারে।</p><h2>আল্লাহর কাছে কী পৌঁছায়?</h2><p>কুরবানির সবচেয়ে গুরুত্বপূর্ণ আয়াতটি সম্ভবত এটি: আল্লাহর কাছে পৌঁছায় না এগুলোর গোশত, আর না রক্ত; বরং তাঁর কাছে পৌঁছায় তোমাদের তাকওয়া (সূরা আল-হাজ্জ ২২:৩৭)। এই একটি আয়াত কুরবানির পুরো দর্শন বুঝিয়ে দেয়। পশুর দাম, আকার, রং—এসব আল্লাহর কাছে মূল বিষয় নয়। মূল বিষয় হলো অন্তরের অবস্থা: আমি কি আল্লাহর জন্য করছি, নাকি মানুষকে দেখানোর জন্য?</p><p>আল্লাহ তাঁর নবীকে বলেছেন, তোমার রবের উদ্দেশ্যে নামাজ পড়ো এবং কুরবানি করো (সূরা আল-কাওসার ১০৮:২)। আর শিখিয়েছেন এই ঘোষণা দিতে: আমার নামাজ, আমার কুরবানি, আমার জীবন ও আমার মৃত্যু সবই আল্লাহর জন্য, যিনি সমগ্র জগতের রব (সূরা আল-আনআম ৬:১৬২)। কুরবানি তাই শুধু একটি দিনের আমল নয়; এটি পুরো জীবন আল্লাহর জন্য উৎসর্গ করার প্রতীক।</p><h2>ইবরাহিম (আ.)-এর আত্মত্যাগ</h2><p>সূরা আস-সাফফাতে আল্লাহ সেই ঘটনা বর্ণনা করেছেন (সূরা আস-সাফফাত ৩৭:১০০-১১১)। দীর্ঘ প্রতীক্ষার পর বৃদ্ধ বয়সে পাওয়া সন্তান যখন বাবার সাথে চলাফেরা করার মতো বড় হলো, তখন ইবরাহিম (আ.) স্বপ্নে দেখলেন তিনি তাকে জবাই করছেন। নবীদের স্বপ্ন ওহি। তিনি ছেলের সাথে বিষয়টি আলোচনা করলেন, আর ছেলে বললেন, বাবা, আপনাকে যা আদেশ করা হয়েছে তা করুন; ইনশাআল্লাহ আপনি আমাকে ধৈর্যশীলদের অন্তর্ভুক্ত পাবেন। দুজনেই যখন আত্মসমর্পণ করলেন, আল্লাহ ডেকে বললেন, তুমি স্বপ্নকে সত্যে পরিণত করেছ; এবং একটি মহান কুরবানির বিনিময়ে তাকে মুক্ত করলেন।</p><p>এই ঘটনার কয়েকটি শিক্ষা লক্ষ করার মতো:</p><ul><li><strong>আল্লাহর আদেশ সবার ওপরে:</strong> সবচেয়ে প্রিয় জিনিসও আল্লাহর আদেশের সামনে ছাড়তে প্রস্তুত থাকা।</li><li><strong>পরিবারে দ্বীনি আলোচনা:</strong> ইবরাহিম (আ.) ছেলেকে জোর করেননি, আলোচনা করেছেন। আর ছেলে এমনভাবে বড় হয়েছিলেন যে আল্লাহর আদেশ শুনেই মেনে নিয়েছেন।</li><li><strong>পরীক্ষার পরেই মুক্তি:</strong> আল্লাহ বান্দাকে কষ্ট দিতে চান না, তাঁর আনুগত্য দেখতে চান। আনুগত্য প্রমাণ হলে তিনি সহজ করে দেন।</li></ul><h2>জিলহজের প্রথম দশক</h2><p>কুরবানির প্রস্তুতি শুরু হয় জিলহজের চাঁদ দেখার সাথে সাথে। রাসূল ﷺ বলেছেন, এই দশ দিনের আমলের চেয়ে উত্তম আমল আর কোনো দিনে নেই (সহীহ বুখারী ৯৬৯)। এই দিনগুলোতে বেশি বেশি জিকির, তাকবির, নফল রোজা ও দান করা যায়। আর যিনি কুরবানি করার নিয়ত করেছেন, রাসূল ﷺ তাকে জিলহজ মাস শুরু হওয়ার পর থেকে কুরবানি পর্যন্ত চুল ও নখ না কাটার নির্দেশনা দিয়েছেন (সহীহ মুসলিম ১৯৭৭)।</p><h2>পশুর প্রতি দয়া: ইহসানের শিক্ষা</h2><p>রাসূল ﷺ বলেছেন, আল্লাহ সবকিছুতে ইহসান, অর্থাৎ উত্তমভাবে করা ফরজ করেছেন। তাই যখন জবাই করবে, উত্তমভাবে জবাই করো; তোমাদের প্রত্যেকে যেন ছুরি ধারালো করে নেয় এবং পশুকে আরাম দেয় (সহীহ মুসলিম ১৯৫৫)। কুরবানির পশু নিয়ে আমাদের সমাজে কিছু অনাকাঙ্ক্ষিত চিত্র দেখা যায়:</p><ul><li>পশুকে দিনের পর দিন খাবার-পানি ঠিকমতো না দিয়ে বেঁধে রাখা।</li><li>এক পশুর সামনে আরেকটিকে জবাই করা।</li><li>ভোঁতা ছুরি দিয়ে জবাই, বা জবাইয়ের পর পুরোপুরি নিস্তেজ হওয়ার আগেই চামড়া ছাড়ানো শুরু করা।</li><li>শিশুদের সামনে পশুকে আঘাত করা বা নিষ্ঠুরতাকে মজার বিষয় বানানো।</li></ul><p>এগুলো সুন্নাহর শিক্ষার পরিপন্থী। রাসূল ﷺ নিজে দুটি শিংওয়ালা সাদা-কালো মেশানো দুম্বা কুরবানি করেছেন, নিজ হাতে জবাই করেছেন এবং বিসমিল্লাহ ও আল্লাহু আকবার বলেছেন (সহীহ বুখারী ৫৫৬৫, সহীহ মুসলিম ১৯৬৬)। সম্ভব হলে নিজে জবাই করুন বা অন্তত উপস্থিত থাকুন, আর নিজে না পারলে দক্ষ ও দয়ালু কাউকে দায়িত্ব দিন।</p><h2>গোশত বণ্টন: ভাগের ভেতরে ভালোবাসা</h2><p>কুরবানির গোশত সম্পর্কে আল্লাহ বলেছেন, তোমরা তা থেকে খাও এবং দুস্থ-অভাবীকে খাওয়াও (সূরা আল-হাজ্জ ২২:২৮, ৩৬)। রাসূল ﷺ বলেছেন, খাও, খাওয়াও এবং সংরক্ষণ করো (সহীহ বুখারী ৫৫৬৯)। অনেক আলেম তিন ভাগ করার কথা বলেছেন: এক ভাগ নিজের পরিবারের জন্য, এক ভাগ আত্মীয়-প্রতিবেশীর জন্য এবং এক ভাগ গরিবদের জন্য। এটি উত্তম পদ্ধতি, বাধ্যতামূলক হিসাব নয়।</p><p>কিছু বিষয়ে খেয়াল রাখা দরকার:</p><ul><li>গরিবের ভাগে শুধু হাড় আর চর্বি নয়, ভালো অংশও দিন।</li><li>যারা কুরবানি দিতে পারেননি, বিশেষ করে আত্মীয় ও প্রতিবেশী, তাদের কথা আগে ভাবুন।</li><li>সব গোশত মাসের পর মাস ফ্রিজে জমিয়ে রাখার আগে ভাবুন, পাশের বাড়ির কেউ হয়তো আজ রাতে গোশত ছাড়াই খাচ্ছে।</li><li>কসাইয়ের পারিশ্রমিক আলাদাভাবে টাকায় দিন; পারিশ্রমিক হিসেবে কুরবানির গোশত বা চামড়া দেওয়া যায় না—এটিই আলেমদের প্রসিদ্ধ মত।</li></ul><h2>পরিচ্ছন্নতা: ঈমানের অংশ</h2><p>ঈদের পর শহরের রাস্তায় রক্ত, বর্জ্য আর দুর্গন্ধ—এ চিত্র আমাদের জন্য লজ্জার। যে দ্বীন পবিত্রতাকে ঈমানের অর্ধেক বলেছে (সহীহ মুসলিম ২২৩), সেই দ্বীনের সবচেয়ে বড় উৎসবের পর পরিবেশ নোংরা থাকা মানায় না। নির্ধারিত জায়গায় জবাই করুন, বর্জ্য সঠিকভাবে ফেলুন, রক্ত ধুয়ে দিন। প্রতিবেশীর কষ্ট হয় এমন কিছু করবেন না।</p><h2>লোক দেখানো থেকে সাবধান</h2><p>কুরবানির পশু নিয়ে সোশ্যাল মিডিয়ায় প্রতিযোগিতা, দামের ঘোষণা, অন্যকে ছোট করা—এসব আমলের সওয়াব নষ্ট করে দিতে পারে। আল্লাহ দেখেন অন্তর। ছোট একটা ছাগল আন্তরিকতার সাথে কুরবানি করা, লোক দেখানো বড় গরুর চেয়ে আল্লাহর কাছে অনেক বেশি মূল্যবান হতে পারে।</p><h2>শিশুদের যা শেখাবেন</h2><p>কুরবানির দিনগুলো শিশুদের জন্য দারুণ শিক্ষার সুযোগ। পশুর যত্ন নেওয়া, তাকে খাবার-পানি দেওয়ার দায়িত্ব শিশুদের দিন, যাতে তারা প্রাণীর প্রতি দয়া শেখে। ইবরাহিম (আ.) ও ইসমাইল (আ.)-এর গল্প তাদের বয়স উপযোগী ভাষায় বলুন। গোশত বণ্টনের সময় তাদের সাথে নিয়ে যান, যাতে তারা নিজের চোখে দেখে, ভাগ করে দেওয়ার আনন্দ কেমন। এভাবে কুরবানি শিশুর মনে শুধু খাওয়ার উৎসব নয়, ত্যাগ ও দয়ার উৎসব হয়ে থাকবে।</p><blockquote>পশুর গলায় ছুরি চালানোর আগে নিজের অহংকার, লোভ আর কৃপণতার গলায় ছুরি চালান।</blockquote><p>তাশরিকের দিনগুলো সম্পর্কে রাসূল ﷺ বলেছেন, এগুলো খাওয়া-দাওয়া ও আল্লাহর জিকিরের দিন (সহীহ মুসলিম ১১৪১)। তাই আনন্দ করুন, খাওয়ান, কিন্তু আল্লাহকে ভুলবেন না। এই ঈদে কুরবানির পাশাপাশি নিজের ভেতরের কোনো একটি খারাপ স্বভাবকে কুরবানি দেওয়ার নিয়ত করুন।</p>', ARRAY['qurbani', 'eid', 'dhul-hijjah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('d63e5630-7c66-5a67-b001-15a66988589a', 'team', 'Islamic Studio', 'bn', 'জানাজায় অংশ নেওয়ার আদব', 'জানাজায় অংশ নেওয়া মুসলিমের হক এবং বিশাল সওয়াবের কাজ। মৃত ব্যক্তির বাড়িতে, জানাজায়, দাফনে ও শোকার্ত পরিবারের পাশে দাঁড়ানোর সুন্নাহসম্মত আদবগুলো।', '<p>মৃত্যু এমন এক সত্য, যা কেউ অস্বীকার করে না, অথচ সবাই ভুলে থাকতে চায়। আল্লাহ বলেছেন, প্রত্যেক প্রাণকে মৃত্যুর স্বাদ গ্রহণ করতে হবে (সূরা আলে ইমরান ৩:১৮৫)। আমাদের চারপাশে প্রায়ই কারও না কারও মৃত্যুর খবর আসে: আত্মীয়, প্রতিবেশী, সহকর্মী, মসজিদের পরিচিত মুখ। এমন সময়ে আমাদের কী করা উচিত, কী বলা উচিত, কোথায় যাওয়া উচিত—এসব বিষয়ে ইসলামের রয়েছে সুন্দর নির্দেশনা। জানাজায় অংশ নেওয়া শুধু সামাজিকতা নয়; এটি একজন মুসলিমের ওপর অপর মুসলিমের হক এবং বিশাল সওয়াবের কাজ।</p><h2>মুসলিমের ওপর মুসলিমের হক</h2><p>রাসূল ﷺ বলেছেন, এক মুসলিমের ওপর অপর মুসলিমের পাঁচটি হক: সালামের জবাব দেওয়া, অসুস্থকে দেখতে যাওয়া, জানাজার অনুসরণ করা, দাওয়াত কবুল করা এবং হাঁচিদাতার জবাব দেওয়া (সহীহ বুখারী ১২৪০, সহীহ মুসলিম ২১৬২)। জানাজায় অংশ নেওয়া এই তালিকায় আছে। অর্থাৎ মৃত মুসলিম ভাইয়ের শেষ যাত্রায় সঙ্গী হওয়া তার প্রতি আমাদের দায়িত্ব।</p><h2>পাহাড় সমান সওয়াব</h2><p>রাসূল ﷺ বলেছেন, যে ব্যক্তি জানাজায় উপস্থিত হয় এবং নামাজ পড়া পর্যন্ত থাকে, তার জন্য এক কিরাত সওয়াব; আর যে দাফন পর্যন্ত থাকে, তার জন্য দুই কিরাত। জিজ্ঞেস করা হলো, দুই কিরাত কী? তিনি বললেন, দুটি বিশাল পাহাড়ের মতো (সহীহ বুখারী ১৩২৫, সহীহ মুসলিম ৯৪৫)। একটি জানাজায় আধা ঘণ্টা থেকে এক ঘণ্টা সময় দেওয়ার বিনিময়ে পাহাড় সমান সওয়াব—এর চেয়ে লাভজনক বিনিয়োগ আর কী হতে পারে!</p><h2>মৃত্যুর খবর পেলে</h2><ul><li><strong>ইন্না লিল্লাহ পড়ুন:</strong> আল্লাহ ধৈর্যশীলদের সুসংবাদ দিয়েছেন, যারা বিপদে বলে: আমরা আল্লাহরই এবং তাঁর কাছেই ফিরে যাব (সূরা আল-বাকারা ২:১৫৫-১৫৬)।</li><li><strong>মৃত ব্যক্তির জন্য দোয়া করুন:</strong> ক্ষমা ও রহমতের দোয়া তার সবচেয়ে বড় প্রয়োজন।</li><li><strong>ভালো কথা বলুন:</strong> রাসূল ﷺ বলেছেন, মৃতদের গালমন্দ করো না, কারণ তারা যা আগে পাঠিয়েছে তার কাছে পৌঁছে গেছে (সহীহ বুখারী ১৩৯৩)। মৃত ব্যক্তির দোষ চর্চা না করে তার ভালো দিকগুলো স্মরণ করুন।</li><li><strong>গুজব ছড়াবেন না:</strong> মৃত্যুর কারণ বা পরিস্থিতি নিয়ে অনুমাননির্ভর কথা সোশ্যাল মিডিয়ায় ছড়ানো থেকে বিরত থাকুন।</li></ul><h2>দ্রুততা: সুন্নাহর নির্দেশ</h2><p>রাসূল ﷺ বলেছেন, তোমরা জানাজা দ্রুত সম্পন্ন করো; যদি সে নেককার হয়, তবে তাকে কল্যাণের দিকে এগিয়ে দিচ্ছ, আর যদি অন্য কিছু হয়, তবে একটি বোঝা নিজেদের কাঁধ থেকে নামিয়ে রাখছ (সহীহ বুখারী ১৩১৫, সহীহ মুসলিম ৯৪৪)। আমাদের সমাজে অনেক সময় দূরের আত্মীয়দের আসার অপেক্ষায় বা নানা আনুষ্ঠানিকতায় দাফন অনেক দেরি করা হয়। প্রয়োজনীয় ব্যবস্থা শেষে যত দ্রুত সম্ভব গোসল, কাফন, জানাজা ও দাফন সম্পন্ন করা সুন্নাহর কাছাকাছি।</p><h2>জানাজার নামাজে</h2><ul><li>অজুসহ সময়মতো উপস্থিত হোন। দেরিতে এসে কাতার ভেঙে এগোনো থেকে বিরত থাকুন।</li><li>জানাজার নামাজের নিয়ম আগে থেকে শিখে রাখুন: চার তাকবির, প্রথম তাকবিরের পর ছানা বা ফাতিহা (মাযহাবভেদে), দ্বিতীয়টির পর দরুদ, তৃতীয়টির পর মৃতের জন্য দোয়া, চতুর্থটির পর সালাম। নিজের অনুসৃত মাযহাবের নিয়ম জেনে নিন।</li><li>মৃতের জন্য দোয়াটি অর্থসহ জানুন, যাতে আন্তরিকভাবে দোয়া করতে পারেন। দোয়া মুখস্থ না থাকলে মনে মনে নিজের ভাষায় ক্ষমা চাইলেও চলে, তবে শিখে নেওয়ার চেষ্টা করুন।</li><li>নামাজের সময় মোবাইল বন্ধ রাখুন, আর জানাজার ছবি বা ভিডিও তোলা থেকে বিরত থাকুন।</li></ul><h2>দাফনে অংশ নিলে</h2><ul><li>খাটিয়া বহনে অংশ নিন এবং পালা করে অন্যদেরও সুযোগ দিন।</li><li>কবরস্থানে নীরবতা ও গাম্ভীর্য বজায় রাখুন। হাসি-ঠাট্টা, দুনিয়াবি গল্প বা রাজনীতি আলোচনা এ জায়গার উপযুক্ত নয়।</li><li>কবরে মাটি দেওয়ায় অংশ নিন।</li><li>দাফনের পর মৃতের জন্য দোয়া করুন। রাসূল ﷺ দাফন শেষে বলতেন, তোমাদের ভাইয়ের জন্য ক্ষমা প্রার্থনা করো এবং তার জন্য দৃঢ়তা চাও, কারণ এখন তাকে প্রশ্ন করা হচ্ছে (সুনান আবি দাউদ ৩২২১)।</li></ul><h2>শোকার্ত পরিবারের পাশে</h2><p>রাসূল ﷺ-এর এক নাতি যখন মৃত্যুশয্যায়, তিনি তাঁর কন্যাকে বলে পাঠিয়েছিলেন: আল্লাহ যা নিয়েছেন তা তাঁরই, যা দিয়েছেন তাও তাঁরই; তাঁর কাছে সবকিছুর একটি নির্দিষ্ট সময় আছে। সুতরাং সে যেন ধৈর্য ধরে এবং সওয়াবের আশা রাখে (সহীহ বুখারী ১২৮৪, সহীহ মুসলিম ৯২৩)। এটি সান্ত্বনা দেওয়ার একটি সুন্দর সুন্নাহ ভাষা।</p><ul><li><strong>কম কথা, বেশি উপস্থিতি:</strong> শোকার্ত মানুষ উপদেশের চেয়ে সঙ্গ বেশি চান। "আল্লাহ তাকে মাফ করুন, আপনাদের ধৈর্য দিন"—এমন ছোট দোয়াই যথেষ্ট।</li><li><strong>খাবারের ব্যবস্থা:</strong> জাফর (রা.)-এর শাহাদাতের খবর এলে রাসূল ﷺ বলেছিলেন, জাফরের পরিবারের জন্য খাবার তৈরি করো, কারণ তাদের ওপর এমন বিষয় এসেছে যা তাদের ব্যস্ত রেখেছে (সুনান আবি দাউদ ৩১৩২, জামে তিরমিযী ৯৯৮)। শোকার্ত পরিবারকে মেহমানদারির বোঝা না দিয়ে বরং তাদের জন্য খাবার পাঠানোই সুন্নাহ।</li><li><strong>কান্না স্বাভাবিক, বিলাপ নয়:</strong> রাসূল ﷺ নিজের ছেলে ইবরাহিমের মৃত্যুতে কেঁদেছিলেন এবং বলেছিলেন, চোখ অশ্রু ঝরায়, হৃদয় ব্যথিত হয়, কিন্তু আমরা শুধু তা-ই বলি যাতে আমাদের রব সন্তুষ্ট হন (সহীহ বুখারী ১৩০৩)। অন্যদিকে গাল চাপড়ানো, কাপড় ছেঁড়া ও জাহেলি বিলাপ সম্পর্কে তিনি বলেছেন, যে এমন করে সে আমাদের দলভুক্ত নয় (সহীহ বুখারী ১২৯৪, সহীহ মুসলিম ১০৩)।</li><li><strong>ঋণ ও অসিয়তের খোঁজ:</strong> মৃত ব্যক্তির ঋণ থাকলে তা দ্রুত পরিশোধের ব্যবস্থা করতে পরিবারকে সহযোগিতা করুন।</li></ul><h2>মৃত ব্যক্তির জন্য যা উপকারী</h2><p>রাসূল ﷺ বলেছেন, মানুষ যখন মারা যায়, তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান এবং নেক সন্তান যে তার জন্য দোয়া করে (সহীহ মুসলিম ১৬৩১)। তাই মৃতের পরিবার ও প্রিয়জনরা তার জন্য দোয়া, তার পক্ষ থেকে দান এবং তার রেখে যাওয়া ভালো কাজগুলো চালু রাখার চেষ্টা করতে পারেন।</p><h2>নিজের জন্য শিক্ষা</h2><p>রাসূল ﷺ কবর জিয়ারতের অনুমতি দিয়ে বলেছেন, তা মৃত্যুকে স্মরণ করিয়ে দেয় (সহীহ মুসলিম ৯৭৬)। প্রতিটি জানাজা আসলে আমাদের নিজেদের জন্য একটি বার্তা: একদিন আমাকেও এভাবে কাঁধে তুলে নেওয়া হবে। আমার জানাজায় যারা আসবে, তারা আমার সম্পর্কে কী বলবে? আমি কী রেখে যাচ্ছি?</p><blockquote>জানাজার খাটিয়া প্রতিদিন আমাদের বলে যায়: প্রস্তুত হও।</blockquote><p>এরপর যখন কোনো জানাজার খবর পাবেন, সম্ভব হলে অংশ নিন। মৃত ভাইয়ের জন্য দোয়া করুন, শোকার্ত পরিবারের পাশে দাঁড়ান, আর নিজের জীবন নিয়ে একটু ভাবুন। এই ছোট উপস্থিতি হয়তো আমাদের আমলনামায় পাহাড় সমান হয়ে থাকবে।</p>', ARRAY['janazah', 'death', 'adab', 'sunnah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('201a7460-81a7-5464-b9ef-5d46be6ad77f', 'team', 'Islamic Studio', 'bn', 'সোশ্যাল মিডিয়া ও ইসলাম: স্ক্রিনের ওপারেও আমি মুসলিম', 'ফেসবুক, ইউটিউব, টিকটক—অনলাইনে আমাদের প্রতিটি পোস্ট, শেয়ার ও কমেন্টও আমলনামায় লেখা হয়। যাচাই, গিবত, সময়, দৃষ্টি ও দাওয়াহ নিয়ে কুরআন-হাদিসের আলোকে একটি ডিজিটাল আদবনামা।', '<p>আজ আমাদের জীবনের একটা বড় অংশ কাটে স্ক্রিনে। ঘুম থেকে উঠেই ফোন, ঘুমানোর আগেও ফোন। বন্ধুদের সাথে আড্ডা, খবর জানা, কেনাকাটা, শেখা, বিনোদন—সবই এখন অনলাইনে। এই নতুন জগতে অনেকে মনে করেন, এখানকার কথা-কাজ যেন "আসল" নয়; ভার্চুয়াল জগতে একটু গিবত, একটু মিথ্যা, একটু কটু কমেন্ট যেন তেমন কিছু না। অথচ আল্লাহর কাছে স্ক্রিনের এপার-ওপার বলে কিছু নেই।</p><p>আল্লাহ বলেছেন, মানুষ যে কথাই উচ্চারণ করে, তা লিপিবদ্ধ করার জন্য তার কাছে একজন সদা প্রস্তুত প্রহরী থাকে (সূরা কাফ ৫০:১৮)। আলেমরা বলেন, আঙুলে টাইপ করা কথাও মুখের কথার মতোই। প্রতিটি পোস্ট, কমেন্ট, শেয়ার আর লাইক আমাদের আমলনামায় যোগ হচ্ছে।</p><h2>১. শেয়ার করার আগে যাচাই</h2><p>সোশ্যাল মিডিয়ার সবচেয়ে বড় সমস্যাগুলোর একটি গুজব। একটা চাঞ্চল্যকর খবর, একটা ভুয়া হাদিস, একটা বিকৃত ছবি—মুহূর্তে হাজার মানুষের কাছে পৌঁছে যায়। অথচ আল্লাহ মুমিনদের নির্দেশ দিয়েছেন, কোনো ফাসিক যদি তোমাদের কাছে কোনো সংবাদ নিয়ে আসে, তবে তা যাচাই করে নাও, যাতে অজ্ঞতাবশত কোনো সম্প্রদায়ের ক্ষতি করে না বসো এবং পরে নিজেদের কাজের জন্য অনুতপ্ত না হও (সূরা আল-হুজুরাত ৪৯:৬)।</p><p>রাসূল ﷺ বলেছেন, একজন মানুষের মিথ্যাবাদী হওয়ার জন্য এটুকুই যথেষ্ট যে সে যা শোনে তা-ই বলে বেড়ায় (সহীহ মুসলিম, ভূমিকা, হাদিস ৫)। "শুনেছি তো", "সবাই শেয়ার করছে"—এগুলো দায় এড়ানোর অজুহাত নয়। আর বিশেষভাবে সতর্ক থাকুন ধর্মীয় পোস্টের ব্যাপারে: সূত্রহীন "হাদিস", মনগড়া ফজিলতের বার্তা, "দশজনকে শেয়ার করলে সুসংবাদ পাবেন"—এসব ছড়ানোর আগে নির্ভরযোগ্য সূত্র থেকে যাচাই করুন। রাসূল ﷺ-এর নামে মিথ্যা ছড়ানো অত্যন্ত গুরুতর গুনাহ।</p><h2>২. গিবত, উপহাস ও ট্রল</h2><p>কমেন্ট সেকশন অনেক সময় গিবতের বাজারে পরিণত হয়। কারও ছবি নিয়ে ঠাট্টা, কারও ভুলের স্ক্রিনশট ঘুরিয়ে বেড়ানো, কাউকে ব্যঙ্গাত্মক নামে ডাকা—এসব আমাদের কাছে "মজা" মনে হলেও কুরআনে স্পষ্ট নিষেধ এসেছে। আল্লাহ বলেছেন, কোনো সম্প্রদায় যেন অন্য সম্প্রদায়কে উপহাস না করে, হতে পারে তারা উপহাসকারীদের চেয়ে উত্তম; আর তোমরা একে অপরকে মন্দ নামে ডেকো না (সূরা আল-হুজুরাত ৪৯:১১)। পরের আয়াতেই বলেছেন, অনেক ধারণা থেকে বিরত থাকো, গোপন দোষ খুঁজো না এবং একে অপরের গিবত করো না (সূরা আল-হুজুরাত ৪৯:১২)।</p><p>অন্যের দোষ প্রকাশ করার বিপরীতে রাসূল ﷺ শিখিয়েছেন, যে ব্যক্তি কোনো মুসলিমের দোষ গোপন রাখে, আল্লাহ কিয়ামতের দিন তার দোষ গোপন রাখবেন (সহীহ বুখারী ২৪৪২, সহীহ মুসলিম ২৫৮০)। কারও ভুল দেখলে ভাইরাল করার আগে ভাবুন, ব্যক্তিগতভাবে তাকে জানানো যায় কি না।</p><h2>৩. ভালো বলো, নয়তো চুপ থাকো</h2><p>রাসূল ﷺ বলেছেন, যে আল্লাহ ও আখিরাতে বিশ্বাস রাখে, সে যেন ভালো কথা বলে অথবা চুপ থাকে (সহীহ বুখারী ৬০১৮, সহীহ মুসলিম ৪৭)। প্রতিটি বিতর্কে মত দেওয়া, প্রতিটি পোস্টে কমেন্ট করা আমাদের দায়িত্ব নয়। তিনি আরও বলেছেন, অনর্থক বিষয় ছেড়ে দেওয়া একজন মানুষের ইসলামের সৌন্দর্যের অংশ (জামে তিরমিযী ২৩১৭)। পোস্ট করার আগে তিনটি প্রশ্ন করুন: এটা কি সত্য? এটা কি উপকারী? এটা কি এখন বলা প্রয়োজন?</p><h2>৪. দৃষ্টির হেফাজত</h2><p>সোশ্যাল মিডিয়ার অ্যালগরিদম আমাদের চোখকে ধরে রাখতে চায়, আর এর জন্য প্রায়ই অশ্লীল বা উত্তেজক কনটেন্ট সামনে আনে। আল্লাহ মুমিন পুরুষ ও নারী উভয়কে দৃষ্টি সংযত রাখার নির্দেশ দিয়েছেন (সূরা আন-নূর ২৪:৩০-৩১)। স্ক্রলিংয়ের মধ্যে হঠাৎ কিছু সামনে এলে দ্রুত সরে যান, এমন অ্যাকাউন্ট আনফলো করুন, আর প্রয়োজনে কনটেন্ট ফিল্টার ব্যবহার করুন। আর নিজে এমন কিছু পোস্ট বা শেয়ার করবেন না যা অন্যের দৃষ্টিকে গুনাহর দিকে টানে। আল্লাহ সতর্ক করেছেন তাদের ব্যাপারে, যারা মুমিনদের মধ্যে অশ্লীলতার প্রসার পছন্দ করে (সূরা আন-নূর ২৪:১৯)।</p><h2>৫. সময়: যে নিয়ামতে আমরা প্রতারিত</h2><p>রাসূল ﷺ বলেছেন, দুটি নিয়ামত এমন, যে বিষয়ে অনেক মানুষ প্রতারিত: সুস্থতা ও অবসর (সহীহ বুখারী ৬৪১২)। "পাঁচ মিনিট দেখি" বলে ফোন হাতে নিয়ে এক ঘণ্টা পার হয়ে যাওয়ার অভিজ্ঞতা আমাদের সবার। কিছু বাস্তব পরামর্শ:</p><ul><li>ফোনের স্ক্রিন টাইম রিপোর্ট দেখুন; সংখ্যাটা অনেক সময় চোখ খুলে দেয়।</li><li>প্রতিটি অ্যাপের জন্য দৈনিক সময়সীমা ঠিক করুন।</li><li>নামাজের সময়, খাবারের টেবিলে ও ঘুমানোর আগে ফোন দূরে রাখুন।</li><li>অপ্রয়োজনীয় নোটিফিকেশন বন্ধ করুন।</li><li>সপ্তাহে অন্তত কয়েক ঘণ্টা "ডিজিটাল বিরতি" নিন; পরিবার, কুরআন ও প্রকৃতির সাথে সময় কাটান।</li></ul><h2>৬. লোক দেখানো ও তুলনা</h2><p>সোশ্যাল মিডিয়া এমন এক মঞ্চ, যেখানে সবাই নিজের জীবনের সবচেয়ে সুন্দর মুহূর্তগুলো দেখায়। ফলে অন্যের জীবন দেখে নিজের জীবনকে তুচ্ছ মনে হয়, আর জন্ম নেয় হিংসা ও অতৃপ্তি। আবার নিজের ইবাদতের ছবি দিয়ে প্রশংসা কুড়ানোর প্রলোভনও তৈরি হয়। নিয়তের দিকে খেয়াল রাখুন: নেক কাজ গোপন রাখা অনেক সময় বেশি নিরাপদ। আর অন্যের "হাইলাইট" দেখে নিজের জীবনের সাথে তুলনা করার আগে মনে রাখুন, প্রত্যেকের জীবনের পর্দার আড়ালে নিজস্ব পরীক্ষা আছে।</p><h2>৭. গোপনীয়তা ও পরিবারের সম্মান</h2><p>পরিবারের ব্যক্তিগত বিষয়, দাম্পত্য কলহ, অন্যের অনুমতি ছাড়া তাদের ছবি—এসব প্রকাশ্যে আনা থেকে বিরত থাকুন। বিশেষ করে শিশুদের ছবি ও তথ্য অনলাইনে দেওয়ার আগে তাদের নিরাপত্তার কথা ভাবুন। অন্যের ব্যক্তিগত বার্তার স্ক্রিনশট অনুমতি ছাড়া ছড়ানোও আমানতের খেয়ানত।</p><h2>৮. ভালোর প্রসার: সোশ্যাল মিডিয়া হতে পারে সদকায়ে জারিয়া</h2><p>সোশ্যাল মিডিয়া শুধু বিপদ নয়, বিশাল সুযোগও। রাসূল ﷺ বলেছেন, যে ব্যক্তি কোনো ভালো কাজের পথ দেখায়, সে তা পালনকারীর সমান সওয়াব পায় (সহীহ মুসলিম ১৮৯৩)। তিনি আরও বলেছেন, যে ইসলামে কোনো ভালো রীতি চালু করে, সে তার সওয়াব এবং পরবর্তীতে যারা তা পালন করবে তাদের সওয়াবও পাবে; আর মন্দ রীতির ক্ষেত্রেও তেমনি গুনাহ (সহীহ মুসলিম ১০১৭)। একটি সঠিক তথ্যসমৃদ্ধ পোস্ট, একটি উপকারী লেকচারের লিংক, একটি সুন্দর কুরআন তিলাওয়াত শেয়ার—হয়তো এগুলোই আমাদের মৃত্যুর পরও সওয়াব পাঠাতে থাকবে। আবার একটি অশ্লীল বা মিথ্যা পোস্টও তেমনি গুনাহ পাঠাতে থাকতে পারে।</p><h2>একটি ছোট চেকলিস্ট</h2><ul><li>পোস্ট করার আগে: সত্য? উপকারী? প্রয়োজনীয়? সম্মানজনক?</li><li>শেয়ার করার আগে: সূত্র কী? যাচাই করেছি?</li><li>কমেন্ট করার আগে: সামনাসামনি কি এভাবে বলতাম?</li><li>স্ক্রল করার আগে: আজ কতক্ষণ? এর বদলে কী করতে পারতাম?</li></ul><blockquote>কিয়ামতের দিন আমাদের টাইমলাইন খুলে দেখানো হবে; আজই তা পরিষ্কার রাখুন।</blockquote><p>আল্লাহ বলেছেন, কান, চোখ ও অন্তর—এদের প্রত্যেকটি সম্পর্কে জিজ্ঞাসা করা হবে (সূরা আল-ইসরা ১৭:৩৬)। আমাদের স্ক্রিনে দেখা, শোনা আর ভাবা সবই এর অন্তর্ভুক্ত। ইসলামিক স্টুডিওর মতো উপকারী অ্যাপ ও কনটেন্ট দিয়ে নিজের ফোনটাকে ভালোর মাধ্যম বানান, আর আজ থেকে প্রতিটি শেয়ারের আগে এক মুহূর্ত থামুন।</p>', ARRAY['social-media', 'akhlaq', 'tongue', 'modern-life']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('520b8a9e-76ea-5fa7-88d4-171171261231', 'team', 'Islamic Studio', 'bn', 'পরিবারে দ্বীন চর্চা: ঘরকে বানান ইমানের বাগান', 'ঘরে নামাজ, পারিবারিক তালিম, একসাথে কুরআন, দোয়া আর উত্তম আচরণ—কীভাবে ব্যস্ত জীবনেও পুরো পরিবারকে দ্বীনের পথে একসাথে রাখা যায়, তার বাস্তব পরিকল্পনা।', '<p>মসজিদ, মাদরাসা, ওয়াজ মাহফিল—দ্বীন শেখার এসব জায়গা অত্যন্ত গুরুত্বপূর্ণ। কিন্তু একজন মানুষের দ্বীনি চরিত্র সবচেয়ে বেশি গড়ে ওঠে তার নিজের ঘরে। শিশু প্রথম আল্লাহর নাম শোনে মায়ের মুখে, প্রথম নামাজ দেখে বাবার জায়নামাজে, প্রথম সততা শেখে পরিবারের আচরণে। যে ঘরে দ্বীন জীবন্ত, সেই ঘর থেকে বের হয় দ্বীনদার প্রজন্ম। আর যে ঘরে দ্বীন শুধু শুক্রবারের বা রমজানের বিষয়, সেখানে সন্তানরা দ্বীনকে জীবনের অংশ হিসেবে দেখতে শেখে না।</p><h2>কুরআন-সুন্নাহর আলোকে পরিবারের দায়িত্ব</h2><p>আল্লাহ বলেছেন, হে মুমিনগণ, তোমরা নিজেদের এবং তোমাদের পরিবারকে সেই আগুন থেকে রক্ষা করো, যার ইন্ধন মানুষ ও পাথর (সূরা আত-তাহরিম ৬৬:৬)। শুধু নিজে বাঁচলেই চলবে না, পরিবারকেও বাঁচানোর দায়িত্ব আছে। আর রাসূল ﷺ বলেছেন, তোমরা প্রত্যেকে দায়িত্বশীল; পুরুষ তার পরিবারের দায়িত্বশীল, নারী তার স্বামীর ঘরের দায়িত্বশীল, এবং প্রত্যেককে তার দায়িত্ব সম্পর্কে জিজ্ঞাসা করা হবে (সহীহ বুখারী ৮৯৩, সহীহ মুসলিম ১৮২৯)।</p><p>কুরআনে মুমিনদের একটি সুন্দর দোয়া শেখানো হয়েছে: হে আমাদের রব, আমাদের স্ত্রী ও সন্তানদের আমাদের জন্য চোখের শীতলতা বানিয়ে দিন এবং আমাদের মুত্তাকিদের নেতা বানান (সূরা আল-ফুরকান ২৫:৭৪)। এই দোয়া প্রতিদিন পড়ার মতো, কারণ পরিবারে দ্বীন চর্চার প্রথম ধাপ দোয়া।</p><h2>ঘরকে কবরস্থান বানিয়ো না</h2><p>রাসূল ﷺ বলেছেন, তোমরা তোমাদের কিছু নামাজ ঘরে পড়ো এবং ঘরকে কবর বানিয়ো না (সহীহ বুখারী ৪৩২, সহীহ মুসলিম ৭৭৭)। অর্থাৎ যে ঘরে নামাজ হয় না, তা যেন কবরের মতো নিষ্প্রাণ। তিনি আরও বলেছেন, যে ঘরে সূরা আল-বাকারা পড়া হয়, শয়তান সেখান থেকে পালিয়ে যায় (সহীহ মুসলিম ৭৮০)।</p><p>পুরুষরা ফরজ নামাজ মসজিদে পড়বেন, কিন্তু সুন্নাত ও নফল নামাজের একটা অংশ ঘরে পড়ার অভ্যাস করুন, যাতে সন্তানরা নিয়মিত বাবাকে নামাজ পড়তে দেখে। ঘরে একটি নির্দিষ্ট জায়গা নামাজের জন্য রাখুন, যেখানে জায়নামাজ, কুরআন আর কিছু দ্বীনি বই থাকবে।</p><h2>পারিবারিক তালিম: সপ্তাহে একটি বৈঠক</h2><p>সপ্তাহে একটি নির্দিষ্ট সময় ঠিক করুন, যেমন শুক্রবার মাগরিবের পর বা শনিবার রাতের খাবারের আগে, যখন পরিবারের সবাই মিলে ২০-৩০ মিনিট বসবেন। এই বৈঠক যেন ভাষণ না হয়, বরং সবার অংশগ্রহণে হয়:</p><ul><li><strong>একটি আয়াত:</strong> একজন তিলাওয়াত করবে, আরেকজন অর্থ পড়বে, তারপর সবাই মিলে আলোচনা: এই আয়াত আমাদের জীবনে কী বলে?</li><li><strong>একটি হাদিস:</strong> সংক্ষিপ্ত একটি হাদিস, যা সপ্তাহজুড়ে আমল করার চেষ্টা করা হবে।</li><li><strong>একটি গল্প:</strong> নবী-রাসূল বা সাহাবিদের জীবনের একটি ঘটনা। শিশুরা গল্প খুব ভালোবাসে।</li><li><strong>সপ্তাহের লক্ষ্য:</strong> যেমন "এই সপ্তাহে সবাই ঘরে ঢোকার সময় সালাম দেব" বা "প্রতিদিন একটা দোয়া শিখব"।</li><li><strong>দোয়া দিয়ে শেষ:</strong> পরিবারের সবার জন্য, আত্মীয়দের জন্য, উম্মাহর জন্য।</li></ul><h2>দৈনন্দিন ছোট অভ্যাস</h2><ul><li><strong>সালাম:</strong> ঘরে ঢোকার সময় সালাম দেওয়া। আল্লাহ বলেছেন, যখন ঘরে প্রবেশ করবে, পরস্পরকে সালাম দেবে; এটি আল্লাহর পক্ষ থেকে বরকতময় ও পবিত্র অভিবাদন (সূরা আন-নূর ২৪:৬১)।</li><li><strong>খাবারের আদব:</strong> বিসমিল্লাহ বলে ডান হাতে খাওয়া, খাওয়ার পর আলহামদুলিল্লাহ। পরিবারের সবাই একসাথে খেলে এসব আদব স্বাভাবিকভাবে শেখা হয়।</li><li><strong>ঘুমের আগে:</strong> সন্তানদের সাথে বসে তিন কুল ও আয়াতুল কুরসি পড়া, ঘুমের দোয়া।</li><li><strong>জামাতে নামাজ:</strong> মাঝে মাঝে, বিশেষ করে মাগরিব বা ইশায়, পরিবারের সবাই মিলে ঘরে জামাতে নামাজ পড়া। শিশুরা এতে অংশ নিতে খুব আনন্দ পায়।</li><li><strong>রাতের নামাজে জাগানো:</strong> রাসূল ﷺ দোয়া করেছেন, আল্লাহ সেই ব্যক্তির ওপর রহম করুন, যে রাতে উঠে নামাজ পড়ে এবং তার স্ত্রীকে জাগায় (সুনান আবি দাউদ ১৩০৮)।</li></ul><h2>আচরণই সবচেয়ে বড় দাওয়াহ</h2><p>পরিবারে দ্বীন চর্চা মানে শুধু ইবাদত নয়, আচরণও। যে বাবা নামাজ পড়েন কিন্তু স্ত্রী-সন্তানের সাথে রূঢ় আচরণ করেন, তিনি সন্তানদের কাছে দ্বীনের ভুল ছবি তুলে ধরেন। রাসূল ﷺ বলেছেন, তোমাদের মধ্যে সর্বোত্তম সে, যে তার পরিবারের কাছে সর্বোত্তম, আর আমি আমার পরিবারের কাছে তোমাদের মধ্যে সর্বোত্তম (জামে তিরমিযী ৩৮৯৫)।</p><p>আয়েশা (রা.)-কে জিজ্ঞেস করা হয়েছিল, রাসূল ﷺ ঘরে কী করতেন? তিনি বললেন, তিনি পরিবারের কাজে সাহায্য করতেন, আর নামাজের সময় হলে নামাজে বেরিয়ে যেতেন (সহীহ বুখারী ৬৭৬)। ঘরের কাজে হাত লাগানো, স্ত্রীর প্রতি সম্মান, সন্তানদের সাথে খেলা—এসবই সুন্নাহ, আর এসবের মাধ্যমেই সন্তানরা শেখে দ্বীন মানে সুন্দর জীবন।</p><h2>লুকমানের উপদেশ: একটি পারিবারিক পাঠ্যক্রম</h2><p>সূরা লুকমানে (৩১:১৩-১৯) একজন জ্ঞানী বাবা তাঁর ছেলেকে যে উপদেশ দিয়েছেন, তা যেন একটি সম্পূর্ণ পারিবারিক পাঠ্যক্রম: শিরক থেকে বাঁচা, মা-বাবার প্রতি কৃতজ্ঞতা, আল্লাহ সবকিছু দেখেন এই বিশ্বাস, নামাজ কায়েম, সৎকাজের আদেশ, বিপদে ধৈর্য, অহংকার না করা, চলাফেরায় মধ্যপন্থা এবং কণ্ঠস্বর নিচু রাখা। পারিবারিক তালিমে এই আয়াতগুলো দিয়ে কয়েক সপ্তাহের একটি সিরিজ করতে পারেন; প্রতি সপ্তাহে একটি উপদেশ।</p><h2>যখন পরিবারের সবাই একমত নন</h2><p>অনেক পরিবারে কেউ দ্বীনের প্রতি আগ্রহী, কেউ নন। এমন অবস্থায় জোরজবরদস্তি, তর্ক বা খোঁটা দেওয়া সাধারণত হিতে বিপরীত হয়। নিজের আচরণ সুন্দর রাখুন, ধৈর্য ধরুন, উপযুক্ত সময়ে নরমভাবে কথা বলুন, আর আল্লাহর কাছে দোয়া করুন। মনে রাখুন, নূহ (আ.)-এর ছেলে, ইবরাহিম (আ.)-এর বাবা—নবীদের পরিবারেও সবাই ঈমান আনেননি। আমাদের দায়িত্ব চেষ্টা; হিদায়াত আল্লাহর হাতে।</p><h2>ঘরের পরিবেশ: ছোট পরিবর্তন, বড় প্রভাব</h2><ul><li><strong>ঘরের ছোট লাইব্রেরি:</strong> বয়স অনুযায়ী কিছু দ্বীনি বই, নবীদের গল্প, সীরাত ও দোয়ার বই এমন জায়গায় রাখুন যেখানে সহজে হাত যায়।</li><li><strong>স্ক্রিনমুক্ত সময়:</strong> দিনের অন্তত একটি সময়, যেমন রাতের খাবার, পুরো পরিবারের জন্য ফোন ও টিভিমুক্ত রাখুন। এই সময়েই গল্প, প্রশ্ন আর আলোচনা জমে ওঠে।</li><li><strong>ঘরে যা চলে, তা নিয়ে সচেতনতা:</strong> টিভি, গান, ভিডিও—যা ঘরে চলে, তা শিশুদের মূল্যবোধ গড়ে। উপকারী ও পরিচ্ছন্ন বিকল্প বেছে নিন।</li><li><strong>দানের বাক্স:</strong> ঘরে একটি ছোট দানের বাক্স রাখুন। শিশুরা নিজের টাকা থেকে কিছু রাখলে মাস শেষে সবাই মিলে কোনো অভাবীকে দিয়ে আসুন।</li><li><strong>আত্মীয় ও প্রতিবেশী:</strong> পরিবার নিয়ে আত্মীয়দের খোঁজখবর নেওয়া, অসুস্থ প্রতিবেশীকে দেখতে যাওয়া—এসব কাজে সন্তানদের সঙ্গী করুন। দ্বীন শুধু ঘরের ভেতরে নয়, সম্পর্কের ভেতরেও।</li></ul><blockquote>যে ঘরে কুরআন পড়া হয়, সালাম শোনা যায় আর একে অপরকে ক্ষমা করা হয়, সেই ঘরই সত্যিকারের সুখের ঘর।</blockquote><p>আজ রাতেই শুরু করুন: খাবারের পর পরিবারের সবাইকে পাঁচ মিনিটের জন্য ডাকুন, একটি ছোট আয়াত বা হাদিস পড়ুন, আর একসাথে দোয়া করুন। ইসলামিক স্টুডিওর দৈনিক আয়াত ও দোয়া অংশ এই পারিবারিক বৈঠকের জন্য সহজ উপকরণ হতে পারে।</p>', ARRAY['family', 'parenting', 'home', 'tarbiyah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('100ab54b-6d6d-54d0-b7fe-745461ee3b61', 'team', 'Islamic Studio', 'bn', 'সাহাবিদের জীবন থেকে: কাব ইবনে মালিক (রা.) ও সত্যবাদিতার পুরস্কার', 'তাবুক অভিযানে পিছিয়ে পড়া এক সাহাবি অজুহাতের বদলে সত্য বলেছিলেন, আর তার মূল্য দিয়েছিলেন পঞ্চাশ দিনের কঠিন পরীক্ষায়। সহীহ বুখারী ও মুসলিমে বর্ণিত সেই ঘটনা ও তার শিক্ষা।', '<p>সাহাবিদের জীবন আমাদের জন্য আলোকবর্তিকা। তাঁরা ফেরেশতা ছিলেন না, মানুষ ছিলেন; তাঁদেরও ভুল হয়েছে। কিন্তু ভুলের পর তাঁরা কীভাবে আল্লাহর দিকে ফিরেছেন, সেটাই তাঁদের মহান করেছে। এমনই এক অসাধারণ ঘটনা কাব ইবনে মালিক (রা.)-এর। ঘটনাটি তিনি নিজেই বিস্তারিত বর্ণনা করেছেন, যা সহীহ বুখারী (৪৪১৮) ও সহীহ মুসলিমে (২৭৬৯) সংরক্ষিত আছে। আর আল্লাহ তাআলা এই ঘটনা নিয়ে কুরআনের আয়াত নাজিল করেছেন (সূরা আত-তাওবা ৯:১১৭-১১৯)।</p><h2>পটভূমি: তাবুক অভিযান</h2><p>নবম হিজরিতে রাসূল ﷺ রোমানদের মোকাবিলায় তাবুকের উদ্দেশ্যে অভিযানের ঘোষণা দিলেন। সময়টা ছিল প্রচণ্ড গরমের, পথ ছিল দীর্ঘ, আর মদিনায় তখন ফল পাকার মৌসুম। অন্যান্য অভিযানে রাসূল ﷺ গন্তব্য গোপন রাখতেন, কিন্তু এবার স্পষ্ট জানিয়ে দিলেন, যাতে সবাই প্রস্তুতি নিতে পারে।</p><p>কাব (রা.) বলেন, এই অভিযানের সময় আমি আগের যেকোনো সময়ের চেয়ে বেশি সচ্ছল ও সক্ষম ছিলাম; এর আগে কখনো আমার দুটি বাহন একসাথে ছিল না, কিন্তু তখন ছিল। তবু প্রতিদিন ভাবতাম, প্রস্তুতি নেব, আমি তো পারি। এভাবে "কাল করব" করতে করতে বাহিনী রওনা হয়ে গেল। তারপরও ভাবলাম, রওনা হয়ে ধরে ফেলব। কিন্তু তাও হলো না। মদিনায় ঘুরে দেখলাম, পেছনে রয়ে গেছে কেবল মুনাফিক হিসেবে পরিচিত লোকেরা আর অক্ষম মানুষেরা। এটা দেখে আমার কষ্ট আরও বেড়ে গেল।</p><h2>সিদ্ধান্তের মুহূর্ত: অজুহাত না সত্য?</h2><p>রাসূল ﷺ তাবুক থেকে ফিরে এলে যারা পিছিয়ে ছিল তারা এসে নানা অজুহাত পেশ করতে লাগল এবং কসম খেতে লাগল। তারা আশির কিছু বেশি লোক ছিল। রাসূল ﷺ তাদের বাহ্যিক কথা গ্রহণ করলেন, তাদের জন্য ক্ষমা চাইলেন এবং তাদের অন্তরের বিষয় আল্লাহর ওপর ছেড়ে দিলেন।</p><p>কাব (রা.) বলেন, আমি মনে মনে নানা অজুহাত সাজাচ্ছিলাম। আমি ছিলাম কথা বলায় দক্ষ, যুক্তি দিয়ে বেরিয়ে আসতে পারতাম। কিন্তু যখন রাসূল ﷺ-এর সামনে গেলাম, বুঝলাম মিথ্যা দিয়ে আজ হয়তো তাঁকে সন্তুষ্ট করতে পারব, কিন্তু আল্লাহ শিগগিরই তাঁকে আমার ওপর অসন্তুষ্ট করে দেবেন। আর সত্য বললে তিনি এখন অসন্তুষ্ট হবেন, কিন্তু আমি আল্লাহর কাছে ক্ষমার আশা রাখতে পারব। তাই বললাম, আল্লাহর কসম, আমার কোনো অজুহাত ছিল না; আমি কখনো এর চেয়ে সক্ষম ও সচ্ছল ছিলাম না।</p><p>রাসূল ﷺ বললেন, এই লোকটি সত্য বলেছে। যাও, আল্লাহ তোমার ব্যাপারে ফয়সালা না করা পর্যন্ত অপেক্ষা করো। কাবের গোত্রের লোকেরা তাঁকে দোষারোপ করে বলল, অন্যদের মতো একটা অজুহাত দিলেই তো হতো! তিনি প্রায় ফিরে গিয়ে কথা বদলাতে চেয়েছিলেন। তখন জানতে পারলেন, আরও দুজন একই অবস্থায় আছেন: মুরারা ইবনুর রাবি ও হিলাল ইবনে উমাইয়া (রা.), দুজনেই বদরযুদ্ধে অংশ নেওয়া নেককার মানুষ। তাঁদের মধ্যে নিজের জন্য আদর্শ খুঁজে পেয়ে কাব (রা.) সত্যের ওপর অটল রইলেন।</p><h2>পঞ্চাশ দিনের কঠিন পরীক্ষা</h2><p>রাসূল ﷺ মুসলিমদের এই তিনজনের সাথে কথা বলতে নিষেধ করলেন। কাব (রা.) বলেন, মানুষ আমাদের এড়িয়ে চলতে লাগল, যেন পৃথিবীটাই বদলে গেছে, এ যেন সেই পৃথিবী নয় যাকে আমি চিনতাম। আমি নামাজে যেতাম, রাসূল ﷺ-কে সালাম দিতাম আর লক্ষ করতাম তাঁর ঠোঁট জবাবে নড়ছে কি না। নামাজে আমি তাঁর কাছাকাছি দাঁড়াতাম; আমি নামাজে মন দিলে তিনি আমার দিকে তাকাতেন, আর আমি তাকালে মুখ ফিরিয়ে নিতেন।</p><p>একদিন তিনি নিজের চাচাতো ভাই ও প্রিয় বন্ধু আবু কাতাদা (রা.)-এর বাগানের দেয়াল টপকে তাঁকে সালাম দিলেন। আবু কাতাদা জবাব দিলেন না। কাব তিনবার জিজ্ঞেস করলেন, তুমি কি জানো না আমি আল্লাহ ও তাঁর রাসূলকে ভালোবাসি? তৃতীয়বার আবু কাতাদা শুধু বললেন, আল্লাহ ও তাঁর রাসূলই ভালো জানেন। কাবের চোখ দিয়ে অশ্রু ঝরতে লাগল।</p><h2>প্রলোভনের চিঠি</h2><p>এই কঠিন সময়ে গাসসানের খ্রিস্টান রাজার পক্ষ থেকে কাবের কাছে একটি চিঠি এল: শুনেছি তোমার নেতা তোমার প্রতি কঠোর হয়েছেন; আমাদের কাছে চলে এসো, আমরা তোমাকে সম্মান দেব। কাব (রা.) বললেন, এটাও একটা পরীক্ষা। তিনি চিঠিটি চুলায় ফেলে পুড়িয়ে দিলেন। যখন সমাজ মুখ ফিরিয়ে নিয়েছে, তখন বাইরের সম্মানের প্রস্তাব—এর চেয়ে বড় প্রলোভন আর কী হতে পারে! কিন্তু ঈমান তাঁকে স্থির রেখেছিল।</p><p>চল্লিশ দিন পর নির্দেশ এল স্ত্রীদের থেকেও আলাদা থাকতে। কাব (রা.) স্ত্রীকে বাবার বাড়ি পাঠিয়ে দিলেন। আল্লাহ এই অবস্থার বর্ণনা দিয়েছেন: পৃথিবী প্রশস্ত হওয়া সত্ত্বেও তাদের জন্য সংকীর্ণ হয়ে গিয়েছিল, তাদের জীবন তাদের জন্য দুর্বিষহ হয়ে উঠেছিল এবং তারা বুঝেছিল যে আল্লাহ ছাড়া তাঁর থেকে বাঁচার কোনো আশ্রয় নেই (সূরা আত-তাওবা ৯:১১৮)।</p><h2>সুসংবাদের ভোর</h2><p>পঞ্চাশতম রাতের পর ফজরের নামাজ পড়ে কাব (রা.) নিজের ঘরের ছাদে বসে ছিলেন। হঠাৎ সালা পাহাড়ের ওপর থেকে কেউ উচ্চস্বরে ডেকে বলল, হে কাব ইবনে মালিক, সুসংবাদ গ্রহণ করো! তিনি সিজদায় লুটিয়ে পড়লেন। বুঝলেন, মুক্তি এসেছে। আল্লাহ তাঁদের তওবা কবুল করে আয়াত নাজিল করেছেন। যে লোকটি সুসংবাদ নিয়ে এল, আনন্দে কাব তাকে নিজের পরনের দুটি কাপড় খুলে উপহার দিলেন।</p><p>তিনি মসজিদে গেলেন। তালহা ইবনে উবাইদুল্লাহ (রা.) দৌড়ে এসে তাঁর সাথে মুসাফাহা করলেন ও অভিনন্দন জানালেন; কাব এই আচরণ কখনো ভোলেননি। রাসূল ﷺ-এর চেহারা আনন্দে চাঁদের মতো উজ্জ্বল হয়ে উঠেছিল। তিনি বললেন, তোমার মা তোমাকে জন্ম দেওয়ার পর থেকে আজকের দিনটি তোমার জীবনের সর্বোত্তম দিন, এর সুসংবাদ গ্রহণ করো।</p><p>কাব (রা.) কৃতজ্ঞতায় নিজের সব সম্পদ সদকা করে দিতে চাইলেন। রাসূল ﷺ বললেন, কিছু নিজের জন্য রেখে দাও, সেটাই তোমার জন্য উত্তম। তারপর কাব (রা.) বললেন, হে আল্লাহর রাসূল, আল্লাহ আমাকে সত্যের কারণে মুক্তি দিয়েছেন, তাই আমার তওবার অংশ হলো, যতদিন বেঁচে থাকব, সত্য ছাড়া কিছু বলব না।</p><h2>এই ঘটনার শিক্ষা</h2><ul><li><strong>"কাল করব" একটি ফাঁদ:</strong> কাবের সমস্যার শুরু হয়েছিল গড়িমসি থেকে। সামর্থ্য ছিল, ইচ্ছাও ছিল, কিন্তু আজকের কাজ কালকে ঠেলে দেওয়ায় সুযোগ হাতছাড়া হলো। আমাদের তওবা, নামাজ, হজ, ঋণ পরিশোধ—কত কিছুই আমরা এভাবে পিছিয়ে দিই।</li><li><strong>সত্য প্রথমে কঠিন, পরিণামে মুক্তি:</strong> মিথ্যা বলা লোকেরা সেদিন সহজে পার পেয়েছিল, কিন্তু আল্লাহ তাদের সম্পর্কে কঠোর আয়াত নাজিল করেছেন। আর সত্যবাদীরা কষ্ট পেয়েছেন, কিন্তু তাঁদের তওবার কথা কিয়ামত পর্যন্ত কুরআনে তিলাওয়াত হবে। রাসূল ﷺ বলেছেন, সত্য নেকির পথ দেখায়, আর নেকি জান্নাতের পথ দেখায় (সহীহ বুখারী ৬০৯৪, সহীহ মুসলিম ২৬০৭)।</li><li><strong>ভালো সঙ্গীর প্রভাব:</strong> যখন কাব (রা.) দোদুল্যমান ছিলেন, তখন দুজন নেককার মানুষের দৃষ্টান্ত তাঁকে অটল রেখেছিল।</li><li><strong>পরীক্ষার সময় শত্রুর প্রস্তাব:</strong> বিপদের সময় শয়তান ও তার সহযোগীরা সহজ বিকল্প দেখায়। কাব (রা.) চিঠি পুড়িয়ে আমাদের শিখিয়ে গেছেন, প্রলোভনের দরজা খোলা রাখতে নেই।</li><li><strong>অন্যের আনন্দে শরিক হওয়া:</strong> তালহা (রা.)-এর অভিনন্দন কাব (রা.) সারা জীবন মনে রেখেছিলেন। কারও তওবা বা সুখবরে আন্তরিক আনন্দ প্রকাশ সম্পর্ককে চিরস্থায়ী করে।</li><li><strong>তওবার পর পরিবর্তন:</strong> কাব (রা.) শুধু ক্ষমা পেয়েই থেমে থাকেননি; সারা জীবনের জন্য সত্যবাদিতার প্রতিজ্ঞা করেছেন। প্রকৃত তওবা জীবনে স্থায়ী পরিবর্তন আনে।</li></ul><h2>আমাদের জন্য আয়াতটি</h2><p>এই ঘটনার পরপরই আল্লাহ বলেছেন, হে মুমিনগণ, আল্লাহকে ভয় করো এবং সত্যবাদীদের সাথে থাকো (সূরা আত-তাওবা ৯:১১৯)। আজ আমাদের জীবনেও অনেক মুহূর্ত আসে, যখন একটা ছোট মিথ্যা বা অজুহাত দিয়ে সহজে বেরিয়ে আসা যায়—অফিসে দেরির কারণ, পরীক্ষায় খারাপ ফলের ব্যাখ্যা, ব্যবসায় পণ্যের মান। কাব (রা.)-এর গল্প আমাদের মনে করিয়ে দেয়, সত্যের পথ কখনো কখনো দীর্ঘ ও একাকী মনে হতে পারে, কিন্তু সেই পথের শেষে আল্লাহর সন্তুষ্টি অপেক্ষা করে।</p><blockquote>অজুহাত হয়তো আজকের দিনটা বাঁচায়; সত্য বাঁচায় আখিরাত।</blockquote><p>পুরো ঘটনাটি সহীহ বুখারীর তাবুক অভিযান অধ্যায়ে কাব (রা.)-এর নিজের ভাষায় পড়ুন। এর প্রতিটি লাইনে ঈমান, অনুশোচনা আর আশার এমন চিত্র আছে, যা পাঠককে বারবার ভাবায়।</p>', ARRAY['sahaba', 'seerah', 'truthfulness', 'tawbah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('587a46d7-7627-5c12-8c3e-13ac79e6f5b7', 'team', 'Islamic Studio', 'bn', 'সাহাবিদের জীবন থেকে: আবু বকর সিদ্দিক (রা.)', 'নবীজির সবচেয়ে ঘনিষ্ঠ সঙ্গী, হিজরতের সাথী, ইসলামের প্রথম খলিফা। আবু বকর (রা.)-এর ঈমান, দানশীলতা, বিনয় ও সংকটকালের দৃঢ়তা থেকে সহীহ সূত্রে বর্ণিত কয়েকটি ঘটনা।', '<p>রাসূল ﷺ-এর সাহাবিদের মধ্যে যাঁর নাম সবার আগে আসে, তিনি আবু বকর সিদ্দিক (রা.)। তাঁর আসল নাম আব্দুল্লাহ ইবনে উসমান, আর "সিদ্দিক" উপাধি তাঁর ঈমানের দৃঢ়তার স্বীকৃতি। প্রাপ্তবয়স্ক স্বাধীন পুরুষদের মধ্যে তিনিই প্রথম ইসলাম গ্রহণ করেন বলে প্রসিদ্ধ। নবুয়তের শুরু থেকে রাসূল ﷺ-এর ইন্তেকাল পর্যন্ত তিনি ছিলেন তাঁর ছায়াসঙ্গী। তাঁর জীবন থেকে কয়েকটি ঘটনা আমরা এখানে তুলে ধরছি, যেগুলো সহীহ হাদিস ও কুরআনের আলোকে প্রমাণিত।</p><h2>গুহায় দুজন, তৃতীয়জন আল্লাহ</h2><p>হিজরতের রাতে কুরাইশরা যখন রাসূল ﷺ-কে হত্যার ষড়যন্ত্র করছিল, তখন তাঁর সফরসঙ্গী হওয়ার সৌভাগ্য পেয়েছিলেন আবু বকর (রা.)। তাঁরা সাওর গুহায় আশ্রয় নিলেন। কুরাইশের অনুসন্ধানকারীরা গুহার মুখ পর্যন্ত পৌঁছে গেল। আবু বকর (রা.) বলেন, আমি বললাম, হে আল্লাহর রাসূল, তাদের কেউ যদি নিজের পায়ের দিকে তাকায়, তাহলেই আমাদের দেখে ফেলবে। রাসূল ﷺ বললেন, হে আবু বকর, সেই দুজন সম্পর্কে তোমার কী ধারণা, যাদের তৃতীয়জন আল্লাহ (সহীহ বুখারী ৩৬৫৩, সহীহ মুসলিম ২৩৮১)?</p><p>আল্লাহ এই মুহূর্তটিকে কুরআনে চিরস্থায়ী করেছেন: যখন তিনি ছিলেন দুজনের দ্বিতীয়জন, যখন তারা দুজন গুহায় ছিলেন, যখন তিনি তাঁর সঙ্গীকে বলছিলেন, চিন্তা করো না, আল্লাহ আমাদের সাথে আছেন (সূরা আত-তাওবা ৯:৪০)। লক্ষ করুন, আবু বকর (রা.)-এর ভয় নিজের জন্য ছিল না, ছিল রাসূল ﷺ-এর জন্য। আর কুরআন তাঁকে "সঙ্গী" বলে সম্মানিত করেছে।</p><h2>যদি অন্তরঙ্গ বন্ধু বানাতাম</h2><p>রাসূল ﷺ বলেছেন, আমি যদি আমার রব ছাড়া কাউকে খলিল, অর্থাৎ একান্ত অন্তরঙ্গ বন্ধু হিসেবে গ্রহণ করতাম, তবে আবু বকরকেই গ্রহণ করতাম; তবে ইসলামি ভ্রাতৃত্বই শ্রেষ্ঠ (সহীহ বুখারী ৩৬৫৪, সহীহ মুসলিম ২৩৮২)। রাসূল ﷺ-এর জীবনের শেষ দিনগুলোতে অসুস্থ অবস্থায় তিনি আবু বকর (রা.)-কে নামাজে ইমামতি করার নির্দেশ দিয়েছিলেন—এ ঘটনা সহীহ হাদিসে প্রসিদ্ধ।</p><h2>সব দিয়ে দেওয়ার দিন</h2><p>উমর (রা.) বর্ণনা করেছেন, একবার রাসূল ﷺ সদকা দেওয়ার আহ্বান জানালেন। আমার কাছে তখন সম্পদ ছিল। মনে মনে বললাম, আজ যদি কোনোদিন আবু বকরকে ছাড়িয়ে যেতে পারি, তবে আজই সেই দিন। আমি আমার সম্পদের অর্ধেক নিয়ে এলাম। রাসূল ﷺ জিজ্ঞেস করলেন, পরিবারের জন্য কী রেখে এসেছ? বললাম, এর সমপরিমাণ। আর আবু বকর তাঁর কাছে যা ছিল সব নিয়ে এলেন। রাসূল ﷺ জিজ্ঞেস করলেন, পরিবারের জন্য কী রেখে এসেছ? তিনি বললেন, তাদের জন্য আল্লাহ ও তাঁর রাসূলকে রেখে এসেছি। উমর (রা.) বললেন, আমি বুঝলাম, কোনো কিছুতেই আমি কখনো তাঁকে ছাড়িয়ে যেতে পারব না (সুনান আবি দাউদ ১৬৭৮, জামে তিরমিযী ৩৬৭৫)।</p><p>এই ঘটনায় দুটি সুন্দর বিষয় আছে। এক, নেক কাজে প্রতিযোগিতা—উমর (রা.) হিংসা থেকে নয়, ভালো কাজে এগিয়ে থাকার আকাঙ্ক্ষা থেকে চেষ্টা করেছিলেন। দুই, আবু বকর (রা.)-এর আল্লাহর ওপর ভরসা। আমাদের মতো সাধারণ মানুষের জন্য অবশ্য রাসূল ﷺ-এর সাধারণ শিক্ষা হলো পরিবারের প্রয়োজন রেখে দান করা; সব দিয়ে দেওয়া আবু বকর (রা.)-এর মতো অসাধারণ ঈমানের মানুষের বৈশিষ্ট্য।</p><h2>নির্যাতিতদের মুক্তিদাতা</h2><p>মক্কার প্রথম যুগে যেসব দাস ইসলাম গ্রহণের কারণে নির্যাতিত হচ্ছিলেন, আবু বকর (রা.) নিজের সম্পদ দিয়ে তাঁদের কিনে মুক্ত করেছিলেন। তাঁদের মধ্যে সবচেয়ে প্রসিদ্ধ বিলাল (রা.)। উমর (রা.) বলতেন, আবু বকর আমাদের নেতা, আর তিনি আমাদের নেতাকে মুক্ত করেছেন—অর্থাৎ বিলালকে (সহীহ বুখারী ৩৭৫৪)। যিনি নিজে সম্মানিত, তিনি অন্য একজন দাসকে "আমাদের নেতা" বলছেন—ইসলামের ভ্রাতৃত্বের কী চমৎকার দৃষ্টান্ত!</p><h2>এক দিনে চারটি নেক কাজ</h2><p>একদিন রাসূল ﷺ সাহাবিদের জিজ্ঞেস করলেন, আজ তোমাদের মধ্যে কে রোজা রেখেছ? আবু বকর বললেন, আমি। তিনি জিজ্ঞেস করলেন, আজ কে জানাজায় অংশ নিয়েছ? আবু বকর বললেন, আমি। কে আজ কোনো মিসকিনকে খাইয়েছ? আবু বকর বললেন, আমি। কে আজ অসুস্থকে দেখতে গেছ? আবু বকর বললেন, আমি। তখন রাসূল ﷺ বললেন, যার মধ্যে এই কাজগুলো একত্র হয়, সে জান্নাতে প্রবেশ করবে (সহীহ মুসলিম ১০২৮)। লক্ষ করুন, এগুলোর কোনোটিই অসাধ্য নয়। সাধারণ দিনের সাধারণ নেক কাজ, কিন্তু একসাথে আর আন্তরিকতার সাথে।</p><h2>যিনি তাঁকে কষ্ট দিয়েছেন, তাঁকেও ক্ষমা</h2><p>আয়েশা (রা.)-এর বিরুদ্ধে মিথ্যা অপবাদের ঘটনায় যারা জড়িয়ে পড়েছিল, তাদের একজন ছিলেন মিসতাহ, আবু বকর (রা.)-এর আত্মীয়, যাকে তিনি নিয়মিত আর্থিক সাহায্য করতেন। নিজের মেয়ের বিরুদ্ধে অপবাদে অংশ নেওয়ায় কষ্ট পেয়ে আবু বকর (রা.) কসম করলেন, আর সাহায্য করবেন না। তখন আল্লাহ আয়াত নাজিল করলেন: তোমাদের মধ্যে যারা মর্যাদা ও সচ্ছলতার অধিকারী, তারা যেন আত্মীয়, অভাবী ও হিজরতকারীদের দান না করার কসম না করে; তারা যেন ক্ষমা করে ও উপেক্ষা করে। তোমরা কি চাও না যে আল্লাহ তোমাদের ক্ষমা করুন (সূরা আন-নূর ২৪:২২)? আয়াত শুনে আবু বকর (রা.) বললেন, অবশ্যই, আল্লাহর কসম, আমি চাই আল্লাহ আমাকে ক্ষমা করুন। এবং তিনি আবার মিসতাহকে সাহায্য করা শুরু করলেন (সহীহ বুখারী ৪৭৫০)।</p><h2>সবচেয়ে কঠিন দিনের দৃঢ়তা</h2><p>রাসূল ﷺ-এর ইন্তেকালের খবরে সাহাবিরা দিশেহারা হয়ে পড়েছিলেন। উমর (রা.)-এর মতো দৃঢ় মানুষও তা মেনে নিতে পারছিলেন না। আবু বকর (রা.) এসে রাসূল ﷺ-এর মুখ থেকে কাপড় সরিয়ে চুমু খেলেন, তারপর বাইরে এসে মানুষের উদ্দেশে বললেন, তোমাদের মধ্যে যে মুহাম্মাদ ﷺ-এর ইবাদত করত, সে জেনে রাখুক মুহাম্মাদ ﷺ ইন্তেকাল করেছেন; আর যে আল্লাহর ইবাদত করত, সে জেনে রাখুক আল্লাহ চিরঞ্জীব, কখনো মরবেন না। তারপর তিনি সূরা আলে ইমরানের আয়াত তিলাওয়াত করলেন (সূরা আলে ইমরান ৩:১৪৪) (সহীহ বুখারী ৩৬৬৮)। সাহাবিরা বলেছেন, মনে হচ্ছিল যেন এই আয়াত তারা আগে কখনো শোনেননি।</p><p>সবচেয়ে গভীর শোকের মুহূর্তে উম্মাহকে তাওহিদের মূলে ফিরিয়ে আনা—এটাই ছিল সিদ্দিকের নেতৃত্ব।</p><h2>আমাদের জন্য শিক্ষা</h2><ul><li><strong>সত্যকে নিঃসংকোচে গ্রহণ:</strong> সিদ্দিক মানে যিনি সত্যকে পূর্ণভাবে বিশ্বাস করেন। আল্লাহ ও রাসূলের কথা এলে দ্বিধা না করা।</li><li><strong>বন্ধুত্বের মান:</strong> তাঁর বন্ধুত্ব ছিল ত্যাগের, সঙ্গ দেওয়ার, বিপদে পাশে থাকার।</li><li><strong>দানে অগ্রগামী:</strong> সম্পদকে আল্লাহর পথে ব্যবহারের উপায় মনে করা।</li><li><strong>প্রতিদিনের ছোট নেক কাজ:</strong> রোজা, জানাজা, মিসকিনকে খাওয়ানো, অসুস্থকে দেখা—এগুলো সাধারণ মানুষের নাগালের মধ্যে।</li><li><strong>ব্যক্তিগত কষ্টের ঊর্ধ্বে ক্ষমা:</strong> আল্লাহর ক্ষমা পেতে চাইলে মানুষকে ক্ষমা করতে শেখা।</li><li><strong>সংকটে স্থিরতা:</strong> আবেগ নয়, ওহির আলোয় সিদ্ধান্ত নেওয়া।</li></ul><blockquote>আবু বকর (রা.) আমাদের শেখান: ঈমান মানে বিশ্বাস করা, ভালোবাসা মানে সঙ্গ দেওয়া, আর নেতৃত্ব মানে সংকটে মানুষকে আল্লাহর দিকে ফিরিয়ে আনা।</blockquote><p>সাহাবিদের জীবনী পড়া আমাদের ঈমানকে তাজা করে। ইসলামিক স্টুডিওর বই অংশে সীরাত ও সাহাবিদের জীবনী বিষয়ক বইগুলো দেখুন, আর আজকের দিনে সহীহ মুসলিমের সেই চারটি কাজের অন্তত একটি করার চেষ্টা করুন।</p>', ARRAY['sahaba', 'seerah', 'abu-bakr']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('6275a677-8253-5f65-935d-aa077b85ae3d', 'team', 'Islamic Studio', 'bn', 'হিংসা থেকে বাঁচার উপায়', 'অন্যের সুখ দেখে মনে জ্বালা? হিংসা কী, ঈর্ষা ও গিবতার পার্থক্য, কুরআন-হাদিসে এর ভয়াবহতা এবং অন্তরকে হিংসামুক্ত রাখার কার্যকর কিছু চিকিৎসা।', '<p>বন্ধুর ভালো চাকরি হয়েছে, আত্মীয় নতুন বাড়ি করেছে, সহকর্মী প্রমোশন পেয়েছে—খবরটা শুনে মুখে বললাম "মাশাআল্লাহ", কিন্তু ভেতরে কোথাও একটা খচখচ করল। কেন ও পেল, আমি পেলাম না? এই অনুভূতি মানুষের স্বভাবের অংশ, কিন্তু একে লালন করলে তা ধীরে ধীরে অন্তরকে বিষিয়ে তোলে। এর নাম হাসাদ, বা হিংসা। আর এটি সেই রোগ, যা দিয়ে শয়তানের প্রথম অবাধ্যতা শুরু হয়েছিল এবং আদম (আ.)-এর এক ছেলে আরেক ছেলেকে হত্যা করেছিল।</p><h2>হিংসা কী, ঈর্ষা কী?</h2><p>আলেমরা হিংসার সংজ্ঞা দিয়েছেন এভাবে: অন্যের কাছে থাকা নিয়ামত দেখে তা তার কাছ থেকে চলে যাক—এমন কামনা করা, অথবা নিয়ামত পাওয়ায় মনে কষ্ট পাওয়া। এটি নিন্দনীয়। অন্যদিকে আরেকটি অনুভূতি আছে, যাকে আরবিতে গিবতা বলা হয়: অন্যের নিয়ামত দেখে কামনা করা, আল্লাহ আমাকেও এমন দিন, অথচ তার কাছ থেকে চলে যাক তা না চাওয়া। এটি দোষের নয়, বিশেষ করে নেক কাজের ক্ষেত্রে।</p><p>রাসূল ﷺ বলেছেন, দুই ব্যক্তি ছাড়া কারও প্রতি ঈর্ষা করা যায় না: এমন ব্যক্তি, যাকে আল্লাহ সম্পদ দিয়েছেন আর সে তা সত্যের পথে ব্যয় করে; এবং এমন ব্যক্তি, যাকে আল্লাহ জ্ঞান দিয়েছেন আর সে তা দিয়ে ফয়সালা করে ও শিক্ষা দেয় (সহীহ বুখারী ৭৩, সহীহ মুসলিম ৮১৬)। এখানে ঈর্ষা মানে প্রশংসনীয় প্রতিযোগিতা—তার মতো হতে চাওয়া, তাকে নিচে নামাতে চাওয়া নয়।</p><h2>কুরআনে হিংসা</h2><p>আল্লাহ তাআলা সূরা আল-ফালাকে আমাদের শিখিয়েছেন হিংসুকের অনিষ্ট থেকে আশ্রয় চাইতে, যখন সে হিংসা করে (সূরা আল-ফালাক ১১৩:৫)। অর্থাৎ হিংসা এমন একটি বাস্তব ক্ষতি, যা থেকে আল্লাহর আশ্রয় চাওয়া দরকার। অন্যত্র আল্লাহ জিজ্ঞেস করেছেন, নাকি তারা মানুষকে হিংসা করে আল্লাহ নিজ অনুগ্রহে তাদের যা দিয়েছেন তার জন্য (সূরা আন-নিসা ৪:৫৪)? আর সরাসরি নিষেধ করেছেন: আল্লাহ যা দিয়ে তোমাদের কাউকে কারও ওপর শ্রেষ্ঠত্ব দিয়েছেন, তার আকাঙ্ক্ষা করো না; বরং আল্লাহর কাছে তাঁর অনুগ্রহ চাও (সূরা আন-নিসা ৪:৩২)।</p><p>এই আয়াতটি হিংসার চিকিৎসার মূল সূত্র দিয়ে দেয়: অন্যের দিকে না তাকিয়ে আল্লাহর দিকে তাকাও। তাঁর ভাণ্ডার অফুরন্ত; একজনকে দিলে আরেকজনের জন্য কমে যায় না।</p><h2>হাদিসে হিংসার নিষেধ</h2><p>রাসূল ﷺ বলেছেন, তোমরা পরস্পর হিংসা করো না, প্রতারণামূলক দাম বাড়িয়ো না, পরস্পর বিদ্বেষ পোষণ করো না, একে অপর থেকে মুখ ফিরিয়ে নিয়ো না... আর আল্লাহর বান্দা হিসেবে ভাই ভাই হয়ে যাও (সহীহ মুসলিম ২৫৬৪)। তিনি আরও বলেছেন, তোমাদের কেউ ততক্ষণ পূর্ণ মুমিন হতে পারবে না, যতক্ষণ না সে তার ভাইয়ের জন্য তা-ই পছন্দ করে, যা নিজের জন্য পছন্দ করে (সহীহ বুখারী ১৩, সহীহ মুসলিম ৪৫)। হিংসা এই হাদিসের ঠিক বিপরীত: ভাইয়ের জন্য যা ভালো, তা দেখে কষ্ট পাওয়া।</p><h2>হিংসার ক্ষতি</h2><ul><li><strong>আল্লাহর বণ্টনে আপত্তি:</strong> হিংসুক আসলে মনে মনে আল্লাহর ফয়সালার সমালোচনা করে—কেন ওকে দিলেন, আমাকে দিলেন না।</li><li><strong>নিজের শান্তি নষ্ট:</strong> যাকে হিংসা করা হয়, তার কিছুই কমে না; কিন্তু হিংসুকের ঘুম, শান্তি আর আনন্দ চলে যায়।</li><li><strong>অন্য গুনাহর দরজা:</strong> হিংসা থেকে জন্ম নেয় গিবত, অপবাদ, ষড়যন্ত্র, সম্পর্ক ছিন্ন করা। ইউসুফ (আ.)-এর ভাইদের ঘটনা এর জ্বলন্ত উদাহরণ (সূরা ইউসুফ ১২:৮-১০)।</li><li><strong>কৃতজ্ঞতা হারানো:</strong> অন্যের নিয়ামতের দিকে তাকাতে তাকাতে নিজের অসংখ্য নিয়ামত চোখে পড়ে না।</li></ul><h2>হিংসার চিকিৎসা</h2><h3>১. নিচের দিকে তাকান</h3><p>রাসূল ﷺ বলেছেন, তোমাদের চেয়ে যে নিচে আছে তার দিকে তাকাও, যে ওপরে আছে তার দিকে তাকিয়ো না; এতে তোমাদের ওপর আল্লাহর নিয়ামতকে তুচ্ছ মনে না করা বেশি সম্ভব হবে (সহীহ মুসলিম ২৯৬৩)। দুনিয়ার বিষয়ে যখনই কারও সাথে তুলনা মনে আসে, ভাবুন: পৃথিবীতে কত মানুষ আছে যাদের মাথার ওপর ছাদ নেই, যারা অসুস্থ, যাদের পরিবার নেই।</p><h3>২. যাকে হিংসা হয়, তার জন্য দোয়া করুন</h3><p>শুনতে উল্টো মনে হলেও এটি সবচেয়ে কার্যকর চিকিৎসাগুলোর একটি। যখনই কারও নিয়ামত দেখে মনে জ্বালা হয়, সাথে সাথে তার জন্য বরকতের দোয়া করুন: আল্লাহ তাকে আরও বরকত দিন। শুরুতে কঠিন লাগবে, কিন্তু নিয়মিত করলে অন্তর নরম হয়ে আসে। কুরআন শিখিয়েছে মাশাআল্লাহ বলতে: আল্লাহ যা চেয়েছেন তা-ই হয়েছে, আল্লাহর সাহায্য ছাড়া কোনো শক্তি নেই (সূরা আল-কাহফ ১৮:৩৯)।</p><h3>৩. আল্লাহর কাছে চান</h3><p>অন্যের কাছে থাকা নিয়ামত যদি আপনারও প্রয়োজন হয়, তাহলে তার কাছ থেকে চলে যাক না চেয়ে আল্লাহর কাছে নিজের জন্য চান (সূরা আন-নিসা ৪:৩২)। চেষ্টা করুন, পরিশ্রম করুন, দোয়া করুন। হিংসায় যে শক্তি নষ্ট হয়, তা নিজের উন্নতিতে লাগান।</p><h3>৪. প্রশংসা ও উপহার</h3><p>যার প্রতি মনে বিরূপ অনুভূতি জাগে, তার ভালো কাজের আন্তরিক প্রশংসা করুন, তাকে সালাম দিন, সম্ভব হলে উপহার দিন। আচরণ বদলালে অনুভূতিও ধীরে ধীরে বদলায়।</p><h3>৫. নিজের নিয়ামত গুনুন</h3><p>প্রতিদিন রাতে তিনটি নিয়ামতের কথা লিখুন, যার জন্য আপনি কৃতজ্ঞ। যে অন্তর কৃতজ্ঞতায় ভরা, সেখানে হিংসার জায়গা কম থাকে।</p><h3>৬. তাকদিরে বিশ্বাস</h3><p>রিজিক, সন্তান, সৌন্দর্য, মেধা—সবকিছুর বণ্টন আল্লাহর প্রজ্ঞায়। কাউকে কিছু দিয়ে তিনি পরীক্ষা করেন, কাউকে না দিয়ে। কার জন্য কোনটা কল্যাণকর, তা তিনিই জানেন। হয়তো যে নিয়ামতের জন্য আপনি আফসোস করছেন, সেটাই অন্যের জন্য কঠিন পরীক্ষা।</p><h3>৭. দোয়া: অন্তর পরিষ্কারের জন্য</h3><p>কুরআনে মুমিনদের একটি দোয়া এসেছে: হে আমাদের রব, আমাদের এবং আমাদের আগে যেসব ভাই ঈমান এনেছেন তাদের ক্ষমা করুন, আর মুমিনদের প্রতি আমাদের অন্তরে কোনো বিদ্বেষ রাখবেন না (সূরা আল-হাশর ৫৯:১০)। এই দোয়াটি মুখস্থ করে নিয়মিত পড়ুন।</p><h2>যদি অন্যের হিংসার শিকার হন</h2><p>রাসূল ﷺ বলেছেন, বদনজর সত্য (সহীহ বুখারী ৫৭৪০, সহীহ মুসলিম ২১৮৭)। অন্যের হিংসা থেকে বাঁচতে সকাল-সন্ধ্যার জিকির, সূরা আল-ফালাক ও আন-নাস পড়ার অভ্যাস করুন। নিজের সব নিয়ামত সবার সামনে, বিশেষ করে সোশ্যাল মিডিয়ায়, প্রদর্শন করা থেকে বিরত থাকুন। ইয়াকুব (আ.) ইউসুফ (আ.)-কে তাঁর স্বপ্নের কথা ভাইদের না বলতে বলেছিলেন (সূরা ইউসুফ ১২:৫)। আর হিংসুকের প্রতি প্রতিশোধ না নিয়ে তার সাথে ভালো আচরণ করুন; আল্লাহর ওপর ভরসা রাখুন।</p><blockquote>হিংসা এমন আগুন, যা প্রথমে জ্বালায় তাকে, যে তা অন্তরে জ্বালিয়ে রাখে।</blockquote><p>আজ এমন একজনের কথা ভাবুন, যার সাফল্য দেখে আপনার মন খারাপ হয়েছিল। এখনই তার জন্য আন্তরিকভাবে একটি দোয়া করুন। হয়তো এই ছোট্ট দোয়াটিই আপনার অন্তরকে মুক্ত করার প্রথম ধাপ হবে।</p>', ARRAY['hasad', 'heart', 'tazkiyah', 'akhlaq']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('7a281e03-f008-5106-9b04-1b7788a02780', 'team', 'Islamic Studio', 'bn', 'বিবাহের সুন্নাহ: সহজ বিয়ে, বরকতময় সংসার', 'পাত্র-পাত্রী নির্বাচন থেকে মোহর, ওয়ালিমা ও দাম্পত্য জীবন পর্যন্ত—কুরআন-সুন্নাহর আলোকে বিয়ের সৌন্দর্য, আর আমাদের সমাজে প্রচলিত যৌতুক ও অপচয়ের মতো কুপ্রথা থেকে বাঁচার উপায়।', '<p>বিয়ে মানুষের জীবনের অন্যতম গুরুত্বপূর্ণ সিদ্ধান্ত। ইসলামে বিয়ে শুধু একটি সামাজিক চুক্তি নয়; এটি ইবাদত, সুন্নাহ এবং প্রশান্তির উৎস। অথচ আমাদের সমাজে বিয়ে অনেক সময় হয়ে ওঠে ঋণ, প্রদর্শনী আর পারিবারিক টানাপোড়েনের উৎসব। যৌতুকের দাবি, বিপুল খরচের অনুষ্ঠান, অবাস্তব মোহর—এসবের কারণে অনেক তরুণ-তরুণীর বিয়ে বছরের পর বছর পিছিয়ে যায়, আর তার ফলে সমাজে নানা অন্যায় বাড়ে। চলুন দেখি, কুরআন ও সুন্নাহ বিয়েকে কীভাবে দেখে।</p><h2>বিয়ে: আল্লাহর নিদর্শন</h2><p>আল্লাহ বলেছেন, তাঁর নিদর্শনাবলির মধ্যে একটি হলো, তিনি তোমাদের মধ্য থেকেই তোমাদের জন্য সঙ্গিনী সৃষ্টি করেছেন, যাতে তোমরা তাদের কাছে প্রশান্তি পাও, এবং তিনি তোমাদের মধ্যে ভালোবাসা ও দয়া সৃষ্টি করেছেন (সূরা আর-রুম ৩০:২১)। এই আয়াতে দাম্পত্যের তিনটি স্তম্ভ: প্রশান্তি, ভালোবাসা ও দয়া। সময়ের সাথে আবেগের ভালোবাসা কমে এলেও দয়া ও সহমর্মিতা সম্পর্ককে ধরে রাখে।</p><p>আল্লাহ সমাজকে নির্দেশ দিয়েছেন, তোমাদের মধ্যে যারা অবিবাহিত তাদের বিয়ে দাও; তারা অভাবী হলে আল্লাহ নিজ অনুগ্রহে তাদের সচ্ছল করে দেবেন (সূরা আন-নূর ২৪:৩২)। অর্থাৎ শুধু আর্থিক অনিশ্চয়তার ভয়ে বিয়ে অনির্দিষ্টকাল পিছিয়ে রাখা কুরআনের শিক্ষার সাথে মেলে না।</p><h2>বিয়ে: নবীজির সুন্নাহ</h2><p>তিন ব্যক্তি রাসূল ﷺ-এর ইবাদত সম্পর্কে জেনে নিজেদের জন্য কঠোর নিয়ম ঠিক করল; একজন বলল, আমি কখনো বিয়ে করব না। রাসূল ﷺ তাদের বললেন, আমি রোজা রাখি, আবার ছেড়েও দিই; নামাজ পড়ি, আবার ঘুমাই; এবং নারীদের বিয়ে করি। যে আমার সুন্নাহ থেকে মুখ ফিরিয়ে নেয়, সে আমার দলভুক্ত নয় (সহীহ বুখারী ৫০৬৩, সহীহ মুসলিম ১৪০১)।</p><p>তরুণদের উদ্দেশে তিনি বলেছেন, হে যুবসমাজ, তোমাদের মধ্যে যে বিয়ের সামর্থ্য রাখে, সে যেন বিয়ে করে; কারণ তা দৃষ্টি সংযত রাখে ও লজ্জাস্থান হেফাজত করে। আর যে সামর্থ্য রাখে না, সে যেন রোজা রাখে (সহীহ বুখারী ৫০৬৬, সহীহ মুসলিম ১৪০০)।</p><h2>জীবনসঙ্গী নির্বাচন</h2><p>রাসূল ﷺ বলেছেন, সাধারণত চারটি কারণে নারীকে বিয়ে করা হয়: সম্পদ, বংশমর্যাদা, সৌন্দর্য ও দ্বীনদারি। তুমি দ্বীনদার নারীকে বেছে নিয়ে সফল হও (সহীহ বুখারী ৫০৯০, সহীহ মুসলিম ১৪৬৬)। অভিভাবকদের উদ্দেশে বলেছেন, যার দ্বীনদারি ও চরিত্রে তোমরা সন্তুষ্ট, এমন কেউ প্রস্তাব দিলে তার সাথে বিয়ে দাও; না দিলে পৃথিবীতে ফিতনা ও বড় বিপর্যয় হবে (জামে তিরমিযী ১০৮৪)।</p><p>লক্ষ করুন, এখানে দুটি মানদণ্ড: দ্বীন ও চরিত্র। চাকরির পদ, বিদেশে থাকা, গায়ের রং—এসবকে মূল মানদণ্ড বানালে সংসারের ভিত দুর্বল হয়। সৌন্দর্য বা আর্থিক অবস্থা বিবেচনা করা নিষেধ নয়, কিন্তু দ্বীন ও চরিত্রকে প্রথমে রাখতে হবে।</p><p>বিয়ের আগে পাত্র-পাত্রীর পরস্পরকে দেখার অনুমতি আছে। রাসূল ﷺ এক সাহাবিকে বলেছিলেন, তাকে দেখে নাও, কারণ এতে তোমাদের মধ্যে ভালোবাসা স্থায়ী হওয়ার সম্ভাবনা বেশি (জামে তিরমিযী ১০৮৭)। এই দেখা হবে শালীনতার সাথে, অভিভাবকের উপস্থিতিতে; বিয়ের আগে নির্জনে মেলামেশা বা দীর্ঘ সম্পর্কের অনুমতি এ থেকে বোঝায় না।</p><h2>মোহর: নারীর অধিকার</h2><p>আল্লাহ বলেছেন, নারীদের তাদের মোহর খুশিমনে দিয়ে দাও (সূরা আন-নিসা ৪:৪)। মোহর স্ত্রীর অধিকার, কোনো আনুষ্ঠানিকতা নয়। আমাদের সমাজে দুটি ভুল প্রচলিত: এক, লোক দেখানোর জন্য বিশাল অঙ্কের মোহর লিখে রাখা, যা কখনো দেওয়ার ইচ্ছাই থাকে না; দুই, মোহর আদায় না করে স্ত্রীর কাছ থেকে "মাফ" করিয়ে নেওয়ার চাপ। সঠিক পথ হলো সামর্থ্য অনুযায়ী এমন মোহর নির্ধারণ করা, যা সত্যিই আদায় করা হবে, এবং সম্ভব হলে বিয়ের সময়েই আদায় করা। রাসূল ﷺ বলেছেন, সর্বোত্তম বিয়ে হলো যা সবচেয়ে সহজ (সুনান আবি দাউদ ২১১৭)।</p><h2>যৌতুক: একটি জুলুম</h2><p>পাত্রপক্ষের যৌতুক দাবি, প্রকাশ্যে হোক বা "উপহার"-এর নামে, ইসলামে কোনো ভিত্তি নেই; বরং এটি অন্যের সম্পদ অন্যায়ভাবে নেওয়ার শামিল। ইসলামে বিয়ের আর্থিক দায়িত্ব মূলত বরের: মোহর, ওয়ালিমা এবং স্ত্রীর ভরণপোষণ। যৌতুকের কারণে কত বাবা সর্বস্বান্ত হন, কত মেয়ে নির্যাতিত হন—এই সামাজিক অভিশাপ থেকে মুক্ত হতে প্রত্যেক মুসলিম পরিবারকে স্পষ্ট অবস্থান নিতে হবে।</p><h2>ওয়ালিমা: সুন্নাহ, প্রদর্শনী নয়</h2><p>আব্দুর রহমান ইবনে আওফ (রা.) বিয়ে করলে রাসূল ﷺ তাঁকে বলেছিলেন, একটি ছাগল দিয়ে হলেও ওয়ালিমা করো (সহীহ বুখারী ৫১৬৭, সহীহ মুসলিম ১৪২৭)। ওয়ালিমা সুন্নাহ, কিন্তু তা সামর্থ্য অনুযায়ী। রাসূল ﷺ সতর্ক করেছেন, সবচেয়ে নিকৃষ্ট খাবার হলো সেই ওয়ালিমার খাবার, যেখানে ধনীদের দাওয়াত দেওয়া হয় আর গরিবদের বাদ দেওয়া হয় (সহীহ বুখারী ৫১৭৭, সহীহ মুসলিম ১৪৩২)। হাজারো মানুষকে খাওয়ানোর জন্য ঋণ করা, গায়ে হলুদ থেকে বৌভাত পর্যন্ত সপ্তাহব্যাপী আয়োজন—এসব সুন্নাহর সরলতা থেকে অনেক দূরে।</p><h2>নবদম্পতির জন্য দোয়া</h2><p>রাসূল ﷺ বিয়ে উপলক্ষে অভিনন্দন জানাতে বলতেন: বারাকাল্লাহু লাকা ওয়া বারাকা আলাইকা ওয়া জামাআ বাইনাকুমা ফি খাইর—আল্লাহ তোমার জন্য বরকত দিন, তোমার ওপর বরকত দিন এবং তোমাদের দুজনকে কল্যাণের মধ্যে একত্র রাখুন (সুনান আবি দাউদ ২১৩০, জামে তিরমিযী ১০৯১)। বিয়ের অনুষ্ঠানে প্রচলিত শুভেচ্ছার পাশাপাশি এই দোয়াটি প্রচলন করুন।</p><h2>দাম্পত্য জীবনের সুন্নাহ</h2><ul><li><strong>উত্তম আচরণ:</strong> তোমাদের মধ্যে সর্বোত্তম সে, যে তার পরিবারের কাছে সর্বোত্তম (জামে তিরমিযী ৩৮৯৫)।</li><li><strong>নেককার সঙ্গী শ্রেষ্ঠ সম্পদ:</strong> দুনিয়া উপভোগের বস্তু, আর দুনিয়ার শ্রেষ্ঠ সম্পদ নেককার স্ত্রী (সহীহ মুসলিম ১৪৬৭)। একইভাবে নেককার স্বামীও স্ত্রীর জন্য বিরাট নিয়ামত।</li><li><strong>ঘরের কাজে সহযোগিতা:</strong> রাসূল ﷺ ঘরে পরিবারের কাজে সাহায্য করতেন (সহীহ বুখারী ৬৭৬)।</li><li><strong>পরামর্শ ও সম্মান:</strong> সিদ্ধান্তে পরস্পরের মত নেওয়া, একে অপরের পরিবারকে সম্মান করা।</li><li><strong>ভুল ক্ষমা করা:</strong> কোনো মানুষ নিখুঁত নয়। একটি অপছন্দের স্বভাবের পাশে অনেক ভালো গুণও থাকে।</li></ul><h2>অভিভাবকদের জন্য কিছু কথা</h2><p>বিয়ের সিদ্ধান্তে অভিভাবকদের ভূমিকা অত্যন্ত গুরুত্বপূর্ণ। সন্তানের মতামত শোনা, তার পছন্দ-অপছন্দকে গুরুত্ব দেওয়া এবং জোর করে বিয়ে না দেওয়া ইসলামের শিক্ষা। আবার সন্তানদেরও উচিত অভিভাবকদের অভিজ্ঞতা ও পরামর্শকে সম্মান করা। সামাজিক মর্যাদা রক্ষার নামে অপ্রয়োজনীয় শর্ত, দীর্ঘ দরকষাকষি আর আত্মীয়দের মন রক্ষার জন্য বিশাল আয়োজন—এসব থেকে মুক্ত হয়ে যদি দুই পরিবার শুধু দ্বীন, চরিত্র ও পারস্পরিক সম্মানকে মানদণ্ড বানায়, তাহলে বিয়ে সহজ হয়, আর সংসার শুরু হয় ঋণ ও তিক্ততা ছাড়া।</p><p>বিয়ের প্রস্তুতিতে তরুণ-তরুণীদের জন্য দ্বীনি জ্ঞানও জরুরি: স্বামী-স্ত্রীর পারস্পরিক অধিকার, পরিবারের দায়িত্ব, মতবিরোধ মেটানোর পদ্ধতি। বিয়ের আগে এ বিষয়ে নির্ভরযোগ্য বই পড়া বা কোনো আলেমের আলোচনা শোনা অনেক ভুল বোঝাবুঝি এড়াতে সাহায্য করে।</p><blockquote>বিয়ে যত সহজ, বরকত তত বেশি।</blockquote><p>আপনার পরিবারে বা পরিচিতদের মধ্যে কোনো বিয়ের আয়োজন হলে সুন্নাহর সরলতার কথা মনে করিয়ে দিন। যৌতুক ও অপচয়কে না বলুন, আর তরুণদের জন্য হালাল পথ সহজ করে দিন।</p>', ARRAY['marriage', 'nikah', 'family', 'sunnah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('f63d03ee-0414-5690-9ad5-cefa15b84a99', 'team', 'Islamic Studio', 'bn', 'অপচয়: শয়তানের ভাই হতে চাই না', 'খাবার, পানি, বিদ্যুৎ, টাকা, সময়—আমাদের দৈনন্দিন জীবনে অপচয়ের নানা রূপ, কুরআন-হাদিসে এর নিন্দা, মধ্যপন্থার শিক্ষা এবং পরিবারে মিতব্যয়িতার অভ্যাস গড়ার উপায়।', '<p>বিয়েবাড়ির ভোজ শেষে প্লেটে প্লেটে ফেলে রাখা খাবার, রেস্টুরেন্টে অর্ধেক খেয়ে ফেলে আসা খাবার, ঘরে কেউ না থাকলেও জ্বলতে থাকা বাতি আর চলতে থাকা পাখা, অজুর সময় অবিরাম খোলা কল—অপচয় আমাদের জীবনে এত স্বাভাবিক হয়ে গেছে যে আমরা টেরই পাই না। অথচ এই একই সমাজে লাখো মানুষ রাতে না খেয়ে ঘুমাতে যায়। ইসলাম অপচয়কে শুধু অর্থনৈতিক ভুল নয়, নৈতিক অপরাধ হিসেবে দেখে।</p><h2>কুরআনের কঠোর ভাষা</h2><p>আল্লাহ বলেছেন, খাও এবং পান করো, কিন্তু অপচয় করো না; নিশ্চয়ই তিনি অপচয়কারীদের পছন্দ করেন না (সূরা আল-আরাফ ৭:৩১)। লক্ষ করুন, আয়াতটি খাওয়া-দাওয়ার অনুমতি দিয়ে শুরু হয়েছে। ইসলাম ভোগকে নিষেধ করে না, সীমালঙ্ঘনকে নিষেধ করে।</p><p>আরও কঠোর ভাষায় আল্লাহ বলেছেন, আত্মীয়কে তার হক দাও এবং অভাবী ও মুসাফিরকেও; আর কিছুতেই অপব্যয় করো না। নিশ্চয়ই অপব্যয়কারীরা শয়তানের ভাই, আর শয়তান তার রবের প্রতি অকৃতজ্ঞ (সূরা আল-ইসরা ১৭:২৬-২৭)। অপচয়কারীকে শয়তানের ভাই বলা হয়েছে, কারণ অপচয় আসলে নিয়ামতের প্রতি অকৃতজ্ঞতা—আর অকৃতজ্ঞতাই শয়তানের বৈশিষ্ট্য।</p><h2>মধ্যপন্থা: রহমানের বান্দাদের গুণ</h2><p>ইসলাম অপচয়ের বিপরীতে কৃপণতাও পছন্দ করে না। রহমানের প্রিয় বান্দাদের গুণ বর্ণনায় আল্লাহ বলেছেন, তারা যখন ব্যয় করে, তখন অপব্যয় করে না, কৃপণতাও করে না; বরং এ দুয়ের মাঝে মধ্যপন্থা অবলম্বন করে (সূরা আল-ফুরকান ২৫:৬৭)। আরেক আয়াতে সুন্দর উপমা দিয়েছেন: তোমার হাত ঘাড়ের সাথে বেঁধে রেখো না, আবার একেবারে প্রসারিতও করে দিয়ো না, তাহলে তুমি নিন্দিত ও নিঃস্ব হয়ে বসে থাকবে (সূরা আল-ইসরা ১৭:২৯)।</p><h2>হাদিসে অপচয়</h2><p>রাসূল ﷺ বলেছেন, আল্লাহ তোমাদের জন্য তিনটি বিষয় অপছন্দ করেন: অনর্থক কথাবার্তা, অতিরিক্ত প্রশ্ন করা এবং সম্পদ নষ্ট করা (সহীহ বুখারী ১৪৭৭, সহীহ মুসলিম ১৭১৫)। সম্পদ নষ্ট করা মানে আল্লাহর দেওয়া আমানতকে অবহেলা করা।</p><p>পানির ব্যবহারে রাসূল ﷺ ছিলেন অত্যন্ত মিতব্যয়ী। আনাস (রা.) বর্ণনা করেছেন, রাসূল ﷺ এক মুদ (প্রায় দুই অঞ্জলি পরিমাণ) পানি দিয়ে অজু করতেন এবং এক সা থেকে পাঁচ মুদ পর্যন্ত পানি দিয়ে গোসল করতেন (সহীহ বুখারী ২০১, সহীহ মুসলিম ৩২৫)। আমরা যারা অজুর পুরো সময় কল খুলে রাখি, তাদের জন্য এটি একটি বড় শিক্ষা। ইবাদতের সময়েও অপচয়ের সুযোগ নেই।</p><p>খাবারের প্রতি সম্মানের শিক্ষা দিয়ে রাসূল ﷺ বলেছেন, তোমাদের কারও খাবারের লোকমা পড়ে গেলে সে যেন তা তুলে নেয়, ময়লা থাকলে পরিষ্কার করে খেয়ে নেয় এবং শয়তানের জন্য ফেলে না রাখে (সহীহ মুসলিম ২০৩৩)। একটি লোকমার প্রতিও এই যত্ন! আর অতিভোজন সম্পর্কে বলেছেন, পেটের চেয়ে নিকৃষ্ট কোনো পাত্র মানুষ পূর্ণ করে না; আদম সন্তানের জন্য কয়েক লোকমাই যথেষ্ট, যা তার পিঠ সোজা রাখে। যদি বেশি খেতেই হয়, তবে এক-তৃতীয়াংশ খাবারের জন্য, এক-তৃতীয়াংশ পানির জন্য এবং এক-তৃতীয়াংশ শ্বাসের জন্য (জামে তিরমিযী ২৩৮০)।</p><h2>অপচয়ের আধুনিক রূপ</h2><ul><li><strong>খাবার:</strong> প্রয়োজনের চেয়ে বেশি রান্না, বাসি খাবার ফেলে দেওয়া, অনুষ্ঠানে অগণিত পদ, প্লেটে অতিরিক্ত নিয়ে ফেলে রাখা।</li><li><strong>পানি:</strong> অজু, গোসল, দাঁত মাজা বা থালাবাসন ধোয়ার সময় কল খোলা রাখা; লিক হওয়া কল মেরামত না করা।</li><li><strong>বিদ্যুৎ ও জ্বালানি:</strong> খালি ঘরে বাতি-পাখা-এসি চালিয়ে রাখা, অপ্রয়োজনে গ্যাসের চুলা জ্বালিয়ে রাখা।</li><li><strong>পোশাক ও কেনাকাটা:</strong> প্রতি উৎসবে নতুন পোশাক, যা দু-একবার পরে আলমারিতে পড়ে থাকে; ছাড় দেখে অপ্রয়োজনীয় জিনিস কেনা।</li><li><strong>অনুষ্ঠান:</strong> বিয়ে, জন্মদিন বা অন্যান্য অনুষ্ঠানে প্রতিযোগিতামূলক ব্যয়, যা অনেক সময় ঋণ করে করা হয়।</li><li><strong>সময়:</strong> সময়ও সম্পদ। অনর্থক স্ক্রলিং আর অপ্রয়োজনীয় আড্ডায় ঘণ্টার পর ঘণ্টা নষ্ট করাও এক ধরনের অপচয়।</li></ul><h2>কিয়ামতের দিনের প্রশ্ন</h2><p>আল্লাহ বলেছেন, তারপর সেদিন তোমাদের অবশ্যই নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে (সূরা আত-তাকাসুর ১০২:৮)। আর রাসূল ﷺ জানিয়েছেন, কিয়ামতের দিন প্রত্যেককে জিজ্ঞাসা করা হবে তার সম্পদ কোথা থেকে উপার্জন করেছে এবং কোথায় ব্যয় করেছে (জামে তিরমিযী ২৪১৭)। যে খাবার আমরা ফেলে দিই, যে টাকা লোক দেখানোয় উড়িয়ে দিই—সবকিছুর হিসাব দিতে হবে।</p><h2>পরিবারে মিতব্যয়িতার অভ্যাস</h2><ul><li><strong>পরিমাণমতো রান্না:</strong> পরিবারের সদস্যসংখ্যা ও চাহিদা বুঝে রান্না করুন। বেঁচে যাওয়া খাবার যত্ন করে সংরক্ষণ করে পরে খান, অথবা কাউকে দিন।</li><li><strong>অল্প নিন, প্রয়োজনে আবার নিন:</strong> শিশুদের শেখান প্লেটে অল্প নিতে, প্রয়োজন হলে আবার নিতে।</li><li><strong>অনুষ্ঠানের খাবার ভাগ করুন:</strong> অতিরিক্ত খাবার নষ্ট না করে সাথে সাথে আশপাশের অভাবী মানুষ, মাদরাসা বা এতিমখানায় পাঠানোর ব্যবস্থা আগে থেকে করে রাখুন।</li><li><strong>অজুর সময় সচেতনতা:</strong> প্রয়োজনে একটা মগ বা বদনা ব্যবহার করুন; কল খোলা রেখে কথা বলবেন না।</li><li><strong>"সুইচ অফ" অভ্যাস:</strong> ঘর থেকে বের হওয়ার সময় বাতি-পাখা বন্ধ করা পরিবারের নিয়ম বানান।</li><li><strong>কেনার আগে প্রশ্ন:</strong> এটা কি সত্যিই দরকার, নাকি শুধু ইচ্ছা হচ্ছে? একদিন অপেক্ষা করে তারপর সিদ্ধান্ত নিন।</li><li><strong>বাঁচানো টাকা দানে:</strong> মিতব্যয়িতায় যা বাঁচে, তার একটা অংশ সদকার জন্য আলাদা করে রাখুন। তাহলে মিতব্যয় কৃপণতা না হয়ে ইবাদতে পরিণত হবে।</li></ul><h2>অপচয় ও অহংকার</h2><p>অনেক অপচয়ের মূলে থাকে প্রদর্শনের ইচ্ছা: মানুষ কী বলবে, আত্মীয়দের সামনে মান থাকবে কি না, প্রতিবেশীর চেয়ে বড় আয়োজন হলো কি না। এভাবে অপচয় শুধু সম্পদ নষ্ট করে না, অন্তরে অহংকার ও প্রতিযোগিতার বীজও বোনে। আল্লাহ সম্পদকে মানুষের জন্য জীবনধারণের অবলম্বন বানিয়েছেন; তা নিয়ে গর্ব করা বা তা উড়িয়ে দিয়ে নিজের মর্যাদা প্রমাণ করা নিয়ামতের অপমান। সাদামাটা জীবনযাপন দুর্বলতার লক্ষণ নয়; রাসূল ﷺ ও তাঁর সাহাবিদের জীবন ছিল সরলতার শ্রেষ্ঠ উদাহরণ।</p><p>এ ছাড়া মনে রাখা দরকার, পৃথিবীর সম্পদ সীমিত। পানি, জ্বালানি, খাদ্য—সবকিছুতে আমাদের পরবর্তী প্রজন্মের হকও আছে। আল্লাহ মানুষকে পৃথিবীতে তাঁর প্রতিনিধি বানিয়েছেন; প্রতিনিধির দায়িত্ব আমানত রক্ষা করা, নষ্ট করা নয়।</p><h2>মিতব্যয় মানে কৃপণতা নয়</h2><p>অপচয় থেকে বাঁচতে গিয়ে কেউ যেন কৃপণতায় না পড়ে। পরিবারের প্রয়োজন পূরণ না করা, মেহমানদারিতে সংকোচ, যাকাত-সদকায় অনীহা—এসবও নিন্দনীয়। আল্লাহ যাকে সচ্ছলতা দিয়েছেন, তার জীবনে তার প্রকাশ থাকা দোষের নয়, যদি তা অহংকার ও অপচয় ছাড়া হয়। মূল মানদণ্ড হলো মধ্যপন্থা, কৃতজ্ঞতা এবং অন্যের হকের কথা মনে রাখা।</p><blockquote>যে খাবার আজ ফেলে দিচ্ছি, তা হয়তো কারও আজকের একমাত্র আহার হতে পারত।</blockquote><p>এই সপ্তাহে নিজের ঘরে একটি "অপচয় নিরীক্ষা" করুন: কোথায় খাবার, পানি, বিদ্যুৎ বা টাকা অপ্রয়োজনে খরচ হচ্ছে, তা লিখে ফেলুন। তারপর পরিবারের সবাই মিলে একটি করে পরিবর্তনের সিদ্ধান্ত নিন। ছোট পরিবর্তন, বড় কৃতজ্ঞতা।</p>', ARRAY['israf', 'wealth', 'gratitude', 'akhlaq']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('1a7e6ffd-8685-5991-b49f-5e7b4c79066c', 'team', 'Islamic Studio', 'bn', 'দুনিয়া ও আখিরাত: ভারসাম্যের পথ', 'দুনিয়া কি ছেড়ে দিতে হবে, নাকি আঁকড়ে ধরতে হবে? কুরআন-হাদিসে দুনিয়ার প্রকৃত মূল্য, আখিরাতের প্রস্তুতি এবং দুনিয়াকে আখিরাতের সেতু বানানোর ভারসাম্যপূর্ণ দৃষ্টিভঙ্গি।', '<p>আমাদের জীবনের বেশির ভাগ সময়, শক্তি আর চিন্তা যায় দুনিয়ার পেছনে: পড়াশোনা, চাকরি, ব্যবসা, বাড়ি, গাড়ি, সন্তানের ভবিষ্যৎ। এর কিছুই নিজে খারাপ নয়। কিন্তু প্রশ্ন হলো, এই দৌড়ের মধ্যে আমরা কি কখনো থেমে ভাবি, শেষ গন্তব্য কোথায়? ইসলাম দুনিয়াকে অস্বীকার করতে বলে না, আবার দুনিয়াকে চূড়ান্ত লক্ষ্য বানাতেও নিষেধ করে। এই ভারসাম্যই আজকের আলোচনার বিষয়।</p><h2>দুনিয়ার প্রকৃত চেহারা</h2><p>আল্লাহ তাআলা দুনিয়ার জীবনের একটি স্পষ্ট ছবি এঁকেছেন: জেনে রাখো, দুনিয়ার জীবন খেলাধুলা, আমোদ-প্রমোদ, সাজসজ্জা, পরস্পরের মধ্যে অহংকার এবং সম্পদ ও সন্তানে প্রাচুর্যের প্রতিযোগিতা মাত্র। এর উদাহরণ বৃষ্টির মতো, যার উৎপন্ন ফসল কৃষকদের চমৎকৃত করে, তারপর তা শুকিয়ে যায়, তুমি তাকে হলুদ দেখতে পাও, তারপর তা খড়কুটোয় পরিণত হয় (সূরা আল-হাদিদ ৫৭:২০)।</p><p>সূরা আল-কাহফেও একই ধরনের উপমা এসেছে, আর তারপর বলা হয়েছে: সম্পদ ও সন্তান দুনিয়ার জীবনের শোভা; আর স্থায়ী সৎকর্ম তোমার রবের কাছে প্রতিদান হিসেবে উত্তম এবং আশা পোষণের জন্যও উত্তম (সূরা আল-কাহফ ১৮:৪৫-৪৬)।</p><p>রাসূল ﷺ একবার বাজারের পাশ দিয়ে যাচ্ছিলেন। পথে একটি মৃত ছাগলছানা পড়ে ছিল, যার কান ছোট। তিনি তার কান ধরে বললেন, তোমাদের কেউ কি এক দিরহামের বিনিময়ে এটা নিতে চাও? সাহাবিরা বললেন, আমরা তো কিছুর বিনিময়েই এটা চাই না, এটা দিয়ে কী করব? এটা জীবিত থাকলেও তো দোষযুক্ত ছিল। তিনি বললেন, আল্লাহর কসম, এটা তোমাদের কাছে যতটা তুচ্ছ, আল্লাহর কাছে দুনিয়া এর চেয়েও তুচ্ছ (সহীহ মুসলিম ২৯৫৭)।</p><h2>আখিরাত: স্থায়ী ঠিকানা</h2><p>আল্লাহ বলেছেন, বরং তোমরা দুনিয়ার জীবনকে প্রাধান্য দাও, অথচ আখিরাত উত্তম ও স্থায়ী (সূরা আল-আলা ৮৭:১৬-১৭)। আর মনে করিয়ে দিয়েছেন, প্রত্যেক প্রাণ মৃত্যুর স্বাদ গ্রহণ করবে, আর কিয়ামতের দিন তোমাদের পূর্ণ প্রতিদান দেওয়া হবে। যাকে জাহান্নাম থেকে দূরে রাখা হবে ও জান্নাতে প্রবেশ করানো হবে, সে-ই সফল। আর দুনিয়ার জীবন তো প্রতারণার উপকরণ ছাড়া কিছু নয় (সূরা আলে ইমরান ৩:১৮৫)।</p><p>রাসূল ﷺ ইবনে উমর (রা.)-এর কাঁধ ধরে বলেছিলেন, দুনিয়ায় এমনভাবে থাকো যেন তুমি একজন অপরিচিত বা পথিক (সহীহ বুখারী ৬৪১৬)। পথিক যেখানে থামে, সেখানে বাড়ি বানায় না; শুধু প্রয়োজনটুকু নেয় এবং গন্তব্যের কথা মনে রাখে। রাসূল ﷺ নিজের সম্পর্কে বলেছেন, দুনিয়ার সাথে আমার সম্পর্ক কী? আমি তো এমন এক আরোহীর মতো, যে একটি গাছের ছায়ায় বিশ্রাম নিল, তারপর তা ছেড়ে চলে গেল (জামে তিরমিযী ২৩৭৭)।</p><h2>তাহলে কি দুনিয়া ছেড়ে দেব?</h2><p>না। ইসলাম বৈরাগ্যের ধর্ম নয়। কারুনের সম্প্রদায়ের জ্ঞানীরা তাকে যে উপদেশ দিয়েছিলেন, কুরআন তা উল্লেখ করেছে: আল্লাহ তোমাকে যা দিয়েছেন তা দিয়ে আখিরাতের ঘর অনুসন্ধান করো, আর দুনিয়া থেকে তোমার অংশ ভুলে যেয়ো না; এবং তুমি অনুগ্রহ করো, যেমন আল্লাহ তোমার প্রতি অনুগ্রহ করেছেন (সূরা আল-কাসাস ২৮:৭৭)।</p><p>আর কুরআনে শেখানো সবচেয়ে প্রসিদ্ধ দোয়াগুলোর একটিতে দুনিয়া ও আখিরাত দুটোই আছে: হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতেও কল্যাণ দিন এবং আমাদের আগুনের শাস্তি থেকে রক্ষা করুন (সূরা আল-বাকারা ২:২০১)।</p><p>সুতরাং দুনিয়ার কাজ—পড়াশোনা, চাকরি, ব্যবসা, পরিবারের দেখাশোনা—হালাল পথে ও সঠিক নিয়তে করলে তা আখিরাতের পাথেয় হয়ে যায়। সমস্যা দুনিয়া হাতে থাকায় নয়, দুনিয়া অন্তরে ঢুকে পড়ায়। আলেমরা বলেন, দুনিয়া থাকুক হাতে, অন্তরে নয়।</p><h2>প্রকৃত ধনী কে?</h2><p>রাসূল ﷺ বলেছেন, সম্পদের প্রাচুর্যে ধনী হওয়া যায় না; প্রকৃত ধনী হলো অন্তরের ধনী (সহীহ বুখারী ৬৪৪৬, সহীহ মুসলিম ১০৫১)। তিনি আরও বলেছেন, আদম সন্তান বলে, আমার সম্পদ, আমার সম্পদ! অথচ তোমার সম্পদ তো শুধু তা-ই, যা তুমি খেয়ে শেষ করেছ, পরে পুরোনো করেছ, অথবা দান করে আগে পাঠিয়ে দিয়েছ (সহীহ মুসলিম ২৯৫৮)। বাকি সব রেখে যেতে হবে অন্যদের জন্য।</p><h2>দুনিয়ার ভালোবাসা মাপার কিছু প্রশ্ন</h2><ul><li>নামাজের সময় হলে কাজ থামাতে কি কষ্ট হয়?</li><li>দুনিয়ার কোনো ক্ষতিতে যতটা কষ্ট পাই, একটি নামাজ কাজা হলে কি ততটা পাই?</li><li>সম্পদ বাড়ার সাথে দানও কি বাড়ছে?</li><li>সন্তানের দুনিয়ার ক্যারিয়ার নিয়ে যতটা চিন্তা করি, তার দ্বীন নিয়ে কি ততটা করি?</li><li>মৃত্যুর কথা মনে হলে কি প্রস্তুতির তাগিদ অনুভব করি, নাকি এড়িয়ে যাই?</li></ul><h2>ভারসাম্যের বাস্তব উপায়</h2><ul><li><strong>নিয়ত শুদ্ধ করুন:</strong> চাকরি বা ব্যবসার শুরুতে নিয়ত করুন—পরিবারের হালাল রিজিক, মানুষের উপকার, আল্লাহর সন্তুষ্টি। তখন অফিসের প্রতিটি ঘণ্টাও ইবাদত হতে পারে।</li><li><strong>মৃত্যুর স্মরণ:</strong> রাসূল ﷺ বলেছেন, স্বাদ বিনাশকারী মৃত্যুকে বেশি বেশি স্মরণ করো (জামে তিরমিযী ২৩০৭)। এটা হতাশার জন্য নয়, অগ্রাধিকার ঠিক রাখার জন্য।</li><li><strong>আখিরাতের সঞ্চয়:</strong> দুনিয়ার জন্য যেমন সঞ্চয় করি, আখিরাতের জন্যও নিয়মিত "সঞ্চয়" করুন: সদকায়ে জারিয়া, ইলম শেখানো, নেক সন্তান গড়া (সহীহ মুসলিম ১৬৩১)।</li><li><strong>অল্পে তুষ্টি:</strong> প্রয়োজন আর বিলাসিতার পার্থক্য বুঝুন। প্রতিটি নতুন মডেলের পেছনে না ছুটে যা আছে তার জন্য শুকরিয়া আদায় করুন।</li><li><strong>কবর জিয়ারত:</strong> মাঝে মাঝে কবরস্থানে যান; সেখানে শুয়ে থাকা মানুষগুলোরও স্বপ্ন, পরিকল্পনা আর ব্যস্ততা ছিল।</li></ul><h2>দুনিয়াবি সাফল্য কি খারাপ?</h2><p>সাহাবিদের মধ্যে ধনী মানুষও ছিলেন, যেমন উসমান (রা.) ও আব্দুর রহমান ইবনে আওফ (রা.)। তাঁদের সম্পদ তাঁদের আল্লাহ থেকে দূরে সরায়নি, বরং আল্লাহর পথে ব্যয়ের মাধ্যম হয়েছে। আবার দরিদ্র সাহাবিরাও ছিলেন, যাঁরা অভাবে ধৈর্য ধরে মর্যাদা পেয়েছেন। অর্থাৎ ধনী বা গরিব হওয়া নিজে সফলতা বা ব্যর্থতার মাপকাঠি নয়। মাপকাঠি হলো, যে অবস্থায় আল্লাহ রেখেছেন, সেই অবস্থায় আমি কীভাবে চলছি: সচ্ছলতায় কৃতজ্ঞ ও দানশীল, অভাবে ধৈর্যশীল ও আত্মমর্যাদাসম্পন্ন।</p><p>তাই একজন মুসলিম তরুণ ভালো ফলাফল, ভালো চাকরি বা সফল ব্যবসার স্বপ্ন দেখতেই পারেন। শুধু খেয়াল রাখতে হবে, সেই স্বপ্নের পথে যেন নামাজ, হালাল-হারাম আর মানুষের হক বিসর্জন না যায়। দুনিয়ার লক্ষ্য তখনই সুন্দর, যখন তা আখিরাতের লক্ষ্যের অধীনে থাকে।</p><blockquote>দুনিয়া একটি সেতু; সেতুর ওপর কেউ বাড়ি বানায় না।</blockquote><p>আল্লাহ বলেছেন, এই দুনিয়ার জীবন খেলাধুলা ছাড়া কিছু নয়; আর আখিরাতের ঘরই প্রকৃত জীবন, যদি তারা জানত (সূরা আল-আনকাবুত ২৯:৬৪)। আজ নিজের দিনের রুটিনটা একবার দেখুন: দুনিয়ার জন্য কত ঘণ্টা, আখিরাতের জন্য কত মিনিট? তারপর অন্তত একটি ছোট পরিবর্তন আনুন, যা আপনার স্থায়ী ঠিকানার জন্য কাজে লাগবে।</p>', ARRAY['akhirah', 'dunya', 'zuhd', 'tazkiyah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('9baeab49-01a3-56bf-b27b-5dc883ada30c', 'team', 'Islamic Studio', 'bn', 'জিহ্বার হেফাজত: গিবত, মিথ্যা ও চোগলখুরি', 'ছোট্ট একটি অঙ্গ, অথচ জান্নাত-জাহান্নামের পথ ঠিক করে দিতে পারে। গিবত, চোগলখুরি, মিথ্যা ও অনর্থক কথার ভয়াবহতা এবং জিহ্বাকে নিয়ন্ত্রণে রাখার বাস্তব কৌশল।', '<p>আমাদের শরীরের সবচেয়ে ছোট অঙ্গগুলোর একটি জিহ্বা, কিন্তু এর ক্ষমতা বিশাল। একটি কথায় সম্পর্ক গড়ে ওঠে, আরেকটি কথায় ভেঙে যায়। একটি কথায় কারও মন ভালো হয়, আরেকটি কথায় কেউ সারা জীবনের ক্ষত বয়ে বেড়ায়। আর সবচেয়ে ভয়ের কথা, একটি কথাই কখনো মানুষকে আল্লাহর সন্তুষ্টির উচ্চ স্তরে তুলে দেয়, আবার একটি কথাই তাকে জাহান্নামের গভীরে ফেলে দিতে পারে।</p><h2>প্রতিটি কথা লিপিবদ্ধ</h2><p>আল্লাহ বলেছেন, মানুষ যে কথাই উচ্চারণ করে, তার কাছে একজন সদা প্রস্তুত প্রহরী রয়েছে (সূরা কাফ ৫০:১৮)। তিনি মুমিনদের নির্দেশ দিয়েছেন, আল্লাহকে ভয় করো এবং সঠিক কথা বলো; তাহলে তিনি তোমাদের কাজ সংশোধন করে দেবেন এবং গুনাহ মাফ করবেন (সূরা আল-আহযাব ৩৩:৭০-৭১)। লক্ষ করুন, সঠিক কথার পুরস্কার হিসেবে কাজ সংশোধনের প্রতিশ্রুতি দেওয়া হয়েছে। যার কথা ঠিক, তার জীবনও ধীরে ধীরে ঠিক হয়ে আসে। অন্যত্র আল্লাহ বলেছেন, আমার বান্দাদের বলো, তারা যেন সর্বোত্তম কথা বলে; নিশ্চয়ই শয়তান তাদের মধ্যে বিভেদ সৃষ্টি করে (সূরা আল-ইসরা ১৭:৫৩)।</p><p>রাসূল ﷺ বলেছেন, বান্দা কখনো আল্লাহর সন্তুষ্টির এমন কথা বলে, যার গুরুত্ব সে বোঝে না, অথচ এর কারণে আল্লাহ তার মর্যাদা বহু গুণ বাড়িয়ে দেন। আবার বান্দা কখনো আল্লাহর অসন্তুষ্টির এমন কথা বলে, যার গুরুত্ব সে বোঝে না, অথচ এর কারণে সে জাহান্নামে পড়ে যায় (সহীহ বুখারী ৬৪৭৮)। আরেক বর্ণনায় এসেছে, সে এর কারণে জাহান্নামে পূর্ব ও পশ্চিমের দূরত্বের চেয়েও বেশি গভীরে পড়ে যায় (সহীহ বুখারী ৬৪৭৭, সহীহ মুসলিম ২৯৮৮)।</p><p>মুআজ ইবনে জাবাল (রা.)-কে রাসূল ﷺ দ্বীনের অনেক গুরুত্বপূর্ণ বিষয় শেখানোর পর নিজের জিহ্বা ধরে বললেন, এটাকে সংযত রাখো। মুআজ জিজ্ঞেস করলেন, আমরা যা বলি তার জন্যও কি আমাদের পাকড়াও করা হবে? তিনি বললেন, মানুষকে মুখের ওপর ভর করে জাহান্নামে নিক্ষেপ করার কারণ তো তাদের জিহ্বার ফসলই (জামে তিরমিযী ২৬১৬)।</p><h2>গিবত: মৃত ভাইয়ের গোশত</h2><p>রাসূল ﷺ সাহাবিদের জিজ্ঞেস করলেন, তোমরা কি জানো গিবত কী? তারা বললেন, আল্লাহ ও তাঁর রাসূল ভালো জানেন। তিনি বললেন, তোমার ভাইয়ের এমন কিছু আলোচনা করা, যা সে অপছন্দ করে। জিজ্ঞেস করা হলো, যদি সেই দোষ সত্যিই তার মধ্যে থাকে? তিনি বললেন, যা বলছ তা যদি তার মধ্যে থাকে, তবেই তো গিবত করলে; আর যদি না থাকে, তবে তো তুমি তাকে অপবাদ দিলে (সহীহ মুসলিম ২৫৮৯)।</p><p>আমাদের সমাজে প্রচলিত একটা অজুহাত হলো, "আমি তো সত্যি কথাই বলছি।" এই হাদিস সেই অজুহাতকে বাতিল করে দিয়েছে। সত্য দোষ বলাই গিবত; মিথ্যা দোষ বলা আরও বড় অপরাধ, অপবাদ। আল্লাহ গিবতকে তুলনা করেছেন মৃত ভাইয়ের গোশত খাওয়ার সাথে, যা প্রত্যেকেই ঘৃণা করে (সূরা আল-হুজুরাত ৪৯:১২)।</p><p>আলেমরা কিছু সীমিত প্রয়োজনের কথা উল্লেখ করেছেন, যেখানে কারও দোষ উল্লেখ করা বৈধ: যেমন জুলুমের বিচার চাওয়া, বিয়ে বা ব্যবসার ব্যাপারে পরামর্শ চাওয়া হলে সতর্ক করা, কিংবা কাউকে ক্ষতি থেকে বাঁচানো। কিন্তু এগুলো ব্যতিক্রম, এবং তাও প্রয়োজনের সীমায়; আড্ডার বিনোদন নয়।</p><h2>চোগলখুরি: সম্পর্কের বিষ</h2><p>একজনের কথা আরেকজনের কাছে লাগিয়ে বিবাদ সৃষ্টি করাকে চোগলখুরি বা নামিমা বলে। রাসূল ﷺ বলেছেন, চোগলখোর জান্নাতে প্রবেশ করবে না (সহীহ বুখারী ৬০৫৬, সহীহ মুসলিম ১০৫)। পরিবারে, অফিসে, আত্মীয়দের মধ্যে কত সম্পর্ক যে এই "অমুক তোমার সম্পর্কে এই বলেছে" ধরনের কথায় নষ্ট হয়েছে! কেউ আপনার কাছে অন্যের কথা লাগাতে এলে তাকে থামিয়ে দিন। মনে রাখবেন, যে আপনার কাছে অন্যের কথা নিয়ে আসে, সে অন্যের কাছেও আপনার কথা নিয়ে যায়।</p><h2>মিথ্যা: মুনাফিকের চিহ্ন</h2><p>রাসূল ﷺ বলেছেন, মুনাফিকের চিহ্ন তিনটি: যখন কথা বলে মিথ্যা বলে, যখন ওয়াদা করে ভঙ্গ করে, আর যখন তার কাছে আমানত রাখা হয় খেয়ানত করে (সহীহ বুখারী ৩৩, সহীহ মুসলিম ৫৯)। তিনি আরও বলেছেন, সত্য নেকির দিকে পথ দেখায়, আর নেকি জান্নাতের দিকে; আর মিথ্যা পাপাচারের দিকে পথ দেখায়, আর পাপাচার জাহান্নামের দিকে। মানুষ মিথ্যা বলতে থাকে, এক সময় আল্লাহর কাছে তাকে মিথ্যাবাদী হিসেবে লেখা হয় (সহীহ বুখারী ৬০৯৪, সহীহ মুসলিম ২৬০৭)।</p><p>আমাদের দৈনন্দিন জীবনে "ছোট" মিথ্যার ছড়াছড়ি: ফোনে "রাস্তায় আছি" অথচ এখনো বাসায়, শিশুকে ভয় দেখাতে বানানো কথা, ঠাট্টার ছলে মিথ্যা। মজা করেও মিথ্যা না বলার চেষ্টা করুন; শিশুরা আমাদের ছোট মিথ্যা থেকেই মিথ্যা বলা শেখে।</p><h2>অনর্থক কথা ও তর্ক</h2><p>সব কথা গুনাহ না হলেও অনেক কথা অনর্থক। রাসূল ﷺ বলেছেন, যে আল্লাহ ও আখিরাতে বিশ্বাস রাখে, সে যেন ভালো কথা বলে অথবা চুপ থাকে (সহীহ বুখারী ৬০১৮, সহীহ মুসলিম ৪৭)। আর তিনি বলেছেন, মুসলিম সেই ব্যক্তি, যার জিহ্বা ও হাত থেকে অন্য মুসলিমরা নিরাপদ (সহীহ বুখারী ১০, সহীহ মুসলিম ৪০)। তিনি আরও প্রতিশ্রুতি দিয়েছেন, যে ব্যক্তি তার দুই চোয়ালের মাঝের অঙ্গ (জিহ্বা) এবং দুই পায়ের মাঝের অঙ্গের হেফাজতের নিশ্চয়তা দেবে, আমি তার জন্য জান্নাতের নিশ্চয়তা দেব (সহীহ বুখারী ৬৪৭৪)।</p><h2>জিহ্বা নিয়ন্ত্রণের বাস্তব কৌশল</h2><ul><li><strong>বলার আগে তিন ছাঁকনি:</strong> কথাটা কি সত্য? কথাটা কি উপকারী? কথাটা কি এখন বলা দরকার? তিনটির একটিতেও আটকে গেলে চুপ থাকুন।</li><li><strong>অনুপস্থিত মানুষের পক্ষ নিন:</strong> আড্ডায় কারও গিবত শুরু হলে প্রসঙ্গ বদলে দিন, অথবা তার কোনো ভালো দিক উল্লেখ করুন। এতে নিজেও বাঁচবেন, অন্যদেরও বাঁচাবেন।</li><li><strong>রাগের সময় নীরবতা:</strong> রাগের মুহূর্তে বলা কথাই সবচেয়ে বেশি ক্ষতি করে। রাগ উঠলে আগে চুপ থাকুন।</li><li><strong>জিহ্বাকে জিকিরে ব্যস্ত রাখুন:</strong> খালি জিহ্বা অনর্থক কথা খোঁজে। হাঁটতে, অপেক্ষা করতে, কাজের ফাঁকে সুবহানাল্লাহ, আলহামদুলিল্লাহ, ইস্তিগফার পড়ুন।</li><li><strong>দিনের শেষে হিসাব:</strong> ঘুমানোর আগে ভাবুন, আজ কার সম্পর্কে কী বলেছি? কাউকে কষ্ট দিয়েছি কি? প্রয়োজনে পরের দিন ক্ষমা চেয়ে নিন।</li><li><strong>যার গিবত করেছেন:</strong> আলেমরা বলেন, গিবতের তওবা হলো অনুতাপ, আর যার গিবত করেছেন তার জন্য দোয়া করা ও যেখানে গিবত করেছেন সেখানে তার ভালো দিক তুলে ধরা। সরাসরি জানালে নতুন ফিতনা না হলে ক্ষমাও চেয়ে নেওয়া যায়।</li></ul><blockquote>যে কথা না বলার জন্য আজ আফসোস হয়, তা কাল সাক্ষী হয়ে দাঁড়াবে না; যে কথা বলে ফেলার জন্য আফসোস হয়, তা হতে পারে।</blockquote><p>আজ থেকে একটি চ্যালেঞ্জ নিন: পুরো এক দিন কারও অনুপস্থিতিতে তার সম্পর্কে এমন কিছু বলবেন না, যা সে শুনলে কষ্ট পেত। দিনের শেষে দেখবেন, অন্তর কতটা হালকা লাগছে।</p>', ARRAY['tongue', 'gheebah', 'akhlaq', 'truthfulness']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('e0a6c3a1-1c38-5c14-83ff-d528208117ef', 'team', 'Islamic Studio', 'bn', 'সময়ের মূল্য: জীবন মানে কয়েকটি দিন', 'সূরা আল-আসর থেকে শুরু করে কিয়ামতের দিনের প্রশ্ন পর্যন্ত, ইসলাম সময়কে কীভাবে দেখে। সময় নষ্টের আধুনিক ফাঁদ আর ইসলামি দৃষ্টিকোণ থেকে দিনের পরিকল্পনা।', '<p>হাসান বসরি (রহ.)-এর নামে একটি প্রসিদ্ধ উক্তি আছে: হে আদম সন্তান, তুমি তো কয়েকটি দিনের সমষ্টি; যখনই একটি দিন চলে যায়, তোমার একটি অংশ চলে যায়। কথাটা ভাবলে গা শিউরে ওঠে। আমাদের জীবন কোনো অসীম সম্পদ নয়; এটি গোনা কয়েকটি দিন, ঘণ্টা আর নিঃশ্বাস। প্রতিটি মুহূর্ত যা চলে যায়, তা আর ফেরে না। অথচ সময়ই সম্ভবত সেই সম্পদ, যা আমরা সবচেয়ে বেশি অবহেলায় খরচ করি।</p><h2>সময়ের কসম</h2><p>আল্লাহ তাআলা কুরআনে বিভিন্ন সময়ের কসম খেয়েছেন: ভোরের, দিনের, রাতের, পূর্বাহ্নের। আর একটি পুরো সূরা শুরু করেছেন সময়ের কসম দিয়ে: কালের শপথ, নিশ্চয়ই মানুষ ক্ষতির মধ্যে আছে; তবে তারা নয়, যারা ঈমান এনেছে, সৎকর্ম করেছে, পরস্পরকে সত্যের উপদেশ দিয়েছে এবং ধৈর্যের উপদেশ দিয়েছে (সূরা আল-আসর ১০৩:১-৩)। ইমাম শাফেয়ি (রহ.) সম্পর্কে প্রসিদ্ধ আছে, তিনি বলেছেন, মানুষ যদি শুধু এই সূরাটি নিয়ে চিন্তা করত, তবে এটিই তাদের জন্য যথেষ্ট হতো।</p><p>সূরাটির বার্তা স্পষ্ট: সময় চলে যাচ্ছে, আর এর সাথে মানুষ স্বাভাবিকভাবেই ক্ষতির দিকে যাচ্ছে, যদি না সে চারটি কাজে সময়কে বিনিয়োগ করে: ঈমান, সৎকর্ম, সত্যের দাওয়াত এবং ধৈর্যের দাওয়াত।</p><h2>যে নিয়ামতে আমরা প্রতারিত</h2><p>রাসূল ﷺ বলেছেন, দুটি নিয়ামত এমন, যে বিষয়ে অনেক মানুষ প্রতারিত: সুস্থতা ও অবসর (সহীহ বুখারী ৬৪১২)। প্রতারিত হওয়া মানে এমন ব্যবসায়ীর মতো, যে মূল্যবান পণ্য সস্তায় বিক্রি করে দেয়। আমরা সুস্থ থাকতে আর অবসর থাকতে ভাবি, সময় তো অনেক আছে; পরে করব। তারপর একদিন অসুস্থতা বা ব্যস্ততা আসে, তখন আফসোস ছাড়া কিছু থাকে না।</p><h2>কিয়ামতের দিনের প্রশ্ন</h2><p>রাসূল ﷺ বলেছেন, কিয়ামতের দিন কোনো বান্দার পা নড়বে না, যতক্ষণ না তাকে জিজ্ঞাসা করা হবে: তার জীবন সম্পর্কে, কোথায় তা শেষ করেছে; তার জ্ঞান সম্পর্কে, তা দিয়ে কী করেছে; তার সম্পদ সম্পর্কে, কোথা থেকে উপার্জন করেছে ও কোথায় ব্যয় করেছে; এবং তার শরীর সম্পর্কে, কোথায় তা ক্ষয় করেছে (জামে তিরমিযী ২৪১৭)। চারটি প্রশ্নের মধ্যে প্রথমটিই সময় নিয়ে, আর শেষটিও আসলে সময়েরই আরেক রূপ।</p><p>কুরআনে জাহান্নামবাসীদের আকুতি বর্ণিত হয়েছে: হে আমাদের রব, আমাদের বের করুন, আমরা আগে যা করতাম তার বদলে সৎকাজ করব। তখন বলা হবে, আমি কি তোমাদের এত দীর্ঘ জীবন দিইনি, যাতে কেউ উপদেশ গ্রহণ করতে চাইলে করতে পারত? আর তোমাদের কাছে সতর্ককারীও এসেছিল (সূরা ফাতির ৩৫:৩৭)। আরেক আয়াতে মৃত্যুর মুহূর্তের আফসোস: হে আমার রব, আমাকে যদি আরও কিছু সময় দিতেন, তাহলে আমি সদকা করতাম এবং নেককারদের অন্তর্ভুক্ত হতাম (সূরা আল-মুনাফিকুন ৬৩:১০)।</p><h2>সময় নষ্টের আধুনিক ফাঁদ</h2><ul><li><strong>অসীম স্ক্রল:</strong> সোশ্যাল মিডিয়া আর ছোট ভিডিওর অ্যাপগুলো এমনভাবে তৈরি, যাতে থামার কোনো স্বাভাবিক বিন্দু না থাকে।</li><li><strong>"একটু পরে" অভ্যাস:</strong> গড়িমসি সময়ের সবচেয়ে বড় চোর। কাব ইবনে মালিক (রা.)-এর ঘটনা এর জ্বলন্ত উদাহরণ; তিনি "কাল প্রস্তুতি নেব" করতে করতে তাবুক অভিযান হারিয়েছিলেন (সহীহ বুখারী ৪৪১৮)।</li><li><strong>অনর্থক আড্ডা ও তর্ক:</strong> যে আলোচনা থেকে দুনিয়া বা আখিরাতের কোনো উপকার নেই।</li><li><strong>অপরিকল্পিত দিন:</strong> যে দিনের কোনো পরিকল্পনা নেই, সে দিন অন্যের পরিকল্পনা আর হঠাৎ আসা বিষয়ে খরচ হয়ে যায়।</li></ul><h2>ইসলামের সময় ব্যবস্থাপনা</h2><p>একজন মুসলিমের দিন এমনিতেই একটি সুন্দর কাঠামোয় বাঁধা: পাঁচ ওয়াক্ত নামাজ। ফজর দিয়ে দিন শুরু, জোহরে মধ্যাহ্নের বিরতি, আসরে বিকেলের মোড়, মাগরিবে দিনের সমাপ্তি, ইশায় রাতের শুরু। এই পাঁচটি খুঁটির চারপাশে দিনের কাজ সাজালে দিন আপনাআপনি সুশৃঙ্খল হয়ে যায়।</p><ul><li><strong>ভোরের বরকত:</strong> রাসূল ﷺ দোয়া করেছেন, হে আল্লাহ, আমার উম্মতের জন্য তাদের ভোরবেলায় বরকত দিন (সুনান আবি দাউদ ২৬০৬, জামে তিরমিযী ১২১২)। দিনের সবচেয়ে গুরুত্বপূর্ণ কাজগুলো ফজরের পরের সময়ে করার চেষ্টা করুন।</li><li><strong>নামাজভিত্তিক পরিকল্পনা:</strong> "ফজর থেকে জোহর: অফিসের প্রধান কাজ", "আসরের পর: পরিবার ও ব্যায়াম", "ইশার পর: পড়া ও ঘুম"—এভাবে দিনকে ভাগ করুন।</li><li><strong>ইশার পর দ্রুত ঘুম:</strong> রাসূল ﷺ ইশার আগে ঘুমানো এবং ইশার পর অনর্থক কথাবার্তা অপছন্দ করতেন (সহীহ বুখারী ৫৬৮)। আগে ঘুমালে ভোরে ওঠা সহজ হয়, আর দিনটা বড় মনে হয়।</li><li><strong>অপেক্ষার সময় কাজে লাগান:</strong> যানজট, লাইন, অপেক্ষা—এই "মরা সময়গুলো" জিকির, কুরআন শোনা বা উপকারী কিছু পড়ায় কাজে লাগান।</li><li><strong>সাপ্তাহিক পর্যালোচনা:</strong> সপ্তাহে একবার দেখুন, সময় কোথায় গেল। স্ক্রিন টাইম রিপোর্ট এ ক্ষেত্রে চোখ খুলে দেয়।</li></ul><h2>বিশ্রামও সময়ের সঠিক ব্যবহার</h2><p>সময়ের মূল্য বোঝা মানে সারাক্ষণ ব্যস্ত থাকা নয়। পরিবারের সাথে সময় কাটানো, শরীরের প্রয়োজনে ঘুম, বৈধ বিনোদন—এসবও সঠিক নিয়তে হলে সময়ের সদ্ব্যবহার। রাসূল ﷺ নিজে পরিবারের সাথে সময় কাটাতেন, হাসতেন, ঘরের কাজ করতেন। সমস্যা বিশ্রামে নয়, উদ্দেশ্যহীনতায়।</p><h2>যৌবন: জীবনের সবচেয়ে মূল্যবান অধ্যায়</h2><p>শক্তি, স্বাস্থ্য আর অবসর—তিনটিই সবচেয়ে বেশি থাকে যৌবনে। হাশরের ময়দানে আরশের ছায়ায় যে সাত শ্রেণির মানুষ আশ্রয় পাবেন, তাদের একজন সেই যুবক, যে আল্লাহর ইবাদতে বেড়ে উঠেছে (সহীহ বুখারী ৬৬০, সহীহ মুসলিম ১০৩১)। তরুণরা যদি এখনই কুরআন শেখা, নামাজে নিয়মিত হওয়া আর ভালো অভ্যাস গড়ায় সময় দেন, তবে সারা জীবন সেই বিনিয়োগের ফল পাবেন।</p><h2>যদি অনেক সময় নষ্ট হয়ে গিয়ে থাকে</h2><p>অনেকে পেছনে তাকিয়ে আফসোস করেন: কত বছর অবহেলায় কেটে গেল! এই আফসোস যদি হতাশায় পরিণত হয়, তবে তা আরও সময় নষ্ট করে। বরং আফসোসকে তওবা আর নতুন শুরুর শক্তিতে পরিণত করুন। আল্লাহ তওবাকারীদের অতীতের গুনাহকেও নেকিতে বদলে দেওয়ার কথা বলেছেন (সূরা আল-ফুরকান ২৫:৭০)। যে সময় চলে গেছে তা ফেরানো যাবে না, কিন্তু যে সময় বাকি আছে, তা এখনো আপনার হাতে। আজকের দিনটিই বাকি জীবনের প্রথম দিন।</p><p>ছোট লক্ষ্য দিয়ে শুরু করুন: প্রতিদিন পনেরো মিনিট কুরআন, দশ মিনিট উপকারী কিছু পড়া, পাঁচ মিনিট দিনের হিসাব। এক মাস পর এই ছোট সময়গুলো জমে বড় কিছুতে পরিণত হবে।</p><blockquote>সময় তলোয়ারের মতো; তুমি তাকে না কাটলে সে তোমাকে কেটে ফেলবে।</blockquote><p>আজ রাতে ঘুমানোর আগে আগামীকালের একটি ছোট পরিকল্পনা লিখুন: পাঁচ ওয়াক্ত নামাজের সময়, তিনটি গুরুত্বপূর্ণ কাজ, আর একটি আখিরাতের কাজ। ইসলামিক স্টুডিওর নামাজের সময়সূচি আর ইবাদত ট্র্যাকার আপনার দিনটিকে নামাজকেন্দ্রিক করে সাজাতে সাহায্য করবে।</p>', ARRAY['time', 'productivity', 'tazkiyah', 'youth']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('55ee60d3-1ec4-540e-8054-119a02da3b05', 'team', 'Islamic Studio', 'bn', 'আমানতদারি ও ওয়াদা রক্ষা', 'আমানত শুধু গচ্ছিত টাকা নয়: দায়িত্ব, গোপন কথা, পদ, সময়, এমনকি নিজের শরীরও আমানত। কুরআন-হাদিসে আমানত ও প্রতিশ্রুতির গুরুত্ব এবং দৈনন্দিন জীবনে তার প্রয়োগ।', '<p>নবুয়তের আগেই মক্কার মানুষ মুহাম্মাদ ﷺ-কে "আল-আমিন", অর্থাৎ বিশ্বস্ত নামে ডাকত। যারা তাঁর দাওয়াতের বিরোধিতা করত, তারাও নিজেদের মূল্যবান জিনিস তাঁর কাছে গচ্ছিত রাখত। সীরাতগ্রন্থে বর্ণিত আছে, হিজরতের রাতে, যখন কুরাইশরা তাঁকে হত্যার জন্য ঘর ঘেরাও করেছিল, তখনও তিনি আলী (রা.)-কে মক্কায় রেখে গিয়েছিলেন, যাতে মানুষের গচ্ছিত আমানত তাদের ফিরিয়ে দেওয়া যায়। শত্রুর আমানতও তিনি খেয়ানত করেননি। এই হলো ইসলামের আমানতদারির মান।</p><h2>কুরআনে আমানত</h2><p>আল্লাহ তাআলা নির্দেশ দিয়েছেন, নিশ্চয়ই আল্লাহ তোমাদের আদেশ দিচ্ছেন আমানত তার হকদারের কাছে পৌঁছে দিতে, আর যখন মানুষের মধ্যে বিচার করবে তখন ন্যায়ের সাথে বিচার করতে (সূরা আন-নিসা ৪:৫৮)। সফল মুমিনদের গুণ বর্ণনায় বলেছেন, তারা নিজেদের আমানত ও প্রতিশ্রুতির প্রতি যত্নবান (সূরা আল-মুমিনুন ২৩:৮)। আর সতর্ক করেছেন, হে মুমিনগণ, জেনেশুনে আল্লাহ ও রাসূলের সাথে খেয়ানত করো না এবং নিজেদের আমানতেও খেয়ানত করো না (সূরা আল-আনফাল ৮:২৭)।</p><p>আমানতের ভার কত বড়, তা বোঝাতে আল্লাহ বলেছেন, আমি আসমান, জমিন ও পর্বতমালার সামনে আমানত পেশ করেছিলাম, তারা তা বহন করতে অস্বীকার করল এবং ভীত হলো; কিন্তু মানুষ তা বহন করল (সূরা আল-আহযাব ৩৩:৭২)। আলেমরা ব্যাখ্যা করেছেন, এই আমানত হলো দ্বীনের দায়িত্ব, আল্লাহর আদেশ-নিষেধ পালনের ভার। অর্থাৎ পুরো জীবনটাই একটি আমানত।</p><h2>প্রতিশ্রুতি রক্ষা</h2><p>আল্লাহ বলেছেন, হে মুমিনগণ, তোমরা চুক্তিগুলো পূর্ণ করো (সূরা আল-মায়িদা ৫:১)। আরও বলেছেন, প্রতিশ্রুতি পূর্ণ করো; নিশ্চয়ই প্রতিশ্রুতি সম্পর্কে জিজ্ঞাসা করা হবে (সূরা আল-ইসরা ১৭:৩৪)। রাসূল ﷺ মুনাফিকের তিনটি চিহ্নের কথা বলেছেন: কথা বললে মিথ্যা বলে, ওয়াদা করলে ভঙ্গ করে, আর আমানত রাখা হলে খেয়ানত করে (সহীহ বুখারী ৩৩, সহীহ মুসলিম ৫৯)। লক্ষ করুন, তিনটির দুটিই এই আলোচনার বিষয়: ওয়াদা ও আমানত।</p><h2>আমানত কত রকম?</h2><ul><li><strong>গচ্ছিত সম্পদ:</strong> কেউ টাকা, জিনিস বা কাগজপত্র রাখতে দিলে তা যত্নে রাখা এবং চাওয়ামাত্র ফিরিয়ে দেওয়া। অনুমতি ছাড়া তা ব্যবহার করা খেয়ানত।</li><li><strong>ধার:</strong> ধার নেওয়া বই, গাড়ি, জিনিসপত্র যত্নে ব্যবহার করে সময়মতো ফেরত দেওয়া। কত বই যে "ধার" নিয়ে আর ফেরত যায় না!</li><li><strong>গোপন কথা:</strong> রাসূল ﷺ বলেছেন, কেউ যখন কোনো কথা বলে তারপর এদিক-ওদিক তাকায়, সেই কথা আমানত (জামে তিরমিযী ১৯৫৯)। অর্থাৎ বক্তা যদি ইঙ্গিত দেন যে কথাটা গোপন, তবে তা প্রকাশ করা খেয়ানত। স্বামী-স্ত্রীর একান্ত বিষয় তো আরও বড় আমানত।</li><li><strong>পরামর্শ:</strong> কেউ পরামর্শ চাইলে নিজের স্বার্থ না দেখে আন্তরিকভাবে সঠিক পরামর্শ দেওয়া।</li><li><strong>পদ ও দায়িত্ব:</strong> চাকরি, নেতৃত্ব, প্রশাসনিক পদ—সবই আমানত। রাসূল ﷺ বলেছেন, যখন আমানত নষ্ট করা হবে, তখন কিয়ামতের অপেক্ষা করো। জিজ্ঞেস করা হলো, কীভাবে নষ্ট করা হবে? তিনি বললেন, যখন দায়িত্ব অযোগ্য লোকের হাতে দেওয়া হবে (সহীহ বুখারী ৫৯)।</li><li><strong>কর্মঘণ্টা:</strong> বেতনের বিনিময়ে যে সময় দেওয়ার চুক্তি, সে সময় ফাঁকি দেওয়া আমানতের খেয়ানত।</li><li><strong>পরিবার:</strong> তোমরা প্রত্যেকেই দায়িত্বশীল, আর প্রত্যেককে তার দায়িত্ব সম্পর্কে জিজ্ঞাসা করা হবে (সহীহ বুখারী ৮৯৩, সহীহ মুসলিম ১৮২৯)। স্ত্রী, সন্তান, বৃদ্ধ মা-বাবা আল্লাহর দেওয়া আমানত।</li><li><strong>নিজের শরীর ও প্রতিভা:</strong> চোখ, কান, হাত, মেধা—এসবও আল্লাহর আমানত, যার ব্যবহার সম্পর্কে প্রশ্ন করা হবে (সূরা আল-ইসরা ১৭:৩৬)।</li><li><strong>ভোট ও সাক্ষ্য:</strong> সাক্ষ্য দেওয়া বা কাউকে দায়িত্বের জন্য বেছে নেওয়াও আমানত; ব্যক্তিগত লাভে বা অন্ধ পক্ষপাতে তা ব্যবহার করা উচিত নয়।</li></ul><h2>ওয়াদা ভাঙার সাধারণ রূপ</h2><ul><li>"পাঁচ মিনিটে আসছি" বলে এক ঘণ্টা দেরি।</li><li>নির্দিষ্ট তারিখে ঋণ ফেরত দেওয়ার কথা দিয়ে না দেওয়া, এমনকি জানিয়েও না দেওয়া।</li><li>ব্যবসায় নির্ধারিত সময়ে মাল সরবরাহ না করা, বা নমুনার চেয়ে খারাপ মাল দেওয়া।</li><li>শিশুকে কিছু দেওয়ার কথা বলে ভুলে যাওয়া। শিশুরা এভাবেই শেখে যে কথা দেওয়া হালকা বিষয়।</li><li>নির্বাচনের আগে বা চাকরির ইন্টারভিউতে দেওয়া প্রতিশ্রুতি পরে ভুলে যাওয়া।</li></ul><p>অবশ্য কেউ যদি আন্তরিক ইচ্ছা থাকা সত্ত্বেও প্রকৃত অক্ষমতার কারণে ওয়াদা রক্ষা করতে না পারেন, তা মুনাফিকের চিহ্ন নয়। তবে তখনও উচিত আগেভাগে জানিয়ে দেওয়া, দুঃখ প্রকাশ করা এবং বিকল্প প্রস্তাব দেওয়া।</p><h2>ইনশাআল্লাহ: দায় এড়ানোর শব্দ নয়</h2><p>আল্লাহ শিখিয়েছেন, কোনো কাজ সম্পর্কে বলো না যে "আমি এটা আগামীকাল করব", আল্লাহ চাইলে—এ কথা যুক্ত না করে (সূরা আল-কাহফ ১৮:২৩-২৪)। ইনশাআল্লাহ বলা ঈমানের প্রকাশ: আমি চেষ্টা করব, বাকিটা আল্লাহর ইচ্ছা। কিন্তু দুঃখজনকভাবে আমাদের সমাজে অনেক সময় "ইনশাআল্লাহ" হয়ে গেছে ভদ্রভাবে না বলার উপায়, যার ভেতরে কাজটা করার কোনো ইচ্ছাই নেই। এভাবে আল্লাহর নামকে নিজের গাফিলতির আড়াল বানানো উচিত নয়। ইনশাআল্লাহ বলুন, এবং কাজটা করার পূর্ণ চেষ্টাও করুন।</p><h2>আমানতদার হওয়ার অভ্যাস</h2><ul><li><strong>লিখে রাখুন:</strong> কাকে কী কথা দিয়েছেন, কার কাছে কী ধার নিয়েছেন—একটা তালিকা রাখুন।</li><li><strong>কম প্রতিশ্রুতি, বেশি কাজ:</strong> যা পারবেন না, তার কথা দেবেন না। "দেখি" বা "চেষ্টা করব" বলাই সততা।</li><li><strong>অন্যের জিনিস নিজের চেয়ে বেশি যত্নে রাখুন।</strong></li><li><strong>অফিসের সম্পদ ব্যক্তিগত কাজে নয়:</strong> কাগজ, প্রিন্টার, গাড়ি, ইন্টারনেট—অনুমতির বাইরে ব্যবহার না করা।</li><li><strong>গোপন কথা গোপন রাখুন:</strong> "কাউকে বোলো না" বলে অন্যকে বলা আসলে খেয়ানত ছড়ানো।</li></ul><h2>মালিক ও নিয়োগকর্তার আমানত</h2><p>আমানতের দায়িত্ব শুধু কর্মচারীর নয়, নিয়োগকর্তারও। কর্মীর ন্যায্য পারিশ্রমিক সময়মতো দেওয়া, চুক্তির বাইরে অতিরিক্ত কাজ চাপিয়ে না দেওয়া, তার সম্মান রক্ষা করা—এসবও আমানত। শ্রমিককে তার ঘাম শুকানোর আগেই মজুরি দিয়ে দেওয়ার নির্দেশ সংবলিত হাদিসটি সুনান ইবনে মাজাহতে বর্ণিত হয়েছে, আর পাওনা পরিশোধে সামর্থ্যবানের গড়িমসিকে রাসূল ﷺ জুলুম বলেছেন (সহীহ বুখারী ২২৮৭, সহীহ মুসলিম ১৫৬৪)। গৃহকর্মী, দারোয়ান, ড্রাইভার—যারা আমাদের ঘরে কাজ করেন, তাদের বেতন আটকে রাখা বা অকারণে কেটে নেওয়া আমানতের খেয়ানত।</p><p>একইভাবে শিক্ষকের কাছে শিক্ষার্থী, চিকিৎসকের কাছে রোগী, দোকানির কাছে ক্রেতার বিশ্বাস—সবই আমানত। নিজের পেশায় যত্ন, দক্ষতা আর সততা দিয়ে কাজ করা তাই একজন মুমিনের ইবাদতেরই অংশ।</p><blockquote>মানুষ আপনার কথা ভুলে যেতে পারে, কিন্তু আপনি কথা রেখেছিলেন কি না, তা কখনো ভোলে না।</blockquote><p>একটি সমাজের ভিত দাঁড়িয়ে থাকে আস্থার ওপর। যখন মানুষ একে অপরের কথায় ভরসা করতে পারে, তখন ব্যবসা চলে, পরিবার টেকে, রাষ্ট্র শক্ত হয়। আজ নিজের দেওয়া প্রতিশ্রুতিগুলোর তালিকা করুন, আর যেগুলো অপূর্ণ আছে, সেগুলো পূরণের পরিকল্পনা নিন।</p>', ARRAY['amanah', 'promises', 'akhlaq', 'truthfulness']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('d8762bd1-f1ef-5ffb-acd3-65b30a503228', 'team', 'Islamic Studio', 'bn', 'আত্মীয়তার বন্ধন: ছিন্ন করলে ছিন্ন হয় রহমত', 'ব্যস্ততা, অভিমান আর সম্পত্তির বিবাদে আত্মীয়দের সাথে দূরত্ব বাড়ছে। সিলা রাহমি বা আত্মীয়তার সম্পর্ক রক্ষার মর্যাদা, ছিন্ন করার পরিণাম এবং ভাঙা সম্পর্ক জোড়া লাগানোর উপায়।', '<p>শহুরে ব্যস্ত জীবনে আমাদের অনেকের আত্মীয়দের সাথে যোগাযোগ সীমিত হয়ে এসেছে দুই ঈদ, বিয়ে আর জানাজায়। কারও সাথে পুরোনো অভিমান, কারও সাথে জমিজমার বিবাদ, কারও সাথে স্রেফ যোগাযোগ না রাখার অভ্যাস। অথচ ইসলামে আত্মীয়তার সম্পর্ক রক্ষা, যাকে আরবিতে সিলাতুর রাহিম বলা হয়, শুধু সামাজিক সৌজন্য নয়; এটি ঈমানের দাবি, রিজিক ও আয়ুতে বরকতের উপায় এবং জান্নাতে প্রবেশের শর্তের সাথে যুক্ত।</p><h2>কুরআনে আত্মীয়তার বন্ধন</h2><p>সূরা আন-নিসার প্রথম আয়াতেই আল্লাহ বলেছেন, সেই আল্লাহকে ভয় করো, যাঁর নামে তোমরা একে অপরের কাছে অধিকার দাবি করো, এবং আত্মীয়তার সম্পর্কের ব্যাপারেও সতর্ক থাকো (সূরা আন-নিসা ৪:১)। এখানে আল্লাহর ভয়ের সাথেই আত্মীয়তার বন্ধনের কথা এসেছে। বুদ্ধিমান মুমিনদের গুণ হিসেবে বলা হয়েছে, আল্লাহ যে সম্পর্ক অটুট রাখতে আদেশ করেছেন, তারা তা অটুট রাখে (সূরা আর-রাদ ১৩:২১)।</p><p>অন্যদিকে কঠোর সতর্কবাণী: ক্ষমতা পেলে তোমরা কি পৃথিবীতে বিপর্যয় সৃষ্টি করবে এবং আত্মীয়তার বন্ধন ছিন্ন করবে? এরাই তারা, যাদের আল্লাহ লানত করেছেন, তাদের বধির করেছেন এবং দৃষ্টিহীন করেছেন (সূরা মুহাম্মাদ ৪৭:২২-২৩)।</p><h2>আরশের সাথে ঝুলন্ত রাহিম</h2><p>রাসূল ﷺ বলেছেন, আল্লাহ যখন সৃষ্টিজগৎ সৃষ্টি শেষ করলেন, তখন রাহিম (আত্মীয়তা) দাঁড়িয়ে আশ্রয় চাইল। আল্লাহ বললেন, তুমি কি সন্তুষ্ট নও যে, যে তোমাকে জুড়ে রাখবে, আমি তাকে জুড়ে রাখব; আর যে তোমাকে ছিন্ন করবে, আমি তাকে ছিন্ন করব? সে বলল, অবশ্যই (সহীহ বুখারী ৫৯৮৭, সহীহ মুসলিম ২৫৫৪)। আত্মীয়তা রক্ষা মানে আল্লাহর সাথে সম্পর্ক রক্ষা; আর আত্মীয়তা ছিন্ন করা মানে আল্লাহর রহমত থেকে বিচ্ছিন্ন হওয়া।</p><h2>রিজিক ও আয়ুতে বরকত</h2><p>রাসূল ﷺ বলেছেন, যে চায় তার রিজিক প্রশস্ত হোক এবং তার আয়ু দীর্ঘ হোক, সে যেন আত্মীয়তার সম্পর্ক বজায় রাখে (সহীহ বুখারী ৫৯৮৬, সহীহ মুসলিম ২৫৫৭)। আমরা রিজিকের জন্য কত চেষ্টা করি, কত দোয়া করি; অথচ এই সহজ পথটির কথা প্রায় ভুলে যাই। হয়তো একটি ফোনকল, একটি সাক্ষাৎ, একটি উপহারই আমাদের রিজিকের বন্ধ দরজা খুলে দিতে পারে।</p><h2>ছিন্নকারীর পরিণাম</h2><p>রাসূল ﷺ বলেছেন, আত্মীয়তার সম্পর্ক ছিন্নকারী জান্নাতে প্রবেশ করবে না (সহীহ বুখারী ৫৯৮৪, সহীহ মুসলিম ২৫৫৬)। এর চেয়ে কঠোর সতর্কবাণী আর কী হতে পারে! জমির কয়েক শতাংশ, পুরোনো কোনো অপমান, বা কে আগে ফোন করবে—এই অহংকারের জন্য কি আমরা জান্নাত ঝুঁকিতে ফেলব?</p><h2>প্রকৃত সম্পর্ক রক্ষাকারী কে?</h2><p>আমরা অনেকেই ভাবি, যারা আমার খোঁজ নেয়, আমিও তাদের খোঁজ নিই; যারা নেয় না, তাদের সাথে আমার কী! রাসূল ﷺ এই ধারণা বদলে দিয়েছেন: প্রতিদান দেওয়া ব্যক্তি সম্পর্ক রক্ষাকারী নয়; বরং সম্পর্ক রক্ষাকারী সে, যার সাথে সম্পর্ক ছিন্ন করা হলে সে তা জুড়ে দেয় (সহীহ বুখারী ৫৯৯১)।</p><p>এক ব্যক্তি রাসূল ﷺ-কে বলল, আমার কিছু আত্মীয় আছে, আমি তাদের সাথে সম্পর্ক রাখি, তারা ছিন্ন করে; আমি তাদের সাথে ভালো ব্যবহার করি, তারা খারাপ ব্যবহার করে; আমি সহনশীল থাকি, তারা অজ্ঞের মতো আচরণ করে। রাসূল ﷺ বললেন, তুমি যেমন বলছ তেমন হলে তুমি যেন তাদের মুখে গরম ছাই পুরে দিচ্ছ; আর যতদিন তুমি এভাবে থাকবে, আল্লাহর পক্ষ থেকে তাদের বিরুদ্ধে তোমার সাথে একজন সাহায্যকারী থাকবে (সহীহ মুসলিম ২৫৫৮)।</p><h2>সম্পর্কচ্ছেদের সীমা</h2><p>মানুষে মানুষে মনোমালিন্য হতেই পারে। কিন্তু রাসূল ﷺ বলেছেন, কোনো মুসলিমের জন্য তার ভাইয়ের সাথে তিন দিনের বেশি সম্পর্ক ছিন্ন রাখা বৈধ নয়, যে দেখা হলে একজন এদিকে মুখ ফেরায়, আরেকজন ওদিকে; আর তাদের মধ্যে উত্তম সে, যে আগে সালাম দেয় (সহীহ বুখারী ৬০৭৭, সহীহ মুসলিম ২৫৬০)। এটি সাধারণ মুসলিম ভাইয়ের ক্ষেত্রে; আত্মীয়ের ক্ষেত্রে তো আরও বেশি প্রযোজ্য।</p><h2>নবীজির চরিত্রে আত্মীয়তা</h2><p>প্রথম ওহি নাজিলের পর রাসূল ﷺ যখন ভীত অবস্থায় ঘরে ফিরলেন, তখন খাদিজা (রা.) তাঁকে সান্ত্বনা দিয়ে বলেছিলেন, আল্লাহর কসম, আল্লাহ আপনাকে কখনো লাঞ্ছিত করবেন না; আপনি তো আত্মীয়তার সম্পর্ক রক্ষা করেন, অসহায়ের বোঝা বহন করেন, নিঃস্বকে উপার্জন করে দেন, মেহমানদারি করেন এবং বিপদে মানুষকে সাহায্য করেন (সহীহ বুখারী ৩, সহীহ মুসলিম ১৬০)। লক্ষ করুন, নবীজির গুণাবলির তালিকায় প্রথমেই এসেছে আত্মীয়তা রক্ষার কথা। নবুয়তের আগেই এটি ছিল তাঁর চরিত্রের পরিচয়।</p><h2>আত্মীয়কে দান: দ্বিগুণ সওয়াব</h2><p>রাসূল ﷺ বলেছেন, মিসকিনকে দান করা একটি সদকা; আর আত্মীয়কে দান করা দুটি: সদকা ও আত্মীয়তা রক্ষা (জামে তিরমিযী ৬৫৮)। আল্লাহও আদেশ করেছেন আত্মীয়কে তার হক দিতে (সূরা আল-ইসরা ১৭:২৬)। অভাবী আত্মীয়দের খোঁজ নেওয়া, তাদের সন্তানের পড়াশোনায় সাহায্য করা, যাকাতের হকদার হলে তাদের অগ্রাধিকার দেওয়া—এসব সম্পর্ক রক্ষার সবচেয়ে কার্যকর উপায়গুলোর একটি।</p><h2>সম্পর্ক রক্ষার বাস্তব উপায়</h2><ul><li><strong>নিয়মিত যোগাযোগ:</strong> সপ্তাহে একজন আত্মীয়কে ফোন করার অভ্যাস করুন। একটি তালিকা বানিয়ে পালাক্রমে সবাইকে।</li><li><strong>সাক্ষাৎ:</strong> বিশেষ উপলক্ষ ছাড়াও মাঝে মাঝে দেখা করতে যান, বিশেষ করে বয়স্ক আত্মীয়দের।</li><li><strong>অসুস্থতা ও বিপদে:</strong> আত্মীয়ের অসুস্থতা, বিপদ বা শোকের খবর পেলে সবার আগে পাশে দাঁড়ান।</li><li><strong>উপহার:</strong> ছোট উপহার মনের দূরত্ব কমায়।</li><li><strong>সন্তানদের যুক্ত করুন:</strong> সন্তানদের চাচা-মামা, খালা-ফুফুদের সাথে পরিচিত করান। আপনি না থাকলেও যেন এই বন্ধন টিকে থাকে।</li><li><strong>সম্পত্তির বিষয় পরিষ্কার রাখুন:</strong> উত্তরাধিকার আল্লাহর বিধান অনুযায়ী দ্রুত বণ্টন করুন। বোনদের অংশ আটকে রাখা আমাদের সমাজের একটি বড় জুলুম, যা অনেক পরিবার ভেঙে দেয়।</li></ul><h2>ভাঙা সম্পর্ক জোড়া লাগাতে</h2><p>যদি কোনো আত্মীয়ের সাথে দীর্ঘদিন সম্পর্ক বন্ধ থাকে, প্রথম পদক্ষেপটা আপনিই নিন। দোষ কার ছিল, সেই হিসাব আপাতত সরিয়ে রাখুন। একটা সালাম, একটা ছোট বার্তা, "কেমন আছেন" জিজ্ঞেস করা—এভাবে শুরু করুন। প্রয়োজনে পরিবারের কোনো সম্মানিত মুরুব্বিকে মধ্যস্থতাকারী করুন। অপর পক্ষ সাড়া না দিলেও আপনার চেষ্টা আল্লাহর কাছে লেখা থাকবে।</p><blockquote>যে আগে হাত বাড়ায়, সে হারে না; সে আল্লাহর কাছে জিতে যায়।</blockquote><p>আজই এমন একজন আত্মীয়কে ফোন করুন, যার সাথে অনেক দিন কথা হয়নি। কোনো কারণ লাগবে না; শুধু জিজ্ঞেস করুন, কেমন আছেন। হয়তো এই ফোনকলটিই আপনার রিজিক আর আয়ুর বরকতের কারণ হবে।</p>', ARRAY['family', 'kinship', 'silat-ar-rahim', 'akhlaq']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('bca0b798-e776-5f6f-b7b3-bb90ed363631', 'team', 'Islamic Studio', 'bn', 'জুমার দিন: সপ্তাহের ঈদ', 'জুমা কেন সপ্তাহের শ্রেষ্ঠ দিন, জুমার নামাজের গুরুত্ব, গোসল থেকে খুতবা পর্যন্ত সুন্নাহ আমল, দোয়া কবুলের সময় এবং জুমাকে পারিবারিক ইবাদতের দিন বানানোর উপায়।', '<p>আমাদের দেশে শুক্রবার মানে ছুটির দিন: দেরিতে ঘুম থেকে ওঠা, বাজার করা, অতিথি আপ্যায়ন, বেড়াতে যাওয়া। অনেকের কাছে জুমার নামাজ এই ব্যস্ত দিনের মাঝখানে একটা আধা ঘণ্টার দায়িত্ব, যেখানে খুতবা শেষ হওয়ার একটু আগে পৌঁছালেই চলে। অথচ রাসূল ﷺ জুমাকে বলেছেন সপ্তাহের শ্রেষ্ঠ দিন, আর আলেমরা একে বলেন মুসলিমদের সাপ্তাহিক ঈদ। এই দিনটিকে কাজে লাগালে সপ্তাহের বাকি দিনগুলোও বরকতময় হয়ে ওঠে।</p><h2>কুরআনে জুমা</h2><p>কুরআনে জুমার নামে একটি পূর্ণ সূরা আছে। সেখানে আল্লাহ বলেছেন, হে মুমিনগণ, জুমার দিন যখন নামাজের জন্য আহ্বান করা হয়, তখন আল্লাহর স্মরণের দিকে ধাবিত হও এবং বেচাকেনা ত্যাগ করো; এটাই তোমাদের জন্য উত্তম, যদি তোমরা জানতে। তারপর নামাজ শেষ হলে পৃথিবীতে ছড়িয়ে পড়ো, আল্লাহর অনুগ্রহ সন্ধান করো এবং আল্লাহকে বেশি বেশি স্মরণ করো, যাতে তোমরা সফল হও (সূরা আল-জুমুআ ৬২:৯-১০)।</p><p>এই আয়াত দুটি একটি সুন্দর ভারসাম্য শেখায়: আজানের সময় সব দুনিয়াবি কাজ থামাতে হবে, আর নামাজের পর আবার হালাল রিজিকের সন্ধানে যাওয়া যায়। জুমা দুনিয়া থেকে পালানো নয়, দুনিয়ার মাঝে আল্লাহকে কেন্দ্রে রাখা।</p><h2>সপ্তাহের শ্রেষ্ঠ দিন</h2><p>রাসূল ﷺ বলেছেন, যেসব দিনে সূর্য উদিত হয়, তার মধ্যে শ্রেষ্ঠ দিন জুমার দিন। এই দিনে আদম (আ.)-কে সৃষ্টি করা হয়েছে, এই দিনে তাঁকে জান্নাতে প্রবেশ করানো হয়েছে, এই দিনে তাঁকে সেখান থেকে বের করা হয়েছে, আর কিয়ামতও এই জুমার দিনেই সংঘটিত হবে (সহীহ মুসলিম ৮৫৪)।</p><h2>জুমা ছেড়ে দেওয়ার ভয়াবহতা</h2><p>প্রাপ্তবয়স্ক, সুস্থ, মুকিম পুরুষদের ওপর জুমার নামাজ ফরজ। রাসূল ﷺ সতর্ক করেছেন, যে ব্যক্তি অবহেলা করে পরপর তিনটি জুমা ছেড়ে দেয়, আল্লাহ তার অন্তরে মোহর মেরে দেন (সুনান আবি দাউদ ১০৫২, জামে তিরমিযী ৫০০)। ব্যবসা, খেলা বা ঘুমের কারণে জুমা ছেড়ে দেওয়া তাই হালকা বিষয় নয়।</p><h2>দুই জুমার মাঝের গুনাহ মাফ</h2><p>রাসূল ﷺ বলেছেন, পাঁচ ওয়াক্ত নামাজ এবং এক জুমা থেকে আরেক জুমা মধ্যবর্তী গুনাহের কাফফারা, যদি কবিরা গুনাহ থেকে বেঁচে থাকা হয় (সহীহ মুসলিম ২৩৩)। আরেক হাদিসে এসেছে, যে ব্যক্তি গোসল করে জুমায় আসে, তার জন্য যতটুকু নির্ধারিত ছিল নামাজ পড়ে, তারপর ইমামের খুতবা শেষ হওয়া পর্যন্ত চুপ থাকে, তারপর ইমামের সাথে নামাজ পড়ে, তার এই জুমা থেকে পরের জুমা পর্যন্ত এবং আরও তিন দিনের গুনাহ মাফ করে দেওয়া হয় (সহীহ মুসলিম ৮৫৭)।</p><h2>জুমার দিনের সুন্নাহ আমল</h2><ul><li><strong>গোসল:</strong> রাসূল ﷺ বলেছেন, তোমাদের কেউ জুমায় এলে সে যেন গোসল করে (সহীহ বুখারী ৮৭৭, সহীহ মুসলিম ৮৪৪)।</li><li><strong>পরিচ্ছন্নতা ও সুগন্ধি:</strong> পরিষ্কার বা সুন্দর পোশাক পরা, সুগন্ধি ব্যবহার করা, মিসওয়াক করা—এগুলো জুমার আদবের অংশ হিসেবে হাদিসে এসেছে।</li><li><strong>আগে আগে মসজিদে যাওয়া:</strong> রাসূল ﷺ বলেছেন, যে ব্যক্তি জুমার দিন গোসল করে প্রথম প্রহরে মসজিদে যায়, সে যেন একটি উট কুরবানি করল; দ্বিতীয় প্রহরে গেলে যেন একটি গরু; তৃতীয় প্রহরে একটি শিংওয়ালা দুম্বা; চতুর্থ প্রহরে একটি মুরগি; পঞ্চম প্রহরে একটি ডিম। আর ইমাম যখন খুতবার জন্য বের হন, ফেরেশতারা খাতা গুটিয়ে খুতবা শুনতে বসে যান (সহীহ বুখারী ৮৮১, সহীহ মুসলিম ৮৫০)। অর্থাৎ খুতবা শুরু হওয়ার পর পৌঁছালে এই বিশেষ সওয়াবের তালিকায় নাম ওঠে না।</li><li><strong>মনোযোগ দিয়ে খুতবা শোনা:</strong> রাসূল ﷺ বলেছেন, ইমাম খুতবা দেওয়ার সময় তুমি যদি তোমার পাশের লোককে বলো "চুপ করো", তবুও তুমি অনর্থক কাজ করলে (সহীহ বুখারী ৯৩৪, সহীহ মুসলিম ৮৫১)। তাহলে খুতবার সময় মোবাইল দেখা বা কথা বলা কতটা অনুচিত, সহজেই বোঝা যায়।</li><li><strong>বেশি বেশি দরুদ:</strong> রাসূল ﷺ বলেছেন, তোমাদের দিনগুলোর মধ্যে শ্রেষ্ঠ দিন জুমার দিন; সুতরাং এ দিনে আমার ওপর বেশি বেশি দরুদ পাঠ করো, কারণ তোমাদের দরুদ আমার কাছে পেশ করা হয় (সুনান আবি দাউদ ১০৪৭)।</li><li><strong>সূরা আল-কাহফ:</strong> জুমার দিন সূরা আল-কাহফ পড়ার ফজিলত সম্পর্কে হাদিস মুস্তাদরাক হাকিম ও বায়হাকিতে বর্ণিত হয়েছে, এবং অনেক আলেম একে আমলযোগ্য বলেছেন। আর সূরা কাহফের প্রথম দশ আয়াত মুখস্থকারী দাজ্জালের ফিতনা থেকে রক্ষা পাবে বলে সহীহ মুসলিমে (৮০৯) এসেছে।</li></ul><h2>দোয়া কবুলের মুহূর্ত</h2><p>রাসূল ﷺ জুমার দিনের কথা উল্লেখ করে বলেছেন, এ দিনে এমন একটি মুহূর্ত আছে, কোনো মুসলিম বান্দা যদি সে সময় নামাজরত অবস্থায় আল্লাহর কাছে কিছু চায়, আল্লাহ তাকে তা দান করেন; এবং তিনি হাত দিয়ে ইঙ্গিত করলেন যে মুহূর্তটি সংক্ষিপ্ত (সহীহ বুখারী ৯৩৫, সহীহ মুসলিম ৮৫২)। এই মুহূর্তটি ঠিক কখন, সে বিষয়ে আলেমদের একাধিক মত আছে; প্রসিদ্ধ দুটি মত হলো ইমামের মিম্বারে বসা থেকে নামাজ শেষ হওয়া পর্যন্ত সময় এবং আসরের পর থেকে সূর্যাস্ত পর্যন্ত সময়। তাই অনেক নেককার মানুষ জুমার দিন আসরের পর মাগরিব পর্যন্ত দোয়া ও জিকিরে কাটান।</p><h2>জুমাকে পারিবারিক ইবাদতের দিন বানান</h2><ul><li><strong>সকালের প্রস্তুতি:</strong> আগের রাতে কাপড় প্রস্তুত রাখুন, সকালে গোসল সেরে ফেলুন, যাতে শেষ মুহূর্তে দৌড়াতে না হয়।</li><li><strong>ছেলেদের সাথে নিয়ে যান:</strong> ছেলে সন্তানদের আগে আগে মসজিদে নিয়ে যান, মসজিদের আদব শেখান। তাদের জন্য এটি সপ্তাহের বিশেষ অভিজ্ঞতা হয়ে উঠবে।</li><li><strong>বাড়ির নারী ও শিশুদের জন্য:</strong> ঘরে সূরা কাহফ তিলাওয়াত, দরুদ পাঠ, আসরের পর দোয়ার আয়োজন করুন।</li><li><strong>খুতবার আলোচনা:</strong> দুপুরের খাবারে খুতবায় কী শুনলেন, পরিবারের সাথে আলোচনা করুন।</li><li><strong>সাপ্তাহিক দান:</strong> জুমার দিন সামান্য হলেও কিছু দান করার অভ্যাস গড়ুন।</li><li><strong>আত্মীয়-অসুস্থদের খোঁজ:</strong> ছুটির দিন হিসেবে বিকেলে আত্মীয় বা অসুস্থ কাউকে দেখতে যান।</li></ul><h2>যারা জুমায় যেতে পারেন না</h2><p>নারী, অসুস্থ, মুসাফির ও যাদের জন্য শরিয়তসম্মত ওজর আছে, তাদের ওপর জুমা ফরজ নয়; তারা জোহরের নামাজ আদায় করবেন। কিন্তু জুমার দিনের অন্যান্য ফজিলত—দরুদ, দোয়া, কুরআন তিলাওয়াত, দোয়া কবুলের মুহূর্ত—সবার জন্য উন্মুক্ত। তাই ঘরে থাকলেও এই দিনটিকে সাধারণ দিনের মতো কাটাবেন না।</p><blockquote>সপ্তাহের ছয়টি দিন দুনিয়ার জন্য; অন্তত একটি দিনের শ্রেষ্ঠ সময়টুকু আল্লাহর জন্য রাখুন।</blockquote><p>এই শুক্রবার থেকে একটি নতুন অভ্যাস শুরু করুন: খুতবা শুরুর অন্তত পনেরো মিনিট আগে মসজিদে পৌঁছানো, অথবা আসরের পর মাগরিব পর্যন্ত দোয়ায় কাটানো। ইসলামিক স্টুডিওর নামাজের সময়সূচিতে আপনার এলাকার জুমার সময় দেখে নিন।</p>', ARRAY['jumuah', 'friday', 'salah', 'sunnah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('b8f9e66d-9f2c-5eb3-9441-4bab79935cc5', 'team', 'Islamic Studio', 'bn', 'রাগ নিয়ন্ত্রণ: প্রকৃত বীরত্ব', 'এক মুহূর্তের রাগে ভাঙে সংসার, নষ্ট হয় সম্পর্ক। রাগ সম্পর্কে নবীজির উপদেশ, রাগ দমনের পুরস্কার, এবং রাগ উঠলে করণীয় সুন্নাহসম্মত ধাপগুলো।', '<p>রাগ মানুষের স্বাভাবিক অনুভূতি। অন্যায় দেখলে রাগ হওয়া এমনকি ঈমানেরও লক্ষণ হতে পারে। কিন্তু নিয়ন্ত্রণহীন রাগ এক ভয়ংকর আগুন। রাগের মাথায় বলা একটি কথায় বহু বছরের সম্পর্ক ভেঙে যায়, রাগের মাথায় নেওয়া একটি সিদ্ধান্তে সারা জীবন আফসোস করতে হয়। স্বামী-স্ত্রীর তালাক, ভাই-ভাইয়ের মামলা, সন্তানের প্রতি নিষ্ঠুরতা—এসবের পেছনে প্রায়ই থাকে কয়েক মুহূর্তের অনিয়ন্ত্রিত রাগ।</p><h2>রাগ কোরো না</h2><p>এক ব্যক্তি রাসূল ﷺ-এর কাছে এসে বলল, আমাকে উপদেশ দিন। তিনি বললেন, রাগ কোরো না। লোকটি কয়েকবার একই অনুরোধ করল, আর প্রতিবারই তিনি বললেন, রাগ কোরো না (সহীহ বুখারী ৬১১৬)। সংক্ষিপ্ত, কিন্তু গভীর উপদেশ। আলেমরা ব্যাখ্যা করেছেন, এর অর্থ রাগের অনুভূতি একেবারে না হওয়া নয়, বরং রাগের কারণগুলো থেকে দূরে থাকা এবং রাগ এলে তার বশীভূত না হওয়া।</p><h2>প্রকৃত শক্তিশালী কে?</h2><p>রাসূল ﷺ বলেছেন, কুস্তিতে অন্যকে হারিয়ে দেওয়া ব্যক্তি শক্তিশালী নয়; প্রকৃত শক্তিশালী সে, যে রাগের সময় নিজেকে নিয়ন্ত্রণ করতে পারে (সহীহ বুখারী ৬১১৪, সহীহ মুসলিম ২৬০৯)। আমাদের সমাজে রাগ দেখানোকে অনেক সময় ব্যক্তিত্ব বা পৌরুষের প্রকাশ মনে করা হয়। ইসলাম ঠিক উল্টো শিক্ষা দেয়: নিজের রাগকে জয় করাই প্রকৃত বীরত্ব।</p><h2>কুরআনে রাগ দমনকারীদের প্রশংসা</h2><p>জান্নাতের দিকে প্রতিযোগিতা করার আহ্বান জানিয়ে আল্লাহ মুত্তাকিদের গুণ বর্ণনা করেছেন: যারা সচ্ছলতা ও অসচ্ছলতায় ব্যয় করে, যারা রাগ দমন করে এবং মানুষকে ক্ষমা করে; আর আল্লাহ সৎকর্মশীলদের ভালোবাসেন (সূরা আলে ইমরান ৩:১৩৪)। এই আয়াতে তিনটি ধাপ লক্ষ করুন: রাগ দমন করা, তারপর ক্ষমা করা, তারপর ইহসান বা উপকার করা। অন্য জায়গায় মুমিনদের গুণ হিসেবে বলা হয়েছে, যখন তারা রাগান্বিত হয়, তখন ক্ষমা করে দেয় (সূরা আশ-শুরা ৪২:৩৭)।</p><p>আর মন্দের জবাব দেওয়ার পদ্ধতি সম্পর্কে আল্লাহ বলেছেন, মন্দকে প্রতিহত করো যা উত্তম তা দিয়ে; তাহলে যার সাথে তোমার শত্রুতা, সে হয়ে যাবে অন্তরঙ্গ বন্ধুর মতো (সূরা ফুসসিলাত ৪১:৩৪)।</p><h2>রাগ দমনের পুরস্কার</h2><p>রাসূল ﷺ বলেছেন, যে ব্যক্তি রাগ কার্যকর করার সামর্থ্য থাকা সত্ত্বেও তা দমন করে, আল্লাহ কিয়ামতের দিন তাকে সমস্ত সৃষ্টির সামনে ডেকে আনবেন এবং তাকে ইচ্ছামতো হুর বেছে নেওয়ার অধিকার দেবেন (সুনান আবি দাউদ ৪৭৭৭, জামে তিরমিযী ২০২১)। লক্ষ করুন, "সামর্থ্য থাকা সত্ত্বেও"—দুর্বলের চুপ থাকা আর ক্ষমতাবানের রাগ দমন করা এক নয়। বস, বাবা-মা, স্বামী, শিক্ষক—যাদের হাতে ক্ষমতা আছে, তাদের জন্য এই হাদিস বিশেষ বার্তা বহন করে।</p><h2>নবীজির সহনশীলতা</h2><p>আনাস (রা.) দশ বছর রাসূল ﷺ-এর খেদমত করেছেন। তিনি বলেন, এই দীর্ঘ সময়ে তিনি কখনো আমাকে "উফ" পর্যন্ত বলেননি; কোনো কাজ করলে বলেননি কেন করলে, আর না করলে বলেননি কেন করলে না (সহীহ বুখারী ৬০৩৮, সহীহ মুসলিম ২৩০৯)। আয়েশা (রা.) বলেছেন, রাসূল ﷺ কখনো নিজের ব্যক্তিগত কারণে প্রতিশোধ নেননি; তবে আল্লাহর নির্ধারিত সীমা লঙ্ঘিত হলে তিনি আল্লাহর জন্য ব্যবস্থা নিতেন (সহীহ বুখারী ৩৫৬০, সহীহ মুসলিম ২৩২৭)। অর্থাৎ তাঁর রাগ ছিল আল্লাহর জন্য, নিজের অহংকারের জন্য নয়।</p><p>রাসূল ﷺ আব্দুল কায়েস গোত্রের নেতা আশাজ্জকে বলেছিলেন, তোমার মধ্যে দুটি গুণ আছে, যা আল্লাহ ভালোবাসেন: সহনশীলতা ও ধীরস্থিরতা (সহীহ মুসলিম ১৭)।</p><h2>রাগ উঠলে কী করবেন?</h2><h3>১. আউযুবিল্লাহ পড়ুন</h3><p>দুই ব্যক্তি রাসূল ﷺ-এর সামনে ঝগড়া করছিল; একজনের চেহারা রাগে লাল হয়ে গিয়েছিল। রাসূল ﷺ বললেন, আমি এমন একটি বাক্য জানি, সে যদি তা বলত, তার রাগ চলে যেত: আউযু বিল্লাহি মিনাশ শাইতানির রাজিম (সহীহ বুখারী ৩২৮২, সহীহ মুসলিম ২৬১০)। রাগ শয়তানের প্ররোচনার একটি বড় দরজা; আল্লাহর আশ্রয় চাওয়া সেই দরজা বন্ধ করে।</p><h3>২. অবস্থান বদলান</h3><p>রাসূল ﷺ বলেছেন, তোমাদের কেউ দাঁড়ানো অবস্থায় রাগান্বিত হলে সে যেন বসে পড়ে; তাতে রাগ চলে গেলে ভালো, নইলে সে যেন শুয়ে পড়ে (সুনান আবি দাউদ ৪৭৮২)। শরীরের অবস্থান বদলালে রাগের তীব্রতা কমে আসে, আর তাৎক্ষণিক আক্রমণাত্মক কাজের সম্ভাবনাও কমে। প্রয়োজনে জায়গা থেকে সরে যান।</p><h3>৩. চুপ থাকুন</h3><p>রাগের সময় বলা কথাই সবচেয়ে বেশি ক্ষতি করে। রাগ উঠলে কথা বলা বন্ধ করুন; মেসেজ লিখে থাকলে পাঠাবেন না। রাগ কমার পর আবার পড়ে দেখুন, এখনো পাঠাতে চান কি না।</p><h3>৪. অজু করুন</h3><p>অনেক আলেম রাগ কমাতে অজু করার পরামর্শ দেন। ঠান্ডা পানি শরীর ও মনকে শান্ত করে, আর অজু মানুষকে মনে করিয়ে দেয় সে আল্লাহর বান্দা।</p><h3>৫. পরিণাম ভাবুন</h3><p>এই মুহূর্তে যা বলতে বা করতে যাচ্ছি, এক সপ্তাহ পর কি তার জন্য গর্বিত হব, নাকি লজ্জিত? এই প্রশ্ন অনেক অনুতাপ থেকে বাঁচায়।</p><h2>রাগের মূল কারণ খুঁজুন</h2><ul><li><strong>অহংকার:</strong> "আমাকে এভাবে বলল!"—অনেক রাগের মূলে থাকে আহত অহং। বিনয় চর্চা রাগ কমায়।</li><li><strong>ক্লান্তি ও ক্ষুধা:</strong> ঘুম কম হলে, ক্ষুধার্ত থাকলে মানুষ সহজে রেগে যায়। নিজের শরীরের যত্ন নিন।</li><li><strong>অবাস্তব প্রত্যাশা:</strong> স্ত্রী, সন্তান বা সহকর্মীর কাছে নিখুঁত আচরণ আশা করলে হতাশা আর রাগ বাড়ে।</li><li><strong>জমে থাকা কষ্ট:</strong> অনেক সময় ছোট ঘটনায় বড় বিস্ফোরণ হয়, কারণ পেছনে জমে থাকে অনেক অপ্রকাশিত কষ্ট। সময়মতো শান্তভাবে কথা বলুন।</li></ul><h2>পরিবারে রাগ</h2><p>সবচেয়ে বেশি রাগ আমরা দেখাই সবচেয়ে কাছের মানুষদের ওপর: স্ত্রী, সন্তান, মা-বাবা। কারণ তাদের কাছে আমরা নিরাপদ বোধ করি। অথচ তাদের প্রতি উত্তম আচরণই আমাদের শ্রেষ্ঠত্বের মাপকাঠি (জামে তিরমিযী ৩৮৯৫)। সন্তানকে রাগের মাথায় শাসন করবেন না; রাগ কমলে শান্তভাবে বোঝান। রাগের মাথায় কখনো তালাকের মতো শব্দ উচ্চারণ করবেন না; অনেক সংসার এভাবেই ভেঙেছে।</p><h2>রাগ যখন আল্লাহর জন্য</h2><p>সব রাগ নিন্দনীয় নয়। অন্যায়, জুলুম বা আল্লাহর বিধানের অবমাননা দেখে মুমিনের অন্তরে যে কষ্ট ও ক্ষোভ জাগে, তা ঈমানের লক্ষণ। কিন্তু সেই রাগও প্রকাশ পাবে শরিয়তের সীমার মধ্যে: ন্যায়ের সাথে, প্রজ্ঞার সাথে, প্রতিশোধপরায়ণতা ছাড়া। রাসূল ﷺ-এর রাগও ছিল এমনই—নিয়ন্ত্রিত, উদ্দেশ্যপূর্ণ এবং কখনো ব্যক্তিগত অহংকারের জন্য নয়।</p><blockquote>রাগের শুরু পাগলামি, আর শেষ অনুতাপ।</blockquote><p>রাগ করে ফেললে, কাউকে কষ্ট দিয়ে ফেললে, দেরি না করে ক্ষমা চেয়ে নিন। ক্ষমা চাওয়া দুর্বলতা নয়, বরং সাহস। আর প্রতিদিন দোয়া করুন, আল্লাহ যেন আমাদের সহনশীলতা ও ধীরস্থিরতার গুণ দান করেন, যা তিনি ভালোবাসেন।</p>', ARRAY['anger', 'akhlaq', 'family', 'tazkiyah']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('49ca7caf-cda3-51cf-adb6-023d1cfb229d', 'team', 'Islamic Studio', 'bn', 'অসুস্থকে দেখতে যাওয়া: জান্নাতের বাগানে হাঁটা', 'রোগীর খোঁজ নেওয়া মুসলিমের হক এবং অসাধারণ সওয়াবের কাজ। অসুস্থকে দেখতে যাওয়ার ফজিলত, নবীজির শেখানো দোয়া, হাসপাতালে ও বাড়িতে রোগী দেখার আদব, আর নিজে অসুস্থ হলে করণীয়।', '<p>অসুস্থতা মানুষকে দুর্বল করে, একা করে। হাসপাতালের বিছানায় বা ঘরের এক কোণে শুয়ে থাকা মানুষটি তখন সবচেয়ে বেশি চায় একটু সঙ্গ, একটু সান্ত্বনা, কেউ এসে বলুক "চিন্তা করবেন না, ইনশাআল্লাহ সুস্থ হয়ে যাবেন"। ইসলাম এই মানবিক প্রয়োজনকে ইবাদতের মর্যাদা দিয়েছে। অসুস্থকে দেখতে যাওয়া, যাকে আরবিতে ইয়াদাহ বলা হয়, একজন মুসলিমের ওপর অপর মুসলিমের হক এবং অত্যন্ত ফজিলতপূর্ণ আমল।</p><h2>মুসলিমের হক</h2><p>রাসূল ﷺ মুসলিমের ওপর মুসলিমের যে পাঁচটি হকের কথা বলেছেন, তার একটি অসুস্থকে দেখতে যাওয়া (সহীহ বুখারী ১২৪০, সহীহ মুসলিম ২১৬২)। অর্থাৎ এটি ঐচ্ছিক সৌজন্য নয়, দায়িত্ব।</p><h2>আল্লাহকে পাওয়া যায় রোগীর পাশে</h2><p>একটি হাদিসে কুদসিতে রাসূল ﷺ জানিয়েছেন, আল্লাহ কিয়ামতের দিন বলবেন, হে আদম সন্তান, আমি অসুস্থ ছিলাম, তুমি আমাকে দেখতে আসোনি। বান্দা বলবে, হে আমার রব, আপনি তো জগৎসমূহের রব, আমি কীভাবে আপনাকে দেখতে যেতাম? আল্লাহ বলবেন, তুমি কি জানতে না, আমার অমুক বান্দা অসুস্থ ছিল, অথচ তুমি তাকে দেখতে যাওনি? তুমি কি জানতে না, যদি তাকে দেখতে যেতে, তবে আমাকে তার কাছেই পেতে (সহীহ মুসলিম ২৫৬৯)?</p><p>এই হাদিস পড়ে মনটা কেঁপে ওঠে। একজন অসুস্থ মানুষের পাশে বসা মানে আল্লাহর রহমতের কাছে বসা।</p><h2>জান্নাতের বাগানে</h2><p>রাসূল ﷺ বলেছেন, কোনো মুসলিম যখন তার অসুস্থ মুসলিম ভাইকে দেখতে যায়, সে ফিরে না আসা পর্যন্ত জান্নাতের ফলের বাগানে থাকে (সহীহ মুসলিম ২৫৬৮)। রোগী দেখতে যাওয়ার পথের প্রতিটি পদক্ষেপ যেন জান্নাতের বাগানে ফল আহরণ।</p><h2>অমুসলিম প্রতিবেশীও</h2><p>রাসূল ﷺ-এর খেদমত করত এক ইহুদি বালক। সে অসুস্থ হলে রাসূল ﷺ তাকে দেখতে গিয়েছিলেন (সহীহ বুখারী ১৩৫৬)। অসুস্থের খোঁজ নেওয়া মানবিকতা; ধর্মের ভিন্নতা এখানে বাধা নয়। অমুসলিম প্রতিবেশী, সহকর্মী বা পরিচিত কেউ অসুস্থ হলে তাকে দেখতে যাওয়া ইসলামের সৌন্দর্যেরই প্রকাশ।</p><h2>রোগীর জন্য নবীজির শেখানো দোয়া</h2><ul><li><strong>সান্ত্বনার বাক্য:</strong> রাসূল ﷺ রোগী দেখতে গেলে বলতেন, লা বা-সা তহুরুন ইনশাআল্লাহ—কোনো অসুবিধা নেই, ইনশাআল্লাহ এটা পবিত্রকারী (গুনাহ মোচনকারী) (সহীহ বুখারী ৩৬১৬)।</li><li><strong>সাতবারের দোয়া:</strong> রাসূল ﷺ বলেছেন, যে ব্যক্তি এমন কোনো অসুস্থকে দেখতে যায় যার মৃত্যু উপস্থিত হয়নি, এবং তার কাছে সাতবার বলে: আসআলুল্লাহাল আজিম, রব্বাল আরশিল আজিম, আঁই ইয়াশফিয়াক—আমি মহান আল্লাহর কাছে চাই, যিনি মহান আরশের রব, তিনি যেন তোমাকে সুস্থ করে দেন; আল্লাহ তাকে সেই অসুস্থতা থেকে আরোগ্য দান করেন (সুনান আবি দাউদ ৩১০৬, জামে তিরমিযী ২০৮৩)।</li><li><strong>রুকইয়ার দোয়া:</strong> রাসূল ﷺ অসুস্থের ওপর হাত বুলিয়ে বলতেন: আজহিবিল বা-স, রব্বান নাস, ইশফি আনতাশ শাফি, লা শিফাআ ইল্লা শিফাউক, শিফাআন লা ইউগাদিরু সাকামা—হে মানুষের রব, কষ্ট দূর করুন, আরোগ্য দিন, আপনিই আরোগ্যদাতা, আপনার আরোগ্য ছাড়া কোনো আরোগ্য নেই; এমন আরোগ্য দিন, যা কোনো রোগ বাকি রাখে না (সহীহ বুখারী ৫৭৪৩, সহীহ মুসলিম ২১৯১)।</li></ul><h2>রোগী দেখার আদব</h2><ul><li><strong>সময় বুঝে যান:</strong> রোগীর বিশ্রাম, খাবার ও ওষুধের সময় এড়িয়ে চলুন। হাসপাতালে গেলে নির্ধারিত দর্শনার্থী সময় মেনে চলুন।</li><li><strong>অল্প সময় থাকুন:</strong> সাধারণত সংক্ষিপ্ত সাক্ষাৎই রোগীর জন্য আরামদায়ক, যদি না রোগী নিজে চান আপনি থাকুন।</li><li><strong>আশার কথা বলুন:</strong> রোগীর সামনে ভয়ের গল্প, অন্য কেউ এই রোগে কীভাবে মারা গেছে, চিকিৎসার খরচ নিয়ে হতাশার কথা—এসব বলবেন না। আল্লাহর রহমত ও সুস্থতার আশার কথা বলুন।</li><li><strong>চিকিৎসা নিয়ে অযাচিত পরামর্শ নয়:</strong> প্রত্যেক দর্শনার্থী নিজের মতো ওষুধ বা টোটকা সাজেস্ট করলে রোগী ও পরিবার বিভ্রান্ত হন। চিকিৎসকের পরামর্শ মানতে উৎসাহ দিন।</li><li><strong>স্বাস্থ্যবিধি মানুন:</strong> সংক্রামক রোগ হলে বা নিজে অসুস্থ থাকলে সরাসরি না গিয়ে ফোনে খোঁজ নিন। শিশু ও দুর্বল রোগীর কাছে যাওয়ার আগে হাত পরিষ্কার করুন।</li><li><strong>ব্যবহারিক সাহায্য:</strong> শুধু ফল নিয়ে যাওয়ার চেয়ে অনেক সময় বেশি উপকারী হলো রোগীর পরিবারের পাশে দাঁড়ানো: হাসপাতালে রাত জাগার পালা নেওয়া, রক্তদাতা খুঁজে দেওয়া, বাচ্চাদের দেখাশোনা, বাজার করে দেওয়া, বা আর্থিক সাহায্য।</li><li><strong>রোগীর কাছে দোয়া চান:</strong> অনেক আলেম বলেছেন, অসুস্থ মানুষের দোয়া কবুলের আশা করা যায়, কারণ তার অন্তর আল্লাহর কাছে বিনীত।</li></ul><h2>যারা দীর্ঘদিন অসুস্থ</h2><p>হঠাৎ অসুস্থ হলে অনেকে দেখতে আসেন, কিন্তু যারা বছরের পর বছর শয্যাশায়ী—বয়স্ক মা-বাবা, প্রতিবন্ধী আত্মীয়, দীর্ঘমেয়াদি রোগী—তাদের খোঁজ নেওয়া ধীরে ধীরে কমে যায়। অথচ তাদের একাকিত্বই সবচেয়ে গভীর। নিয়মিত তাদের কাছে বসা, গল্প করা, তাদের পরিচর্যাকারী পরিবারকে কিছুটা বিশ্রামের সুযোগ করে দেওয়া—এসব অত্যন্ত মূল্যবান সেবা।</p><h2>নিজে অসুস্থ হলে</h2><p>অসুস্থতা শুধু কষ্ট নয়, মুমিনের জন্য তা গুনাহ মোচনের উপায়ও। রাসূল ﷺ বলেছেন, মুসলিমকে যে ক্লান্তি, রোগ, দুশ্চিন্তা, দুঃখ, কষ্ট বা পেরেশানি স্পর্শ করে, এমনকি একটি কাঁটা বিঁধলেও, আল্লাহ এর মাধ্যমে তার গুনাহ মাফ করে দেন (সহীহ বুখারী ৫৬৪১, সহীহ মুসলিম ২৫৭৩)। তিনি আরও বলেছেন, বান্দা যখন অসুস্থ হয় বা সফরে থাকে, তখন সুস্থ ও মুকিম অবস্থায় সে যে আমল করত, তার জন্য সেই আমলের সওয়াব লেখা হতে থাকে (সহীহ বুখারী ২৯৯৬)।</p><ul><li><strong>চিকিৎসা নিন:</strong> রাসূল ﷺ বলেছেন, আল্লাহ এমন কোনো রোগ নাজিল করেননি, যার আরোগ্য নাজিল করেননি (সহীহ বুখারী ৫৬৭৮)। চিকিৎসা নেওয়া তাওয়াক্কুলের পরিপন্থী নয়।</li><li><strong>আইয়ুব (আ.)-এর মতো দোয়া:</strong> দীর্ঘ অসুস্থতায় আইয়ুব (আ.) তাঁর রবকে ডেকে বলেছিলেন, আমি কষ্টে পড়েছি, আর আপনি দয়ালুদের মধ্যে সর্বশ্রেষ্ঠ দয়ালু (সূরা আল-আম্বিয়া ২১:৮৩)। আর ইবরাহিম (আ.) বলেছিলেন, যখন আমি অসুস্থ হই, তখন তিনিই আমাকে আরোগ্য দেন (সূরা আশ-শুআরা ২৬:৮০)।</li><li><strong>ইবাদতে সহজতা:</strong> অসুস্থ অবস্থায় দাঁড়িয়ে নামাজ পড়তে না পারলে বসে, তাও না পারলে শুয়ে পড়ার সুযোগ আছে। অসুস্থতার কারণে নামাজ ছেড়ে দেবেন না; নিজের অবস্থার জন্য প্রযোজ্য নিয়ম আলেমের কাছ থেকে জেনে নিন।</li><li><strong>ধৈর্য ও অভিযোগহীনতা:</strong> কষ্টের কথা বলা দোষের নয়, কিন্তু আল্লাহর ফয়সালার বিরুদ্ধে অভিযোগ নয়।</li></ul><blockquote>আজ যে হাসপাতালের বিছানায়, কাল হয়তো সেখানে আমি। আজ তার পাশে দাঁড়ালে, কাল আল্লাহ আমার পাশে কাউকে দাঁড় করাবেন।</blockquote><p>আপনার পরিচিত কেউ কি এখন অসুস্থ? আজই তাকে দেখতে যান, অথবা অন্তত ফোন করে খোঁজ নিন এবং তার জন্য সাতবার সেই দোয়াটি পড়ুন। হয়তো আপনার এই ছোট্ট সাক্ষাৎই হবে জান্নাতের বাগানে আপনার আজকের হাঁটা।</p>', ARRAY['sick', 'adab', 'sunnah', 'dua']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('e96b857e-9cbe-5d72-acd1-4acfffcec939', 'team', 'Islamic Studio', 'bn', 'সালামের প্রচলন: ভালোবাসার সহজতম পথ', 'আসসালামু আলাইকুম শুধু অভিবাদন নয়, একটি দোয়া ও শান্তির বার্তা। সালামের ফজিলত, কে কাকে আগে সালাম দেবে, জবাবের নিয়ম, ঘরে প্রবেশের সালাম এবং সমাজে সালাম ছড়িয়ে দেওয়ার উপায়।', '<p>"আসসালামু আলাইকুম"—আপনার ওপর শান্তি বর্ষিত হোক। পৃথিবীর অন্যান্য অভিবাদন যেখানে সময় বা আবহাওয়ার কথা বলে, সেখানে মুসলিমদের অভিবাদন একটি দোয়া। প্রতিবার সালাম দেওয়ার সময় আমরা আসলে অপর ভাইয়ের জন্য আল্লাহর কাছে শান্তি, নিরাপত্তা ও কল্যাণ চাই। অথচ এই সুন্দর সুন্নাহ আমাদের সমাজে ধীরে ধীরে সংকুচিত হয়ে আসছে; অনেকে শুধু পরিচিত বা সম্মানিত মানুষকেই সালাম দেন, অনেকে "হাই-হ্যালো" দিয়েই কাজ সারেন।</p><h2>আল্লাহর পক্ষ থেকে অভিবাদন</h2><p>আল্লাহ তাআলা বলেছেন, যখন তোমরা ঘরে প্রবেশ করবে, তখন পরস্পরকে সালাম দেবে; এটি আল্লাহর পক্ষ থেকে বরকতময় ও পবিত্র অভিবাদন (সূরা আন-নূর ২৪:৬১)। আর বলেছেন, যখন তোমাদের অভিবাদন জানানো হয়, তখন তোমরা তার চেয়ে উত্তম অভিবাদন জানাও, অথবা অন্তত সেটাই ফিরিয়ে দাও; নিশ্চয়ই আল্লাহ সবকিছুর হিসাব রাখেন (সূরা আন-নিসা ৪:৮৬)। অন্যের ঘরে প্রবেশের আদব সম্পর্কে আল্লাহ বলেছেন, অনুমতি না নিয়ে এবং ঘরের লোকদের সালাম না দিয়ে প্রবেশ করো না (সূরা আন-নূর ২৪:২৭)।</p><p>জান্নাতেও এই অভিবাদন থাকবে। কুরআনে বারবার এসেছে, জান্নাতবাসীদের সেখানে অভিবাদন হবে সালাম (যেমন সূরা ইউনুস ১০:১০)।</p><h2>জান্নাতে প্রবেশের পথ</h2><p>রাসূল ﷺ বলেছেন, তোমরা জান্নাতে প্রবেশ করতে পারবে না, যতক্ষণ না ঈমান আনো; আর তোমরা পূর্ণ মুমিন হতে পারবে না, যতক্ষণ না পরস্পরকে ভালোবাসো। আমি কি তোমাদের এমন একটি কাজের কথা বলব, যা করলে তোমরা পরস্পরকে ভালোবাসবে? তোমাদের মধ্যে সালামের প্রসার ঘটাও (সহীহ মুসলিম ৫৪)।</p><p>এই হাদিসে একটি চমৎকার শৃঙ্খল আছে: সালাম থেকে ভালোবাসা, ভালোবাসা থেকে ঈমানের পূর্ণতা, আর ঈমান থেকে জান্নাত। সমাজে যে দূরত্ব, সন্দেহ আর বিভেদ, তার একটি সহজ ওষুধ হলো সালাম।</p><h2>পরিচিত-অপরিচিত সবাইকে</h2><p>এক ব্যক্তি রাসূল ﷺ-কে জিজ্ঞেস করল, ইসলামের কোন কাজ উত্তম? তিনি বললেন, তুমি খাবার খাওয়াবে এবং পরিচিত-অপরিচিত সবাইকে সালাম দেবে (সহীহ বুখারী ১২, সহীহ মুসলিম ৩৯)। শুধু পরিচিতদের সালাম দেওয়া এক ধরনের সংকীর্ণতা। লিফটে, রাস্তায়, মসজিদে, অফিসে—অপরিচিত মুসলিম ভাইকেও সালাম দিন।</p><h2>সালামের পূর্ণতা: দশ, বিশ, ত্রিশ</h2><p>এক ব্যক্তি রাসূল ﷺ-এর কাছে এসে বলল, আসসালামু আলাইকুম। তিনি জবাব দিলেন এবং বললেন, দশ। আরেকজন এসে বলল, আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ। তিনি বললেন, বিশ। আরেকজন এসে বলল, আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ। তিনি বললেন, ত্রিশ (সুনান আবি দাউদ ৫১৯৫, জামে তিরমিযী ২৬৮৯)। অর্থাৎ পূর্ণ সালামে বেশি সওয়াব। মাত্র কয়েকটি শব্দ যোগ করলেই সওয়াব তিন গুণ!</p><h2>কে আগে সালাম দেবে?</h2><p>রাসূল ﷺ বলেছেন, আরোহী পথচারীকে সালাম দেবে, পথচারী বসে থাকা ব্যক্তিকে, আর অল্পসংখ্যক অধিকসংখ্যককে (সহীহ বুখারী ৬২৩২, সহীহ মুসলিম ২১৬০)। আরেক বর্ণনায় এসেছে, ছোট বড়কে সালাম দেবে। এগুলো উত্তম পদ্ধতি; তবে কেউ নিয়ম অনুযায়ী আগে সালাম না দিলে অপেক্ষা না করে নিজেই দিয়ে দিন। রাসূল ﷺ বলেছেন, মানুষের মধ্যে আল্লাহর সবচেয়ে নিকটবর্তী সে, যে আগে সালাম দেয় (সুনান আবি দাউদ ৫১৯৭)।</p><p>রাসূল ﷺ নিজে শিশুদের পাশ দিয়ে যাওয়ার সময় তাদের সালাম দিতেন (সহীহ বুখারী ৬২৪৭, সহীহ মুসলিম ২১৬৮)। বড়রা শিশুদের সালাম দিলে শিশুরা সম্মানিত বোধ করে, আর সুন্নাহটি স্বাভাবিকভাবে শিখে নেয়।</p><h2>সালাম ও সম্পর্কের মেরামত</h2><p>দুজন মুসলিমের মধ্যে মনোমালিন্য হলে রাসূল ﷺ বলেছেন, তিন দিনের বেশি কথা বন্ধ রাখা বৈধ নয়, আর তাদের মধ্যে উত্তম সে, যে আগে সালাম দেয় (সহীহ বুখারী ৬০৭৭, সহীহ মুসলিম ২৫৬০)। সালাম তাই শুধু অভিবাদন নয়, ভাঙা সম্পর্ক জোড়া লাগানোর প্রথম সেতু।</p><p>আর সালামের সাথে মুসাফাহা, অর্থাৎ হাত মেলানো সম্পর্কে রাসূল ﷺ বলেছেন, দুজন মুসলিম যখন সাক্ষাতে মুসাফাহা করে, আলাদা হওয়ার আগেই তাদের ক্ষমা করে দেওয়া হয় (সুনান আবি দাউদ ৫২১২, জামে তিরমিযী ২৭২৭)। মুসাফাহা স্বাভাবিকভাবেই পুরুষ-পুরুষ ও নারী-নারীর মধ্যে, শরিয়তের সীমা মেনে।</p><h2>সালামের কিছু আদব</h2><ul><li><strong>স্পষ্ট করে বলুন:</strong> "স্লামালিকুম" বা অস্পষ্ট উচ্চারণ নয়; শব্দগুলো স্পষ্ট ও শুদ্ধ করে বলুন।</li><li><strong>জবাব দেওয়া ওয়াজিব:</strong> কেউ সালাম দিলে জবাব দেওয়া জরুরি, আর উত্তম হলো আরও পূর্ণ করে জবাব দেওয়া।</li><li><strong>ঘরে প্রবেশের সময়:</strong> নিজের ঘরে ঢোকার সময়ও সালাম দিন, এমনকি ঘরে কেউ না থাকলেও।</li><li><strong>ফোন ও মেসেজে:</strong> কথা শুরু করুন সালাম দিয়ে। মেসেজে সংক্ষেপে "AS" বা "slm" না লিখে পুরো সালাম লেখাই উত্তম।</li><li><strong>বিদায়ের সময়:</strong> মজলিস থেকে ওঠার সময়ও সালাম দেওয়া সুন্নাহ।</li><li><strong>ব্যস্ত মানুষকে:</strong> কেউ নামাজ, কুরআন তিলাওয়াত বা জরুরি কাজে ব্যস্ত থাকলে পরিস্থিতি বুঝে আস্তে সালাম দিন, যাতে বিঘ্ন না হয়।</li></ul><h2>অমুসলিমদের সাথে অভিবাদন</h2><p>অমুসলিমদের সাথে অভিবাদন কীভাবে হবে, সে বিষয়ে আলেমদের মধ্যে বিস্তারিত আলোচনা ও কিছু মতভেদ আছে। তবে সবাই একমত যে, তাদের সাথে ভদ্র, আন্তরিক ও সম্মানজনক আচরণ করা ইসলামের শিক্ষা। প্রতিবেশী বা সহকর্মী অমুসলিমকে সৌজন্যমূলক শুভেচ্ছা জানানো, তাদের খোঁজখবর নেওয়া—এসব ইসলামের সৌন্দর্যকে তুলে ধরে। নির্দিষ্ট শব্দচয়ন নিয়ে প্রশ্ন থাকলে নিজের অনুসৃত আলেমের মত জেনে নিন।</p><h2>সালাম একটি দায়িত্বও</h2><p>সালাম দেওয়া মানে অপর ভাইকে নিরাপত্তার প্রতিশ্রুতি দেওয়া: আমার কাছ থেকে তুমি নিরাপদ। তাই যে মুখে সালাম দেয় অথচ কাজে অন্যকে কষ্ট দেয়, গিবত করে বা ঠকায়, সে সালামের মর্ম রক্ষা করে না। রাসূল ﷺ বলেছেন, মুসলিম সেই ব্যক্তি, যার জিহ্বা ও হাত থেকে অন্য মুসলিমরা নিরাপদ (সহীহ বুখারী ১০, সহীহ মুসলিম ৪০)। সালামের শব্দ আর আচরণের বাস্তবতা যখন এক হয়, তখনই সালাম পূর্ণ হয়।</p><h2>সালাম ছড়িয়ে দেওয়ার উপায়</h2><ul><li>নিজের পরিবার থেকে শুরু করুন: সকালে উঠে, ঘরে ঢুকে, ফোনে—সবসময় সালাম।</li><li>অফিসে সহকর্মী, দারোয়ান, পরিচ্ছন্নতাকর্মী—সবাইকে সমানভাবে সালাম দিন।</li><li>শিশুদের সালামের জবাব আন্তরিকভাবে দিন, তাদেরকে আগে সালাম দিন।</li><li>নিজের জন্য একটি লক্ষ্য ঠিক করুন: আজ অন্তত পাঁচজন অপরিচিত মুসলিমকে সালাম দেব।</li></ul><blockquote>সালাম এমন উপহার, যা দিতে টাকা লাগে না, অথচ তা ফেরত আসে দশ গুণ হয়ে।</blockquote><p>এই সুন্নাহটি এত সহজ যে আমরা এর মূল্য ভুলে যাই। আজ থেকে প্রতিটি সাক্ষাৎ, প্রতিটি ফোনকল আর প্রতিটি ঘরে প্রবেশ শুরু করুন পূর্ণ সালাম দিয়ে। হয়তো এই ছোট অভ্যাসটিই আমাদের সমাজে হারিয়ে যাওয়া ভালোবাসা ফিরিয়ে আনবে।</p>', ARRAY['salam', 'adab', 'sunnah', 'akhlaq']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('97d71aa7-06be-5ed6-b97f-9ece19009e50', 'team', 'Islamic Studio', 'bn', 'ঋণ ও লেনদেন: যে বোঝা মৃত্যুর পরও থাকে', 'ঋণ নেওয়া হারাম নয়, কিন্তু তা হালকা বিষয়ও নয়। ঋণ লিখে রাখার কুরআনি নির্দেশ, পরিশোধে গড়িমসির পরিণাম, ঋণগ্রস্তকে সময় দেওয়ার ফজিলত এবং ঋণমুক্ত জীবনের বাস্তব পরামর্শ।', '<p>জীবনের নানা প্রয়োজনে মানুষকে ঋণ নিতে হয়: চিকিৎসা, ব্যবসা, পড়াশোনা, বিপদ। ইসলাম ঋণ নেওয়া নিষেধ করেনি; রাসূল ﷺ নিজেও প্রয়োজনে ঋণ নিয়েছেন এবং উত্তমভাবে পরিশোধ করেছেন। কিন্তু আমাদের সমাজে ঋণ নিয়ে দুটি বিপরীত সমস্যা দেখা যায়। একদিকে বিলাসিতার জন্য, লোক দেখানো অনুষ্ঠানের জন্য সহজেই ঋণ নেওয়া হয়; অন্যদিকে ঋণ নিয়ে তা ফেরত দেওয়ার ব্যাপারে চরম উদাসীনতা। অনেক বন্ধুত্ব আর আত্মীয়তা ভেঙেছে শুধু ধারের টাকা ফেরত না দেওয়ার কারণে।</p><h2>কুরআনের দীর্ঘতম আয়াত</h2><p>কুরআনের সবচেয়ে দীর্ঘ আয়াতটি নামাজ বা রোজা নিয়ে নয়, ঋণ নিয়ে। আল্লাহ বলেছেন, হে মুমিনগণ, যখন তোমরা নির্দিষ্ট মেয়াদের জন্য ঋণের লেনদেন করো, তখন তা লিখে রাখো (সূরা আল-বাকারা ২:২৮২)। আয়াতটিতে বিস্তারিত নির্দেশনা আছে: একজন লেখক ন্যায়ের সাথে লিখবে, ঋণগ্রহীতা নিজে বলে দেবে কী লিখতে হবে, সাক্ষী রাখতে হবে, আর ছোট-বড় যেকোনো ঋণ লিখতে বিরক্ত হওয়া যাবে না।</p><p>এই আয়াত আমাদের একটি গুরুত্বপূর্ণ শিক্ষা দেয়: ঋণ লিখে রাখা অবিশ্বাস নয়, বরং আল্লাহর নির্দেশ। আমাদের সমাজে অনেকে আত্মীয় বা বন্ধুর সাথে ঋণ লিখতে লজ্জা পান, ভাবেন এতে সম্পর্কের অসম্মান হবে। অথচ না লেখার কারণেই পরে ভুল বোঝাবুঝি, ভুলে যাওয়া আর বিবাদ সৃষ্টি হয়। আর মানুষ যেকোনো সময় মারা যেতে পারে; লিখিত না থাকলে উত্তরাধিকারীরা জানতেই পারেন না কার কাছে কত পাওনা বা দেনা।</p><h2>ঋণের ভার: হাদিসের সতর্কবাণী</h2><p>রাসূল ﷺ বলেছেন, মুমিনের আত্মা তার ঋণের সাথে ঝুলন্ত থাকে, যতক্ষণ না তা পরিশোধ করা হয় (জামে তিরমিযী ১০৭৮)। আরও কঠিন কথা: আল্লাহর পথে শহিদের সব গুনাহ মাফ করে দেওয়া হয়, ঋণ ছাড়া (সহীহ মুসলিম ১৮৮৬)। শাহাদাতের মতো সর্বোচ্চ মর্যাদাও ঋণের বোঝা মাফ করে না, কারণ এটি মানুষের হক।</p><p>ইসলামের প্রথম যুগে কোনো মৃত ব্যক্তির জানাজা আনা হলে রাসূল ﷺ জিজ্ঞেস করতেন, তার কি কোনো ঋণ আছে? ঋণ থাকলে এবং পরিশোধের মতো সম্পদ না রেখে গেলে তিনি নিজে জানাজা পড়াতেন না, সাহাবিদের পড়তে বলতেন। পরে যখন আল্লাহ বিজয় দান করলেন, তখন তিনি ঘোষণা দিলেন, কোনো মুমিন ঋণ রেখে মারা গেলে তা পরিশোধের দায়িত্ব আমার (সহীহ বুখারী ২২৯৮)।</p><h2>নিয়তের গুরুত্ব</h2><p>রাসূল ﷺ বলেছেন, যে ব্যক্তি মানুষের সম্পদ পরিশোধের নিয়তে গ্রহণ করে, আল্লাহ তার পক্ষ থেকে তা পরিশোধ করে দেন; আর যে ব্যক্তি তা নষ্ট করার নিয়তে গ্রহণ করে, আল্লাহ তাকে ধ্বংস করে দেন (সহীহ বুখারী ২৩৮৭)। ঋণ নেওয়ার মুহূর্তেই নিয়ত পরিষ্কার রাখুন: আমি এটা ফেরত দেব। আন্তরিক নিয়ত থাকলে আল্লাহ পরিশোধের পথ সহজ করে দেন।</p><h2>সামর্থ্য থাকতে গড়িমসি: জুলুম</h2><p>রাসূল ﷺ বলেছেন, সামর্থ্যবান ব্যক্তির ঋণ পরিশোধে টালবাহানা করা জুলুম (সহীহ বুখারী ২২৮৭, সহীহ মুসলিম ১৫৬৪)। আমাদের চারপাশে এমন অনেক উদাহরণ: নতুন ফোন কেনা হচ্ছে, বেড়ানো হচ্ছে, কিন্তু ধারের টাকা ফেরত দেওয়ার কথা উঠলেই "এখন হাত খালি"। পাওনাদারকে বারবার চাইতে বাধ্য করা, ফোন না ধরা, এড়িয়ে চলা—এসব জুলুমের অন্তর্ভুক্ত।</p><p>রাসূল ﷺ শুধু পরিশোধ নয়, উত্তমভাবে পরিশোধের কথাও বলেছেন: তোমাদের মধ্যে সর্বোত্তম সে, যে ঋণ পরিশোধে সর্বোত্তম (সহীহ বুখারী ২৩০৫, সহীহ মুসলিম ১৬০১)। তিনি নিজে কখনো যে উট ধার নিয়েছিলেন, তার চেয়ে ভালো উট ফেরত দিয়েছেন। শর্তহীনভাবে খুশি হয়ে কিছু বেশি দেওয়া সুন্নাহ; তবে আগে থেকে শর্ত করা বাড়তি সুদের অন্তর্ভুক্ত।</p><h2>দাতার জন্য: সময় দেওয়া ও মাফ করা</h2><p>ঋণদাতার জন্যও ইসলামের সুন্দর নির্দেশনা আছে। আল্লাহ বলেছেন, যদি ঋণগ্রহীতা অভাবগ্রস্ত হয়, তবে সচ্ছলতা পর্যন্ত তাকে অবকাশ দাও; আর যদি মাফ করে দাও, তবে তা তোমাদের জন্য আরও উত্তম, যদি তোমরা জানতে (সূরা আল-বাকারা ২:২৮০)।</p><p>রাসূল ﷺ এক ব্যবসায়ীর কথা বলেছেন, যে মানুষকে ঋণ দিত এবং তার কর্মচারীকে বলত, কোনো অভাবীর কাছে গেলে তাকে ছাড় দিয়ো, হয়তো আল্লাহও আমাদের ছাড় দেবেন। তার মৃত্যুর পর আল্লাহ তাকে ক্ষমা করে দিলেন (সহীহ বুখারী ২০৭৮, সহীহ মুসলিম ১৫৬২)। আরেক হাদিসে এসেছে, যে অভাবী ঋণগ্রহীতাকে অবকাশ দেয় বা ঋণ মাফ করে দেয়, আল্লাহ তাকে সেদিন তাঁর ছায়ায় আশ্রয় দেবেন, যেদিন তাঁর ছায়া ছাড়া আর কোনো ছায়া থাকবে না (সহীহ মুসলিম ৩০০৬)।</p><h2>সুদ থেকে সাবধান</h2><p>ঋণের সাথে সুদের শর্ত যুক্ত হলে বিষয়টি সম্পূর্ণ ভিন্ন হয়ে যায়। আল্লাহ ব্যবসাকে হালাল এবং সুদকে হারাম করেছেন (সূরা আল-বাকারা ২:২৭৫), আর যারা সুদ ছাড়ে না, তাদের বিরুদ্ধে আল্লাহ ও রাসূলের পক্ষ থেকে যুদ্ধের ঘোষণা দিয়েছেন (সূরা আল-বাকারা ২:২৭৮-২৭৯)। ক্রেডিট কার্ড, কিস্তি, অনলাইন লোন—আধুনিক অনেক সুবিধার মধ্যে সুদ লুকিয়ে থাকে। নেওয়ার আগে শর্তগুলো ভালো করে পড়ুন, আর সন্দেহ থাকলে নির্ভরযোগ্য আলেমের পরামর্শ নিন।</p><h2>ঋণ থেকে আশ্রয় চাওয়া</h2><p>রাসূল ﷺ নামাজে প্রায়ই গুনাহ ও ঋণ থেকে আল্লাহর আশ্রয় চাইতেন। কেউ জিজ্ঞেস করল, আপনি ঋণ থেকে এত বেশি আশ্রয় চান কেন? তিনি বললেন, মানুষ যখন ঋণগ্রস্ত হয়, তখন কথা বললে মিথ্যা বলে আর ওয়াদা করলে ভঙ্গ করে (সহীহ বুখারী ৮৩২, সহীহ মুসলিম ৫৮৯)। ঋণ মানুষকে কতটা নৈতিক চাপে ফেলে, এই হাদিস তা স্পষ্ট করে।</p><p>তিনি আরও একটি দোয়া পড়তেন, যার অর্থ: হে আল্লাহ, আমি আপনার কাছে আশ্রয় চাই দুশ্চিন্তা ও দুঃখ থেকে, অক্ষমতা ও অলসতা থেকে, কৃপণতা ও কাপুরুষতা থেকে, এবং ঋণের ভার ও মানুষের দমন থেকে (সহীহ বুখারী ৬৩৬৯)। এই দোয়াটি মুখস্থ করে নিয়মিত পড়ুন।</p><h2>ঋণমুক্ত জীবনের বাস্তব পরামর্শ</h2><ul><li><strong>প্রয়োজন আর ইচ্ছার পার্থক্য:</strong> চিকিৎসা বা জরুরি প্রয়োজনে ঋণ এক বিষয়; নতুন মডেলের ফোন, বিলাসী অনুষ্ঠান বা লোক দেখানোর জন্য ঋণ আরেক বিষয়।</li><li><strong>সব ঋণের তালিকা:</strong> কার কাছে কত, কবে ফেরত দেওয়ার কথা—লিখে রাখুন এবং পরিবারের কাউকে জানিয়ে রাখুন।</li><li><strong>অসিয়তনামায় উল্লেখ:</strong> নিজের দেনা-পাওনার বিবরণ লিখে রাখুন, যাতে মৃত্যুর পর উত্তরাধিকারীরা পরিশোধ করতে পারেন।</li><li><strong>যোগাযোগ বন্ধ করবেন না:</strong> সময়মতো দিতে না পারলে আগেই পাওনাদারকে জানান, নতুন সময় চেয়ে নিন। এড়িয়ে চলা পরিস্থিতিকে আরও খারাপ করে।</li><li><strong>ছোট কিস্তিতে হলেও:</strong> একবারে না পারলে প্রতি মাসে অল্প অল্প করে দিন। এতে আন্তরিকতা প্রকাশ পায়।</li><li><strong>জরুরি তহবিল:</strong> আয়ের একটি অংশ সঞ্চয় করুন, যাতে ছোট বিপদে ঋণ নিতে না হয়।</li></ul><blockquote>ঋণ নেওয়া সহজ, শোধ করা কঠিন; আর না শোধ করে মরা সবচেয়ে কঠিন।</blockquote><p>আজ একটি কাগজে নিজের সব ঋণ ও পাওনার তালিকা করুন। যে ঋণ শোধ করার সামর্থ্য আছে, তা এই সপ্তাহেই শোধ করুন। আর যদি কারও কাছে আপনার পাওনা থাকে এবং সে সত্যিই অভাবী হয়, তাকে সময় দিন, পারলে মাফ করে দিন; হয়তো কিয়ামতের দিন সেটাই আপনার ছায়া হবে।</p>', ARRAY['debt', 'wealth', 'business', 'akhlaq']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_blog_posts (id, source, author_name, language, title, summary, body_html, tags, review_status) VALUES ('b1caa4af-ffbc-5e60-9ca8-0bff90f4eee5', 'team', 'Islamic Studio', 'bn', 'তাহাজ্জুদ: রাতের নীরবতায় রবের সাথে', 'শেষ রাতে আল্লাহ বান্দাকে ডাকেন: কে আছ আমার কাছে চাইবে? তাহাজ্জুদের ফজিলত, নবীজির রাতের নামাজ, শুরু করার সহজ উপায় এবং নিয়মিত রাখার কৌশল।', '<p>রাতের শেষ ভাগ। চারদিক নিস্তব্ধ। শহরের কোলাহল থেমে গেছে, ফোনের নোটিফিকেশন বন্ধ, পরিবারের সবাই ঘুমিয়ে। এমন সময় একজন বান্দা উঠে অজু করে জায়নামাজে দাঁড়ায়। কেউ দেখছে না, কেউ জানছে না; শুধু সে আর তার রব। এই মুহূর্তের নাম তাহাজ্জুদ। যারা একবার এর স্বাদ পেয়েছেন, তারা জানেন, দিনের হাজার ব্যস্ততায় যে প্রশান্তি পাওয়া যায় না, তা পাওয়া যায় এই কয়েকটি রাকআতে।</p><h2>কুরআনে রাতের নামাজ</h2><p>আল্লাহ তাঁর নবীকে বলেছেন, রাতের কিছু অংশে তাহাজ্জুদ পড়ো, এটি তোমার জন্য অতিরিক্ত; আশা করা যায় তোমার রব তোমাকে প্রশংসিত স্থানে পৌঁছাবেন (সূরা আল-ইসরা ১৭:৭৯)। সূরা আল-মুযযাম্মিলের শুরুতে রাতের নামাজের নির্দেশ দিয়ে বলা হয়েছে, নিশ্চয়ই রাতে জাগরণ প্রবৃত্তি দমনে অধিক কার্যকর এবং কথা বলার জন্য অধিক উপযুক্ত (সূরা আল-মুযযাম্মিল ৭৩:১-৬)।</p><p>মুত্তাকিদের বর্ণনায় আল্লাহ বলেছেন, তারা রাতের সামান্য অংশই ঘুমাত, আর শেষ রাতে ক্ষমা প্রার্থনা করত (সূরা আয-যারিয়াত ৫১:১৭-১৮)। রহমানের বান্দাদের সম্পর্কে বলেছেন, তারা রাত কাটায় তাদের রবের উদ্দেশ্যে সিজদায় ও দাঁড়িয়ে (সূরা আল-ফুরকান ২৫:৬৪)। আর মুমিনদের সম্পর্কে বলেছেন, তাদের পার্শ্বদেশ বিছানা থেকে আলাদা থাকে; তারা তাদের রবকে ডাকে ভয় ও আশা নিয়ে (সূরা আস-সাজদা ৩২:১৬)।</p><h2>শেষ রাতের আহ্বান</h2><p>রাসূল ﷺ বলেছেন, আমাদের রব প্রতি রাতে, যখন রাতের শেষ তৃতীয়াংশ বাকি থাকে, তখন দুনিয়ার আসমানে অবতরণ করেন এবং বলেন: কে আছ আমাকে ডাকবে, আমি তার ডাকে সাড়া দেব? কে আছ আমার কাছে চাইবে, আমি তাকে দেব? কে আছ আমার কাছে ক্ষমা চাইবে, আমি তাকে ক্ষমা করব (সহীহ বুখারী ১১৪৫, সহীহ মুসলিম ৭৫৮)?</p><p>ভাবুন তো, প্রতি রাতে এই আহ্বান হচ্ছে, আর আমরা তখন ঘুমিয়ে আছি। আমাদের যত চাওয়া, যত দুশ্চিন্তা, যত গুনাহ—সবকিছুর সমাধানের দরজা প্রতি রাতে খোলা থাকে।</p><h2>ফরজের পর শ্রেষ্ঠ নামাজ</h2><p>রাসূল ﷺ বলেছেন, রমজানের পর শ্রেষ্ঠ রোজা আল্লাহর মাস মুহাররমের রোজা, আর ফরজ নামাজের পর শ্রেষ্ঠ নামাজ রাতের নামাজ (সহীহ মুসলিম ১১৬৩)।</p><h2>নবীজির রাতের নামাজ</h2><p>রাসূল ﷺ রাতে এত দীর্ঘ সময় নামাজে দাঁড়িয়ে থাকতেন যে তাঁর পা ফুলে যেত। আয়েশা (রা.) বললেন, আপনি এমন কেন করছেন, অথচ আল্লাহ আপনার আগের ও পরের সব গুনাহ মাফ করে দিয়েছেন? তিনি বললেন, আমি কি একজন কৃতজ্ঞ বান্দা হব না (সহীহ বুখারী ৪৮৩৭, সহীহ মুসলিম ২৮২০)? তাহাজ্জুদ তাই শুধু চাওয়ার নামাজ নয়, কৃতজ্ঞতারও নামাজ।</p><p>আয়েশা (রা.) আরও বর্ণনা করেছেন, রমজান হোক বা অন্য সময়, রাসূল ﷺ রাতে এগারো রাকআতের বেশি পড়তেন না, তবে সেগুলো এত সুন্দর ও দীর্ঘ হতো যে তার বর্ণনা দেওয়া যায় না (সহীহ বুখারী ১১৪৭, সহীহ মুসলিম ৭৩৮)। আর তিনি বলেছেন, রাতের নামাজ দুই রাকআত দুই রাকআত করে (সহীহ বুখারী ৯৯০, সহীহ মুসলিম ৭৪৯), এবং তোমরা রাতের শেষ নামাজ বিতর বানাও (সহীহ বুখারী ৯৯৮, সহীহ মুসলিম ৭৫১)।</p><h2>শয়তানের তিন গিঁট</h2><p>রাসূল ﷺ বলেছেন, তোমাদের কেউ যখন ঘুমায়, শয়তান তার মাথার পেছনে তিনটি গিঁট দেয়, প্রতিটিতে বলে: তোমার সামনে দীর্ঘ রাত, ঘুমাও। সে যদি জেগে আল্লাহকে স্মরণ করে, একটি গিঁট খুলে যায়; অজু করলে আরেকটি খুলে যায়; আর নামাজ পড়লে সব গিঁট খুলে যায়, এবং সে সকালে প্রফুল্ল ও প্রশান্ত মনে ওঠে; নইলে সে ওঠে কলুষিত মন ও অলসতা নিয়ে (সহীহ বুখারী ১১৪২, সহীহ মুসলিম ৭৭৬)।</p><h2>তাহাজ্জুদের সময়</h2><p>রাতের নামাজের সময় ইশার নামাজের পর থেকে ফজর পর্যন্ত বিস্তৃত। তবে উত্তম হলো রাতের শেষ ভাগ, বিশেষ করে শেষ তৃতীয়াংশ, কারণ এ সময়েই আল্লাহর সেই বিশেষ আহ্বানের কথা হাদিসে এসেছে। যারা শেষ রাতে উঠতে পারবেন কি না নিশ্চিত নন, তারা ঘুমানোর আগে কিছু নফল নামাজ ও বিতর পড়ে নিতে পারেন; এটিও রাতের নামাজের অন্তর্ভুক্ত। আপনার এলাকার রাতের দৈর্ঘ্য অনুযায়ী মাগরিব থেকে ফজর পর্যন্ত সময়কে তিন ভাগ করলে শেষ তৃতীয়াংশ কখন শুরু হয়, তা সহজে হিসাব করা যায়।</p><h2>শুরু করবেন কীভাবে?</h2><ul><li><strong>ছোট শুরু:</strong> প্রথম দিনেই দীর্ঘ নামাজের লক্ষ্য নয়। ফজরের আজানের ২০-৩০ মিনিট আগে উঠে দুই রাকআত পড়ুন, তারপর বিতর (যদি ইশার পর না পড়ে থাকেন), তারপর কিছুক্ষণ দোয়া। এটুকুই যথেষ্ট শুরুর জন্য।</li><li><strong>সপ্তাহে এক-দুই রাত:</strong> প্রথমে বৃহস্পতিবার রাত বা ছুটির আগের রাত দিয়ে শুরু করুন। অভ্যাস হলে ধীরে ধীরে বাড়ান।</li><li><strong>আগে ঘুমান:</strong> ইশার পর অনর্থক জাগরণ কমান। রাত জেগে স্ক্রিন দেখে শেষ রাতে ওঠা প্রায় অসম্ভব।</li><li><strong>নিয়ত করে ঘুমান:</strong> ঘুমানোর আগে আন্তরিকভাবে নিয়ত করুন এবং আল্লাহর কাছে সাহায্য চান। নিয়ত থাকা সত্ত্বেও ঘুম না ভাঙলে আল্লাহ নিয়তের সওয়াব দেবেন, ইনশাআল্লাহ।</li><li><strong>অ্যালার্ম ও সঙ্গী:</strong> অ্যালার্ম দূরে রাখুন। স্বামী-স্ত্রী একে অপরকে জাগিয়ে দিন; রাসূল ﷺ এমন দম্পতির জন্য রহমতের দোয়া করেছেন (সুনান আবি দাউদ ১৩০৮)।</li><li><strong>কুরআন মুখস্থ না থাকলেও:</strong> যেসব ছোট সূরা জানেন, সেগুলো দিয়েই পড়ুন। রুকু-সিজদায় দীর্ঘ সময় তাসবিহ ও দোয়া করুন। সিজদা দোয়ার শ্রেষ্ঠ সময়।</li></ul><h2>তাহাজ্জুদে কী চাইবেন?</h2><p>সব কিছু। দুনিয়া ও আখিরাতের কল্যাণ, গুনাহের ক্ষমা, পরিবারের হিদায়াত, অসুস্থের আরোগ্য, ঋণ থেকে মুক্তি, উম্মাহর কল্যাণ। একটি তালিকা বানিয়ে রাখতে পারেন। আর নিজের ভাষায় মন খুলে কথা বলুন; আল্লাহ সব ভাষা বোঝেন, সব নীরবতাও।</p><h2>নিয়মিত থাকার কৌশল</h2><p>রাসূল ﷺ আব্দুল্লাহ ইবনে আমর (রা.)-কে বলেছিলেন, হে আব্দুল্লাহ, অমুকের মতো হয়ো না, যে রাতে নামাজ পড়ত, তারপর রাতের নামাজ ছেড়ে দিয়েছে (সহীহ বুখারী ১১৫২, সহীহ মুসলিম ১১৫৯)। তাই অল্প হলেও নিয়মিত থাকাই মূল কথা। প্রতি রাতে না পারলে সপ্তাহে নির্দিষ্ট রাতগুলো ঠিক রাখুন। কোনো রাত বাদ পড়লে হতাশ না হয়ে পরের নির্ধারিত রাতে আবার শুরু করুন।</p><blockquote>দিনের মানুষ যা খুঁজে পায় না, রাতের সিজদায় তা পাওয়া যায়।</blockquote><p>এই সপ্তাহে একটি রাত বেছে নিন। ফজরের আজানের আধা ঘণ্টা আগে অ্যালার্ম দিন, উঠে দুই রাকআত পড়ুন, আর তারপর আল্লাহর কাছে নিজের সবচেয়ে বড় চাওয়াটি চান। ইসলামিক স্টুডিওর নামাজের সময় অংশে আপনার এলাকার ফজরের সময় দেখে নিন, আর ইবাদত ট্র্যাকারে তাহাজ্জুদের রাতগুলো চিহ্নিত করুন।</p>', ARRAY['tahajjud', 'qiyam', 'salah', 'dua']::text[], 'in_review') ON CONFLICT (id) DO NOTHING;
